__load("play",{"edison/blackwing":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"Gana por tempo: entra Blackwings baratos (Gale y Bora salen gratis de la mano si ya controlás un Blackwing) y sostiene el campo con trampas.","en":"Wins on tempo: gets cheap Blackwings out (Gale and Bora Special Summon from hand for free if you already control a Blackwing) and holds the board with traps."},{"es":"Cierra con Sincros: Black Rose Dragon limpia el campo y Blackwing Armor Master no se destruye en batalla.","en":"Closes with Synchros: Black Rose Dragon wipes the field and Blackwing Armor Master cannot be destroyed by battle."},{"es":"Gale reduce a la mitad el ATK y la DEF de un monstruo rival: un Blackwing de 1700 o 2000 de ATK pasa por encima de cuerpos grandes.","en":"Gale halves the ATK and DEF of an opposing monster: a 1700 or 2000 ATK Blackwing gets past big bodies."},{"es":"Icarus Attack (tributa un Blackwing) destruye 2 cartas del campo: se usa para abrir camino, no como jugada de todos los turnos.","en":"Icarus Attack (Tribute a Blackwing) destroys 2 cards on the field: it opens a path, it is not a play for every turn."}]},"starters":[{"cards":["Blackwing - Shura the Blue Flame","Blackwing - Gale the Whirlwind"],"route":{"es":"Shura (nivel 4) por invocación normal + Gale (Tuner nivel 3) desde la mano: nivel 7 para Black Rose Dragon o Blackwing Armor Master.","en":"Shura (Level 4) by Normal Summon + Gale (Level 3 Tuner) from hand: Level 7 for Black Rose Dragon or Blackwing Armor Master."}},{"cards":["Blackwing - Sirocco the Dawn"],"route":{"es":"Si el rival tiene un monstruo y vos ninguno, Sirocco se invoca sin tributo y ya presiona con 2000 de ATK.","en":"If your opponent has a monster and you have none, Sirocco is Normal Summoned without a Tribute and already pressures with 2000 ATK."}},{"cards":["Blackwing - Blizzard the Far North"],"route":{"es":"Blizzard (Tuner nivel 2) por invocación normal revive del Cementerio un Blackwing de nivel 4 o menos (por ejemplo un Kalut enviado antes): nivel 6 para un Sincro.","en":"Blizzard (Level 2 Tuner) Normal Summoned revives a Level 4 or lower Blackwing from the GY (for example a Kalut sent earlier): Level 6 for a Synchro."}}],"chokepoints":[{"card":"Royal Oppression","step":"summon","stepText":{"es":"En la invocación especial de Gale, Bora o del Sincro.","en":"On the Special Summon of Gale, Bora or the Synchro."},"loss":{"es":"Anula y destruye la invocación pagando 800 LP. Duele más contra el Sincro: los materiales ya se fueron. Invocá primero lo que no importa.","en":"Negates and destroys the Summon for 800 LP. It hurts most against the Synchro: the materials are already gone. Summon what does not matter first."}},{"card":"Solemn Judgment","step":"summon","stepText":{"es":"En cualquier invocación (también la normal) o al activar una Magia/Trampa.","en":"On any Summon (Normal too) or when a Spell/Trap is activated."},"loss":{"es":"Anula la invocación o la activación pagando la mitad de los LP. No lo gastes en Black Whirlwind: guardá el Sincro para después de ver si lo usan.","en":"Negates the Summon or the activation for half the LP. Do not bait it with Black Whirlwind: keep the Synchro until you see if they use it."}},{"card":"Torrential Tribute","step":"summon","stepText":{"es":"Cuando se invoca un monstruo: ya hay un Blackwing y el Sincro en el campo.","en":"When a monster is Summoned: a Blackwing and the Synchro are already on the field."},"loss":{"es":"Destruye todos los monstruos del campo, los tuyos incluidos. Invocá de a una pieza por vez y no vacíes la mano en un solo turno.","en":"Destroys all monsters on the field, yours included. Summon one piece at a time and do not empty your hand in a single turn."}},{"card":"Mirror Force","step":"attack","stepText":{"es":"En tu declaración de ataque, con varios monstruos en Posición de Ataque.","en":"On your attack declaration, with several monsters in Attack Position."},"loss":{"es":"Destruye todos tus monstruos en Posición de Ataque. Con trampas boca abajo en el campo rival, atacá con un solo monstruo y dejá el resto en Defensa.","en":"Destroys all your Attack Position monsters. With face-down Traps on the opponent's field, attack with a single monster and keep the rest in Defense."}},{"card":"Skill Drain","step":"main","stepText":{"es":"Boca arriba desde antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Anula los efectos de todos los monstruos boca arriba: Sirocco, Shura, Blizzard y la mitad de Gale dejan de funcionar. Se saca con Mystical Space Typhoon o Heavy Storm.","en":"Negates the effects of all face-up monsters: Sirocco, Shura, Blizzard and Gale's halving stop working. Remove it with Mystical Space Typhoon or Heavy Storm."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Royal Oppression","qty":1,"why":{"es":"Trampa para el turno 1: frena las invocaciones especiales del rival en su turno.","en":"A turn 1 Trap: stops the opponent's Special Summons on their turn."}}],"out":[{"card":"Brain Control","qty":1,"why":{"es":"Necesita un monstruo rival boca arriba: yendo primero no tiene objetivo.","en":"It needs a face-up opposing monster: going first it has no target."}}]},"second":{"in":[{"card":"Fissure","qty":2,"why":{"es":"Destruye el monstruo de menor ATK: bueno contra un campo de un solo monstruo.","en":"Destroys the lowest ATK monster: good against a one-monster field."}}],"out":[{"card":"Legacy of Yata-Garasu","qty":2,"why":{"es":"Roba, pero no hace nada en el tablero: yendo segundo hace falta interacción.","en":"It draws, but does nothing on the board: going second you need interaction."}}]}},"updated":"2026-10-26"},"adv/elfnote":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Medius the Pure suma o invoca un Power Patron del Mazo. Elfnote Power Patron sube 3 niveles al monstruo de tu zona central y hace un Sincro al instante; al ir al Cementerio como material, busca una carta Elfnote.","en":"Medius the Pure adds or Special Summons a Power Patron from the Deck. Elfnote Power Patron raises the monster in your center zone by 3 Levels and Synchro Summons right away; sent to the GY as material, it searches an Elfnote card."},{"es":"Lucina, Fortuna y Regina rotan por la zona central de monstruos. Lucina devuelve a la mano un monstruo rival de nivel 6 o menos y Fortuna un Mágica/Trampa boca arriba, ambas como efecto rápido en el turno rival.","en":"Lucina, Fortuna and Regina rotate through the center Main Monster Zone. Lucina returns a Level 6 or lower opposing monster to the hand and Fortuna a face-up Spell/Trap, both as Quick Effects on the opponent's turn."},{"es":"Elfnotes: Welcome Home protege de la destrucción por efecto al monstruo del centro, y Elfnotes: Rhapsodia of Madness impide que ataquen todos los monstruos rivales menos el del centro y, con un Sincro tuyo, niega un efecto rival.","en":"Elfnotes: Welcome Home keeps the center monster from being destroyed by card effects, and Elfnotes: Rhapsodia of Madness stops every opposing monster except the center one from attacking and, with a Synchro of yours, negates an opposing effect."},{"es":"Welcome Home y Power Patron te limitan el Extra Deck a Sincros ese turno: terminá cualquier invocación de otro tipo antes de usarlos.","en":"Welcome Home and Power Patron limit your Extra Deck to Synchros that turn: finish any other kind of Extra Deck Summon before using them."}]},"starters":[{"cards":["Elfnote Lucina"],"route":{"es":"Lucina entra a la zona central desde la mano y suma otra Elfnote del Mazo (Regina o Power Patron, según lo que falte). Es la apertura más flexible: no te encierra en Sincros desde el primer paso.","en":"Lucina goes to the center zone from the hand and adds another Elfnote from the Deck (Regina or Power Patron, whichever you need). The most flexible opener: it does not lock you into Synchros from the first step."}},{"cards":["Medius the Pure","Elfnote Power Patron"],"route":{"es":"Medius suma o invoca Elfnote Power Patron del Mazo. Power Patron sube el nivel del monstruo del centro y hace un Sincro Elfnote; ya como material en el Cementerio, busca una carta Elfnote para seguir.","en":"Medius adds or Special Summons Elfnote Power Patron from the Deck. Power Patron raises the center monster's Level and makes an Elfnote Synchro; as material in the GY it searches an Elfnote card to keep going."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Lucina o la invocación desde el Mazo de Regina.","en":"On Lucina's search or Regina's Special Summon from the Deck."},"loss":{"es":"Niega ese efecto. Una guía de Master Duel Meta sostiene que el mazo juega bien contra Ash e Imperm, así que seguí con Regina (efecto rápido desde la mano) o con Medius en lugar de repetir la misma línea.","en":"Negates that effect. A Master Duel Meta guide says the deck plays through Ash and Imperm well, so continue with Regina (Quick Effect from hand) or Medius instead of repeating the same line."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Justo después de resolverse la primera búsqueda del Mazo (Lucina, Medius o Power Patron).","en":"Right after the first Deck search resolves (Lucina, Medius or Power Patron)."},"loss":{"es":"Ninguna otra carta puede sumarse del Mazo a la mano ese turno: perdés la búsqueda de Power Patron como material. Pasá a jugadas por invocación especial (Regina, Medius) y no cuentes con más búsquedas.","en":"No other card can be added from the Deck to the hand this turn: you lose Power Patron's material search. Switch to Special Summon plays (Regina, Medius) and do not count on more searches."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"Al llegar la quinta invocación del turno (Lucina, Regina, Medius, Power Patron y el Sincro suman rápido).","en":"On the fifth Summon of the turn (Lucina, Regina, Medius, Power Patron and the Synchro add up fast)."},"loss":{"es":"Tributa todos los monstruos boca arriba, los tuyos incluidos: Welcome Home solo frena la destrucción, no el Tributo. Contá las invocaciones y cortá en la cuarta si el tablero ya alcanza.","en":"Tributes every face-up monster, yours included: Welcome Home only stops destruction, not Tribute. Count your Summons and stop at the fourth if the board is already enough."}},{"card":"Mulcharmy Fuwalos","step":"main","stepText":{"es":"En tu Main Phase 1 si empezás primero: el rival no controla cartas y la activa desde la mano.","en":"In your Main Phase 1 when you go first: the opponent controls no cards and activates it from hand."},"loss":{"es":"Cada invocación tuya desde el Mazo o el Extra Deck le da una carta al rival. No te frena la jugada, pero castiga las rutas largas: elegí las de dos cartas.","en":"Each of your Special Summons from the Deck or Extra Deck gives the opponent a card. It does not stop the play, but it punishes long routes: pick the two-card ones."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto de Lucina, Regina o Medius ya en el campo.","en":"In response to the effect of Lucina, Regina or Medius already on the field."},"loss":{"es":"Niega ese efecto y la cadena de búsquedas se corta en el primer eslabón. Dejá una segunda salida en la mano (Regina se invoca como efecto rápido) antes de comprometer la apertura.","en":"Negates that effect and the search chain breaks at the first link. Keep a second exit in hand (Regina Summons herself as a Quick Effect) before committing the opener."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Primera trampa de tu turno 1: frena la invocación o la activación que más duele en el turno rival.","en":"A turn 1 Trap: stops the Summon or activation that hurts most on the opponent's turn."}},{"card":"Skull Meister","qty":2,"why":{"es":"Niega efectos activados en el Cementerio rival: útil contra mazos que se recuperan desde ahí.","en":"Negates effects activated in the opponent's GY: useful against decks that recover from there."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Se activa solo si no controlás cartas: yendo primero, con tablero, queda muerta en la mano.","en":"It only activates if you control no cards: going first, with a board, it sits dead in hand."}},{"card":"Pendulum Treasure","qty":1,"why":{"es":"Pieza de armado lenta; el cupo se usa mejor en interrupción.","en":"A slow setup piece; the slot is better spent on interruption."}}]},"second":{"in":[{"card":"Typhoon","qty":2,"why":{"es":"Destruye una carta boca arriba que te frene los Sincros o la jugada, y se activa desde la mano si el rival tiene 2 o más Mágicas/Trampas y vos ninguna.","en":"Destroys a face-up card that slows your Synchros or your play, and it can be activated from hand if the opponent has 2 or more Spells/Traps and you have none."}}],"out":[{"card":"Pendulum Treasure","qty":2,"why":{"es":"Segundo, tu prioridad es romper el tablero rival, no sumar piezas de armado.","en":"Going second, your priority is breaking the opposing board, not adding setup pieces."}}]}},"updated":"2026-10-26"},"adv/kewl-tune":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Todos los monstruos son Tuners y los Sincros piden casi solo Tuners (Yugipedia). Con Cue, Reco, Mix y Clip se arma una cadena de Sincros que dejan la mano rival y el Mazo expuestos.","en":"Every monster is a Tuner and the Synchros ask almost only for Tuners (Yugipedia). Cue, Reco, Mix and Clip build a chain of Synchros that exposes the opponent's hand and Deck."},{"es":"La interrupción sale al mandar los Tuners al Cementerio como material: Cue excava 2 cartas del Mazo rival y destierra una, Reco destruye un Mágica/Trampa, Mix destruye un monstruo y Clip destierra una carta al azar del Extra Deck rival.","en":"The disruption comes from sending Tuners to the GY as material: Cue excavates 2 cards from the opponent's Deck and banishes one, Reco destroys a Spell/Trap, Mix destroys a monster and Clip banishes a random card from the opponent's Extra Deck."},{"es":"Fydraulis Harmonia es la pieza de interacción en la mano: en el efecto de un monstruo rival se invoca y, mostrando 6 Sincros, destruye un monstruo (a costa de no poder activar efectos de monstruos del Extra Deck que no sean Sincro hasta el final de tu próximo turno).","en":"Fydraulis Harmonia is the interaction piece in hand: on an opposing monster effect it Summons itself and, revealing 6 Synchros, destroys a monster (at the cost of not activating non-Synchro Extra Deck monster effects until the end of your next turn)."},{"es":"Clip y Kewl Tune Remix hacen Sincros en el turno rival; Kewl Tune B2B es la ruta de daño, con segundo ataque para tus Tuners.","en":"Clip and Kewl Tune Remix make Synchros on the opponent's turn; Kewl Tune B2B is the damage route, giving your Tuners a second attack."}]},"starters":[{"cards":["Kewl Tune Cue"],"route":{"es":"Cue por invocación normal invoca a Mix desde el Mazo; Mix suma otro Kewl Tune (que no sea de nivel 2) y con Cue + Mix (2 + 3) se hace Kewl Tune Remix. Al ir como material, Cue excava el Mazo rival y Mix destruye un monstruo.","en":"Cue Normal Summoned Summons Mix from the Deck; Mix adds another Kewl Tune (not Level 2) and Cue + Mix (2 + 3) make Kewl Tune Remix. As material, Cue excavates the opposing Deck and Mix destroys a monster."}},{"cards":["Kewl Tune Reco","JJ \"Kewl Tune\""],"route":{"es":"Reco suma a Mix; JJ \"Kewl Tune\" da una segunda invocación normal para un Tuner, así que Mix entra también y suma otro Kewl Tune. Reco + Mix hacen Remix y Reco, al ser material, destruye un Mágica/Trampa.","en":"Reco adds Mix; JJ \"Kewl Tune\" gives a second Normal Summon for a Tuner, so Mix also comes down and adds another Kewl Tune. Reco + Mix make Remix and Reco, as material, destroys a Spell/Trap."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Reco o Mix, o la invocación de Cue desde el Mazo.","en":"On Reco's or Mix's search, or Cue's Summon from the Deck."},"loss":{"es":"Niega ese efecto. Una sola interacción rara vez para al mazo (notas de Master Duel Meta): ya con Cue en el campo podés reencaminar con otra pieza de la mano o el Cementerio.","en":"Negates that effect. A single interaction rarely stops the deck (Master Duel Meta notes): with Cue already on the field you can reroute through another piece from hand or GY."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera búsqueda del Mazo (Reco, Mix, Track Maker o Kewl Tune Synchro).","en":"After the first Deck search resolves (Reco, Mix, Track Maker or Kewl Tune Synchro)."},"loss":{"es":"Bloquea todas las búsquedas siguientes, y el mazo se apoya en varias. Las notas de Master Duel Meta dicen que a veces lo traba; priorizá invocaciones sin búsqueda como Cue.","en":"Blocks every following search, and the deck leans on several. Master Duel Meta notes say it sometimes stalls it; favor Summons without a search such as Cue."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación del turno: Tuners y Sincros suman muy rápido.","en":"On the fifth Summon of the turn: Tuners and Synchros add up very fast."},"loss":{"es":"Tributa todo tu tablero y deja una ficha enorme del lado rival. Aprendé en qué invocación vas y frená en la cuarta si la mano ya cierra un tablero útil.","en":"Tributes your whole board and leaves a huge token on the opponent's side. Track your Summon count and stop at the fourth if your hand already closes a useful board."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto de Cue, Reco o Mix recién invocados.","en":"In response to the effect of a freshly Summoned Cue, Reco or Mix."},"loss":{"es":"Niega el efecto del Tuner inicial y se pierde la búsqueda o la invocación en cadena. Guardá un segundo Tuner en la mano para rearmar.","en":"Negates the opening Tuner's effect, so the search or chained Summon is lost. Keep a second Tuner in hand to rebuild."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Mannadium Reframing","qty":1,"why":{"es":"Trampa que niega una activación mientras controles un Sincro; Visas Amritara la busca al invocarse (cardsrealm sugiere esa opción yendo primero).","en":"A Trap that negates an activation while you control a Synchro; Visas Amritara searches it when Summoned (cardsrealm suggests that option going first)."}},{"card":"D.D. Crow","qty":2,"why":{"es":"Es un Tuner de nivel 1 que además destierra una carta del Cementerio rival, sin salirse del mazo.","en":"A Level 1 Tuner that also banishes a card from the opponent's GY, without leaving the deck's theme."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Necesita que no controles cartas: yendo primero queda muerta.","en":"It needs you to control no cards: going first it is dead."}},{"card":"The Fallen & The Virtuous","qty":1,"why":{"es":"Sin Albion, solo Ecclesia and the Dark Dragon la habilita en el Extra Deck: una copia alcanza.","en":"Without Albion, only Ecclesia and the Dark Dragon enables it from the Extra Deck: one copy is enough."}}]},"second":{"in":[{"card":"Lightning Storm","qty":1,"why":{"es":"Si no controlás cartas boca arriba, destruye todos los monstruos en Ataque o todas las Mágicas/Trampas rivales.","en":"If you control no face-up cards, destroys all Attack Position monsters or all Spells/Traps the opponent controls."}},{"card":"Illusion Gate","qty":1,"why":{"es":"Destruye todos los monstruos rivales una vez por Duelo y te deja invocar uno de su Cementerio.","en":"Destroys all opposing monsters once per Duel and lets you Summon one from their GY."}},{"card":"Harpie's Feather Duster","qty":1,"why":{"es":"Limita a 1 y limpia el fondo de campo rival cuando vas segundo y el mazo sufre contra tableros armados.","en":"Limited to 1 and clears the opposing backrow when you go second and the deck struggles against built boards."}}],"out":[{"card":"The Fallen & The Virtuous","qty":2,"why":{"es":"Sin Albion es la carta menos fiable del Main; mejor un rompe-tableros.","en":"Without Albion it is the least reliable Main Deck card; a board breaker is better."}},{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Se cede una interrupción chica a cambio de poder romper el tablero.","en":"You give up a small interruption in exchange for being able to break the board."}}]}},"updated":"2026-10-26"},"adv/branded":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Es un mazo de Fusión basado en Mágicas y Trampas: Aluber, Springans Kitt y Albion the Shrouded Dragon llevan a Branded Fusion y al resto de la familia (Yugipedia).","en":"A Spell and Trap based Fusion deck: Aluber, Springans Kitt and Albion the Shrouded Dragon lead to Branded Fusion and the rest of the family (Yugipedia)."},{"es":"Fallen of Albaz fusiona con monstruos de cualquier campo: incluso arrastra a los del rival. Lubellion encadena otra Fusión descartando una carta.","en":"Fallen of Albaz fuses with monsters from either field, taking the opponent's along. Lubellion chains another Fusion by discarding a card."},{"es":"Mirrorjade destierra un monstruo por turno como efecto rápido; Granguignol responde a una invocación rival trayendo un Dogmatika o un Despia, y los Albaz del Cementerio sostienen el desgaste.","en":"Mirrorjade banishes a monster each turn as a Quick Effect; Granguignol answers an opposing Summon by bringing a Dogmatika or Despia, and Albaz monsters in the GY keep the grind going."},{"es":"Branded Retribution niega una activación que invoque algo, devolviendo una Fusión al Extra Deck, y Super Polymerization responde a tableros con una Fusión que no se puede encadenar.","en":"Branded Retribution negates an activation that Summons something by returning a Fusion to the Extra Deck, and Super Polymerization answers boards with a Fusion nobody can chain to."}]},"starters":[{"cards":["Aluber the Jester of Despia"],"route":{"es":"Aluber suma una Mágica/Trampa Branded (en general Branded Fusion o Branded Opening) y desde ahí se arma la primera Fusión con Fallen of Albaz.","en":"Aluber adds a Branded Spell/Trap (usually Branded Fusion or Branded Opening) and the first Fusion with Fallen of Albaz builds from there."}},{"cards":["Nadir Servant","Fallen of Albaz"],"route":{"es":"Nadir Servant manda un monstruo del Extra Deck al Cementerio y suma a Fallen of Albaz (o a un Dogmatika) con ATK igual o menor; Albaz, al invocarse, descarta una carta y hace una Fusión con monstruos de ambos campos.","en":"Nadir Servant sends an Extra Deck monster to the GY and adds Fallen of Albaz (or a Dogmatika) with equal or lower ATK; Albaz, when Summoned, discards a card and Fusion Summons with monsters from both fields."}},{"cards":["Branded Opening"],"route":{"es":"Branded Opening descarta una carta y toma a un Despia (Aluber) del Mazo, a la mano o invocado en Defensa; es la entrada cuando no hay Aluber en la mano.","en":"Branded Opening discards a card and takes a Despia (Aluber) from the Deck, to the hand or Summoned in Defense; it is the entry when Aluber is not in hand."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre el efecto de Aluber o de Branded Fusion.","en":"On the effect of Aluber or Branded Fusion."},"loss":{"es":"Niega el efecto, y según Yugipedia eso recorta mucho las jugadas porque Branded Lost no protege contra esta forma de negación. Super Polymerization (no se puede responder) es la salida.","en":"Negates the effect, and per Yugipedia that cuts the plays a lot because Branded Lost does not protect against this kind of negation. Super Polymerization (cannot be responded to) is the way around it."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera búsqueda de Aluber o de Springans Kitt.","en":"After Aluber's or Springans Kitt's first search resolves."},"loss":{"es":"Se cortan las demás búsquedas del Mazo (Nadir Servant incluida). Construí el turno con lo que ya tenés en la mano y los Albaz del Cementerio.","en":"Every other Deck search is cut (Nadir Servant included). Build the turn from what is already in hand and the Albaz monsters in the GY."}},{"card":"Dominus Impulse","step":"activation","stepText":{"es":"Al activar Branded Fusion o el efecto de Fallen of Albaz, que invocan monstruos.","en":"When activating Branded Fusion or Fallen of Albaz's effect, which Summon monsters."},"loss":{"es":"Niega el efecto que invoca y, si tiene una Trampa en el Cementerio, destruye la carta. Desde la mano también bloquea LIGHT, EARTH y WIND para el resto del Duelo. Ante dos negaciones posibles, abrí con Super Polymerization.","en":"Negates the Summoning effect and, with a Trap in the GY, destroys the card. From hand it also locks LIGHT, EARTH and WIND for the rest of the Duel. Against two possible negations, open with Super Polymerization."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En respuesta al efecto que apunta a un Albaz o a un monstruo Fusión en el Cementerio.","en":"In response to the effect that targets an Albaz or a Fusion Monster in the GY."},"loss":{"es":"Destierra el objetivo y la recuperación se cae: Guiding Quem, Branded Retribution y las recuperaciones de Dogmatika dependen del Cementerio, según Yugipedia el punto débil de la ventaja del mazo.","en":"Banishes the target and the recovery fails: Guiding Quem, Branded Retribution and the Dogmatika recoveries rely on the GY, which per Yugipedia is the weak spot of the deck's advantage."}},{"card":"Non-Fusion Area","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Nadie puede invocar por Fusión: el mazo se queda sin su motor. Hay que quitarla con Mystical Space Typhoon o Typhoon; sin ellas la mano se juega con Fallen of the White Dragon y los Ecclesia de a uno.","en":"Nobody can Fusion Summon: the deck loses its engine. Remove it with Mystical Space Typhoon or Typhoon; without them the hand plays out with Fallen of the White Dragon and the Ecclesia monsters one by one."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Mistaken Arrest","qty":2,"why":{"es":"Impide que el rival sume cartas del Mazo en su turno; tené presente que también corta tus búsquedas hasta el final de tu turno siguiente.","en":"Stops the opponent from adding cards from the Deck on their turn; remember it also cuts your own searches until the end of your next turn."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Se activa solo si no controlás cartas: yendo primero tenés tablero.","en":"It only activates if you control no cards: going first you have a board."}}]},"second":{"in":[{"card":"Typhoon","qty":2,"why":{"es":"Branded no tiene respuesta propia a un fondo de campo boca arriba como Non-Fusion Area (ygoprodeck); Typhoon la destruye.","en":"Branded has no built-in answer to a face-up backrow such as Non-Fusion Area (ygoprodeck); Typhoon destroys it."}}],"out":[{"card":"Gold Sarcophagus","qty":1,"why":{"es":"Tarda dos turnos en dar su carta; yendo segundo necesitás efecto inmediato.","en":"It takes two turns to give its card; going second you need immediate effect."}},{"card":"Cocatorium the Heavy Metal Avian","qty":1,"why":{"es":"Pieza de engine de nicho que cede su lugar a una carta de respuesta.","en":"A niche engine piece that gives its slot to an answer."}}]}},"updated":"2026-10-26"},"adv/maliss":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Los Maliss se auto-destierran para llenar el campo de material de Link: casi todos se invocan de nuevo del destierro por 300 LP (los Link por 900), y el Extra Deck queda limitado a Links (Yugipedia).","en":"Maliss monsters banish themselves to fill the field with Link material: nearly all come back from the banishment for 300 LP (the Links for 900), and the Extra Deck is limited to Links (Yugipedia)."},{"es":"Maliss in Underground destierra una carta Maliss al activarse, y con 3 Trampas Maliss distintas desterradas los Link Maliss ganan 3000 ATK; además los monstruos rivales solo pueden atacar a esos Link.","en":"Maliss in Underground banishes a Maliss card when activated, and with 3 different Maliss Traps banished the Maliss Links gain 3000 ATK; opposing monsters can only attack those Links."},{"es":"Maliss <Q> Hearts Crypter destierra una carta del campo como efecto rápido y no se puede negar mientras apunte a un monstruo; Allied Code Talker @Ignister suma una negación con destierro.","en":"Maliss <Q> Hearts Crypter banishes a card on the field as a Quick Effect and cannot be negated while it points to a monster; Allied Code Talker @Ignister adds a negate with a banish."},{"es":"Cyberse Wicckid y Backup @Ignister dan la salida cuando no hay Maliss en la mano; Maliss in the Mirror niega un monstruo y recupera una carta Maliss del mismo tipo cuando se destierra.","en":"Cyberse Wicckid and Backup @Ignister give the exit when there is no Maliss in hand; Maliss in the Mirror negates a monster and recovers a same-type Maliss card when banished."}]},"starters":[{"cards":["Maliss in Underground"],"route":{"es":"Al activarse destierra un Maliss <P> del Mazo, que paga 300 LP y se invoca solo: ya tenés un cuerpo para Link Summon. Es la ruta más corta, y encadena con White Rabbit, Dormouse o March Hare.","en":"On activation it banishes a Maliss <P> from the Deck, which pays 300 LP and Summons itself: you already have a body for a Link Summon. The shortest route, chaining with White Rabbit, Dormouse or March Hare."}},{"cards":["Cyberse Wicckid","Backup @Ignister"],"route":{"es":"Wicckid (2 Cyberse) destierra un Cyberse del Cementerio al invocarse algo en su zona y suma a Backup @Ignister (Tuner Cyberse); Backup, al normal o especial, suma un Cyberse OSCURO del Mazo, sea un Maliss, y descarta una carta.","en":"Wicckid (2 Cyberse) banishes a Cyberse from the GY when something is Summoned to its zone and adds Backup @Ignister (a Cyberse Tuner); Backup, Normal or Special Summoned, adds a DARK Cyberse (a Maliss) from the Deck and discards a card."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Backup @Ignister o de Wicckid.","en":"On the search of Backup @Ignister or Wicckid."},"loss":{"es":"Niega la búsqueda que lleva a la ruta de Maliss. Si Ash cae en Backup, retomá con Maliss in Underground y el destierro propio, que no es una búsqueda.","en":"Negates the search that leads into the Maliss route. If Ash hits Backup, resume with Maliss in Underground and its own banishing, which is not a search."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera suma del Mazo (Backup, Wicckid o Maliss in the Mirror).","en":"After the first add from the Deck (Backup, Wicckid or Maliss in the Mirror)."},"loss":{"es":"Frena el resto de las búsquedas (Wicckid, Backup, Maliss in the Mirror). Abrí con Maliss in Underground, que destierra y no busca nada.","en":"Stops the rest of the searches (Wicckid, Backup, Maliss in the Mirror). Open with Maliss in Underground, which banishes and searches nothing."}},{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a Maliss in Underground o a cualquier efecto que destierre.","en":"In response to Maliss in Underground or any effect that banishes."},"loss":{"es":"Nadie puede desterrar cartas ese turno y se apaga el motor Maliss. Yugipedia lo cita junto a Chaos Hunter e Imperial Iron Wall. Con Lancea en mano rival, jugá las ramas que no destierran (Backup, Wicckid).","en":"Neither player can banish cards this turn and the Maliss engine shuts off. Yugipedia lists it alongside Chaos Hunter and Imperial Iron Wall. Against Lancea in hand, play the branches that do not banish (Backup, Wicckid)."}},{"card":"Imperial Iron Wall","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Nadie puede desterrar: ni Maliss in Underground ni los efectos de Link funcionan. Se saca con Typhoon o Cosmic Cyclone; sin respuestas, el turno se juega con Ignister y Ars Magna.","en":"Nobody can banish: neither Maliss in Underground nor the Link effects work. Remove it with Typhoon or Cosmic Cyclone; without answers, play the turn with Ignister and Ars Magna."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre el efecto de un Link Maliss o de Allied Code Talker ya en el campo.","en":"On the effect of a Maliss Link or Allied Code Talker already on the field."},"loss":{"es":"Niega el efecto del Link y deja el tablero sin su interacción. Con Maliss in the Mirror en el Cementerio, el Maliss desterrado al responder suma la carta que falta.","en":"Negates the Link's effect and leaves the board without its interaction. With Maliss in the Mirror in the GY, the banished Maliss adds the card you need."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Dominus Impulse","qty":3,"why":{"es":"Todos los Maliss son OSCUROS, así que su bloqueo de LIGHT, EARTH y WIND desde la mano no te toca y frena las invocaciones del rival.","en":"All Maliss are DARK, so its LIGHT, EARTH and WIND lock from hand does not affect you and it stops the opponent's Summons."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":3,"why":{"es":"Se activa solo sin cartas propias: yendo primero queda en la mano sin uso.","en":"It only activates with no cards of your own: going first it stays unused in hand."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":2,"why":{"es":"Niega los efectos de todos los monstruos rivales por un turno y evita el daño; arma el turno donde el motor Maliss sufre contra un tablero armado.","en":"Negates every opposing monster effect for a turn and prevents damage; it sets up the turn where the Maliss engine struggles against a built board."}}],"out":[{"card":"Gold Sarcophagus","qty":1,"why":{"es":"Tarda dos turnos, demasiado para un mazo que necesita romper el tablero ya.","en":"Takes two turns, too slow for a deck that needs to break the board now."}},{"card":"Terraforming","qty":1,"why":{"es":"Carta lenta que no empuja el turno de quiebre.","en":"A slow card that does not push the board-breaking turn."}}]}},"updated":"2026-10-26"},"adv/invoked":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"El motor original: Aleister the Invoker busca Invocation, Invocation hace la Fusión desterrando material de la mano, el campo y los Cementerios, y al volver al Mazo trae de nuevo a Aleister (Yugipedia).","en":"The original engine: Aleister the Invoker searches Invocation, Invocation Fusion Summons with material from hand, field and GYs, and returning to the Deck brings Aleister back (Yugipedia)."},{"es":"Aiwass, Aleister the Reminiscent y Virakam sostienen la búsqueda y la invocación propias; Magical Meltdown hace que las Fusiones del mazo no se puedan negar ni responder.","en":"Aiwass, Aleister the Reminiscent and Virakam sustain the searching and self-Summons; Magical Meltdown makes the deck's Fusions impossible to negate or respond to."},{"es":"Invoked Mechaba (Aleister + LIGHT) niega y destierra una carta descartando una del mismo tipo; Raidjin voltea un monstruo y Augoeides destruye lo que invoca el rival.","en":"Invoked Mechaba (Aleister + LIGHT) negates and banishes a card by discarding one of the same type; Raidjin flips a monster face-down and Augoeides destroys what the opponent Summons."},{"es":"Hyperinvoked Aeon (2 Fusiones de distinto atributo) destierra tantas cartas como materiales y puede quitar hasta 3 del Extra Deck rival.","en":"Hyperinvoked Aeon (2 Fusions of different Attributes) banishes as many cards as materials and can remove up to 3 from the opposing Extra Deck."}]},"starters":[{"cards":["Aleister the Reminiscent"],"route":{"es":"Se invoca de la mano sobre un Hechicero o una Fusión del campo, y al invocarse destierra un Invoked del Extra Deck y suma Invocation (o una Mágica que la mencione). Es una apertura de una sola carta.","en":"Summons itself from hand onto a Spellcaster or Fusion on the field, and when Summoned banishes an Invoked from the Extra Deck and adds Invocation (or a Spell that mentions it). A one-card opener."}},{"cards":["Magical Meltdown","Aleister the Invoker"],"route":{"es":"Magical Meltdown suma a Aleister the Invoker; invocarlo por normal busca Invocation, y con la Fusión resultante nadie puede responder porque Meltdown ya blindó la activación.","en":"Magical Meltdown adds Aleister the Invoker; Normal Summoning it searches Invocation, and nobody can respond to the resulting Fusion because Meltdown already shielded the activation."}},{"cards":["Aiwass, Divine Spirit of the Law"],"route":{"es":"Aiwass se destierra de la mano y suma a cualquier Aleister; si lo hacés desde el campo, además permite una invocación normal extra de un Spellcaster.","en":"Aiwass banishes itself from hand and adds any Aleister; from the field, it also allows an extra Normal Summon of a Spellcaster."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del Mazo (Aleister the Invoker o Aleister the Reminiscent).","en":"After the first Deck search (Aleister the Invoker or Aleister the Reminiscent)."},"loss":{"es":"Impide buscar Invocation salvo que la hayas robado (Yugipedia). Abrí con Invocation en mano, o con Virakam o Crowley si el rival ya mostró Droll.","en":"Stops you from searching Invocation unless you drew it (Yugipedia). Open with Invocation in hand, or with Virakam or Crowley if the opponent already showed Droll."}},{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Aleister the Invoker o de Invoked Baybarron.","en":"On the search of Aleister the Invoker or Invoked Baybarron."},"loss":{"es":"Yugipedia dice que una interrupción 1 a 1 como Ash frena el motor salvo que Invocation salga de la mano, y que es más fuerte contra Invoked Baybarron. Tené Meltdown o Sacred Spirit Sword Aiwass como segunda ruta.","en":"Yugipedia says a one-for-one interruption such as Ash stops the engine unless Invocation comes from hand, and that it is strongest against Invoked Baybarron. Keep Meltdown or Sacred Spirit Sword Aiwass as a second route."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto de Aleister que busca Invocation.","en":"In response to the Aleister effect that searches Invocation."},"loss":{"es":"Niega el efecto de Aleister y se pierde la búsqueda. Meltdown protege las Fusiones, no a Aleister: tené lista una segunda búsqueda (Reminiscent o Virakam).","en":"Negates Aleister's effect and the search is lost. Meltdown protects the Fusions, not Aleister: keep a second search ready (Reminiscent or Virakam)."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En cuanto Aleister the Invoker queda en el Cementerio, antes de que Invocation lo tome como material.","en":"As soon as Aleister the Invoker sits in the GY, before Invocation takes it as material."},"loss":{"es":"Destierra a Aleister del Cementerio y la Fusión pierde material o el regreso por el efecto de Invocation. Yugipedia nombra a Bystial, Mudora y D.D. Crow como el mismo problema.","en":"Banishes Aleister from the GY and the Fusion loses material or the return through Invocation's effect. Yugipedia names Bystial, Mudora and D.D. Crow as the same problem."}},{"card":"Non-Fusion Area","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1.","en":"Face-up before your Main Phase 1."},"loss":{"es":"Nadie puede invocar por Fusión, así que ni Invocation ni Super Polymerization funcionan. Yugipedia lo cita con Dimensional Barrier y Fossil Dyna Pachycephalo; tené Typhoon o una Mágica de destrucción en el Side.","en":"Nobody can Fusion Summon, so neither Invocation nor Super Polymerization works. Yugipedia cites it with Dimensional Barrier and Fossil Dyna Pachycephalo; keep Typhoon or a destruction Spell in the Side."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Frena la invocación o la activación del turno rival.","en":"Stops the opponent's Summon or activation on their turn."}},{"card":"Effect Veiler","qty":2,"why":{"es":"Niega el efecto de un monstruo rival en su Main Phase desde la mano.","en":"Negates an opposing monster's effect during their Main Phase from hand."}}],"out":[{"card":"Mulcharmy Purulia","qty":3,"why":{"es":"Seis Mulcharmy en total, y yendo primero no se pueden activar con tablero.","en":"Six Mulcharmies in total, and going first they cannot be activated with a board."}}]},"second":{"in":[{"card":"Nibiru, the Primal Being","qty":2,"why":{"es":"Contra un tablero que invoca 5 veces, tributa todo; Invoked no tiene tablero que perder yendo segundo.","en":"Against a board that Summons 5 times, tributes everything; Invoked has no board to lose going second."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Con 3 Fuwalos y 3 Purulia, recortar dos copias para meter una respuesta de un solo gesto.","en":"With 3 Fuwalos and 3 Purulia, trimming two copies to add a one-card answer."}}]}},"updated":"2026-10-26"},"adv/angelechy":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Los monstruos Angelechy van a la Zona de Mágicas y Trampas como Mágicas Continuas y desde ahí hacen de floodgate: Castellan limita a 1 activación por cadena, Shatranga a 5 efectos de monstruo por turno y Destrier inflige 500 por cada activación rival.","en":"Angelechy monsters go to the Spell & Trap Zone as Continuous Spells and act as floodgates from there: Castellan limits to 1 activation per Chain, Shatranga to 5 monster effects per turn and Destrier inflicts 500 for each opposing activation."},{"es":"Angelechy Opening to e4 se activa desde la mano en la Standby Phase del primer turno rival si él empieza: pone el Campo, invoca un Angelechy de nivel 2 o 7 y coloca otro en la Zona de Mágicas. Yugipedia indica que el mazo está pensado para ir segundo.","en":"Angelechy Opening to e4 activates from hand in the opponent's first Standby Phase if they go first: it places the Field Spell, Summons a Level 2 or 7 Angelechy and puts another in the Spell & Trap Zone. Yugipedia says the deck is meant to go second."},{"es":"Angelechy Verdict con 5 o más monstruos Angelechy en el campo destierra todas las cartas rivales; Angelechy Bastion protege de la destrucción por efecto a las demás.","en":"Angelechy Verdict with 5 or more Angelechy Monster Cards on the field banishes all of the opponent's cards; Angelechy Bastion protects the others from destruction by card effects."}]},"starters":[{"cards":["Angelechy Opening to e4"],"route":{"es":"Yendo segundo, se activa desde la mano en la Standby Phase rival y arma todo antes de que el rival juegue su turno 2. Después no podés invocar del Extra Deck salvo Sincros.","en":"Going second, it activates from hand in the opponent's Standby Phase and builds the board before they play turn 2. Afterward you cannot Special Summon from the Extra Deck except Synchros."}},{"cards":["Angelechy Problem"],"route":{"es":"Una vez por turno, descartá una Mágica/Trampa para invocar un Angelechy de nivel 2 del Extra Deck y poner otro Angelechy como Mágica Continua; es el arranque de cualquier mano con el Campo.","en":"Once per turn, discard a Spell/Trap to Summon a Level 2 Angelechy from the Extra Deck and place another Angelechy as a Continuous Spell; the opener for any hand with the Field Spell."}},{"cards":["Witness of the Ancient","Glitch Clutch Nullgainer"],"route":{"es":"Witness (nivel 8 Tuner) permite entrar al arquetipo desde cualquier ruta de Sincro de nivel 8; Glitch Clutch Nullgainer es el puente. Sirve cuando no tenés el Opening to e4.","en":"Witness (a Level 8 Tuner) lets any Level 8 Synchro route enter the archetype, with Glitch Clutch Nullgainer as the bridge. It works when you do not have Opening to e4."}}],"chokepoints":[{"card":"Cosmic Cyclone","step":"main","stepText":{"es":"Contra un Angelechy puesto como Mágica Continua.","en":"Against an Angelechy placed as a Continuous Spell."},"loss":{"es":"Destierra la carta en vez de destruirla, así que Angelechy Bastion no la protege (Yugipedia). Perdés el floodgate que sostenía ese monstruo; reponelo con Brilliant Move o Strategy Score.","en":"Banishes the card instead of destroying it, so Angelechy Bastion does not protect it (Yugipedia). You lose the floodgate that monster held; replace it with Brilliant Move or Strategy Score."}},{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda de Angelechy Strategy Score o de Destrier.","en":"On the search of Angelechy Strategy Score or Destrier."},"loss":{"es":"Niega la búsqueda de la Mágica/Trampa Angelechy. El mazo juega con pocos monstruos de Main, así que seguí con Problem o con la mano que ya tenías en lugar de repetir la misma carta.","en":"Negates the search of the Angelechy Spell/Trap. The deck plays few Main Deck monsters, so continue with Problem or the hand you already have instead of repeating the same card."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda (Strategy Score, Destrier o Shatranga).","en":"After the first search (Strategy Score, Destrier or Shatranga)."},"loss":{"es":"Corta las siguientes búsquedas del Mazo. Las cartas Angelechy que se recuperan desde el Cementerio (Disturbance, Verdict) no pasan por esta cadena y siguen disponibles.","en":"Cuts the next Deck searches. The Angelechy cards that recover from the GY (Disturbance, Verdict) do not go through this chain and stay available."}},{"card":"Solemn Warning","step":"activation","stepText":{"es":"Sobre la activación de Angelechy Opening to e4 en la Standby Phase (invoca monstruos).","en":"On the activation of Angelechy Opening to e4 in the Standby Phase (it Summons monsters)."},"loss":{"es":"Paga 2000 LP, niega la activación y la destruye: perdés el arranque del turno. Si el rival va primero con Trampas Seteadas, tené otra salida lista (Problem, Witness).","en":"Pays 2000 LP, negates the activation and destroys it: you lose the turn opening. If the opponent goes first with Set Traps, have another exit ready (Problem, Witness)."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Chaospawn Bishop","qty":3,"why":{"es":"Dos de nivel 4 hacen un Sincro de nivel 8 (Glitch Clutch Nullgainer) sin necesitar el Opening to e4, que solo se activa desde la mano si el rival empieza.","en":"Two Level 4s make a Level 8 Synchro (Glitch Clutch Nullgainer) without needing Opening to e4, which only activates from hand if the opponent goes first."}}],"out":[{"card":"Angelechy Opening to e4","qty":2,"why":{"es":"Yendo primero no se puede activar en la Standby Phase rival y hay que Setearla; Yugipedia señala que el mazo está diseñado para ir segundo.","en":"Going first it cannot be activated in the opponent's Standby Phase and has to be Set; Yugipedia notes the deck is designed to go second."}},{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Se activa solo sin cartas propias.","en":"It only activates with no cards of your own."}}]},"second":{"in":[{"card":"Pot of Sloth","qty":2,"why":{"es":"Robás tantas cartas como cartas controle el rival: segundo, contra un tablero armado, es el mayor valor.","en":"You draw as many cards as the opponent controls: going second, against a built board, it has the most value."}}],"out":[{"card":"Typhoon","qty":1,"why":{"es":"Con el Opening to e4 ya se arma el tablero, la respuesta a backrow cuesta menos que robar.","en":"With Opening to e4 the board is already built, and the backrow answer matters less than drawing."}},{"card":"Terraforming","qty":1,"why":{"es":"Carta de búsqueda lenta que no empuja el tablero del turno.","en":"A slow search card that does not push the turn's board."}}]}},"updated":"2026-10-26"},"adv/artmage":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Artmage Academic Arcane Arts Acropolis busca cualquier monstruo Artmage descartando una Mágica/Trampa. Finmel, Graflare y Litera se invocan solos de la mano si ya controlás una carta Artmage y dan un robo, una Mágica Artmage y una recuperación (Yugipedia).","en":"Artmage Academic Arcane Arts Acropolis searches any Artmage monster by discarding a Spell/Trap. Finmel, Graflare and Litera Summon themselves from hand if you already control an Artmage card and give a draw, an Artmage Spell and a recovery (Yugipedia)."},{"es":"Medius the Pure suma o invoca un Power Patron; Artmage Power Patron hace una Fusión rápida con Medius, por ejemplo Artmage Diactorus, que niega con 3 o más Tipos de monstruo distintos.","en":"Medius the Pure adds or Summons a Power Patron; Artmage Power Patron makes a Quick Fusion with Medius, for example Artmage Diactorus, which negates with 3 or more different Monster Types."},{"es":"Artmage Non-Finito hace una Fusión extra en el turno rival y pone Artmage Impasto -Recapture-, que niega un efecto de monstruo y devuelve las Mágicas/Trampas rivales con 3 Tipos.","en":"Artmage Non-Finito makes an extra Fusion on the opponent's turn and Sets Artmage Impasto -Recapture-, which negates a monster effect and returns the opponent's Spells/Traps with 3 Types."},{"es":"Nerva the Power Patron of Creation convierte el efecto de un monstruo Artmage en \"destruí todas las cartas rivales\".","en":"Nerva the Power Patron of Creation turns an Artmage monster effect into \"destroy all of the opponent's cards\"."}]},"starters":[{"cards":["Artmage Varnish -Alteration-"],"route":{"es":"Coloca el Acropolis del Mazo o Cementerio; con él ya puesto, suma una carta Artmage. Después, el Acropolis descarta una Mágica/Trampa para buscar el monstruo que falte.","en":"Places Acropolis from the Deck or GY; with it already out, it adds an Artmage card. Then Acropolis discards a Spell/Trap to search the missing monster."}},{"cards":["Medius the Pure","Artmage Power Patron"],"route":{"es":"Medius suma o invoca a Artmage Power Patron del Mazo; Power Patron lo fusiona con Medius como efecto rápido (Medius + un Artmage) y deja un Artmage Diactorus, según una lista de ygoprodeck.","en":"Medius adds or Summons Artmage Power Patron from the Deck; Power Patron fuses with Medius as a Quick Effect (Medius + an Artmage) leaving Artmage Diactorus, per a ygoprodeck list."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la búsqueda del Acropolis o de Medius.","en":"On Acropolis' or Medius' search."},"loss":{"es":"Niega la búsqueda que da el monstruo Artmage. Artmage Power Patron aún suma una Mágica/Trampa desde el Cementerio, y el Acropolis permite buscar otro nombre en el mismo turno.","en":"Negates the search that gives the Artmage monster. Artmage Power Patron can still add a Spell/Trap from the GY, and Acropolis lets you search another name the same turn."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del Acropolis o de Power Patron.","en":"After the first search by Acropolis or Power Patron."},"loss":{"es":"Corta todas las siguientes y el mazo depende de varias. Armá la jugada con Finmel, Graflare y Litera, que se invocan de la mano, y no con más búsquedas.","en":"Cuts all following ones and the deck relies on several. Build the play with Finmel, Graflare and Litera, which Summon from hand, and not with more searches."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación: Artmage invoca varios monstruos de la mano y Fusiones.","en":"On the fifth Summon: Artmage Summons several monsters from hand and Fusions."},"loss":{"es":"Tributa todo el tablero Artmage y deja una ficha del tamaño de lo tributado. Jugá con el Tipo distinto de cada monstruo y cortá antes de la quinta si ya tenés Diactorus.","en":"Tributes the whole Artmage board and leaves a token the size of what was Tributed. Play each monster's different Type and stop before the fifth if you already have Diactorus."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En respuesta al efecto rápido de Artmage Power Patron o de Non-Finito.","en":"In response to the Quick Effect of Artmage Power Patron or Non-Finito."},"loss":{"es":"Niega el efecto del monstruo antes de la Fusión. Con Theorealize Past Lull, Medius se invoca de nuevo sin que el rival pueda activar nada en respuesta.","en":"Negates the monster's effect before the Fusion. With Theorealize Past Lull, Medius is Summoned again without the opponent being able to activate anything in response."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Ash Blossom & Joyous Spring","qty":3,"why":{"es":"El Main no juega Ash; yendo primero necesitás interrupción en el turno rival.","en":"The Main Deck plays no Ash; going first you need interruption on the opponent's turn."}}],"out":[{"card":"Mulcharmy Purulia","qty":3,"why":{"es":"Seis Mulcharmy en total, y yendo primero no se pueden activar con tablero.","en":"Six Mulcharmies in total, and going first they cannot be activated with a board."}}]},"second":{"in":[{"card":"Forbidden Crown","qty":1,"why":{"es":"Anula los efectos de un monstruo boca arriba por un turno y lo vuelve indestructible, útil para frenar a un jefe rival.","en":"Negates the effects of a face-up monster for a turn and makes it indestructible, useful to stop an opposing boss."}},{"card":"Pot of Sloth","qty":1,"why":{"es":"Robás por el tablero del rival cuando vas segundo.","en":"You draw for the opponent's board when you go second."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Con 3 Fuwalos y 3 Purulia, recortar dos copias para meter respuestas.","en":"With 3 Fuwalos and 3 Purulia, trimming two copies to add answers."}}]}},"updated":"2026-10-26"},"adv/sky-striker":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Es un mazo de control basado en Mágicas: las Sky Striker Normal y Mecha solo se activan si no controlás monstruos en la Zona de Monstruos Principal y ganan un efecto extra con 3 o más Mágicas en el Cementerio (Yugipedia).","en":"A Spell-based control deck: the Normal and Mecha Sky Striker Spells only activate if you control no monsters in the Main Monster Zone and gain an extra effect with 3 or more Spells in the GY (Yugipedia)."},{"es":"Sky Striker Ace - Raye cambia entre los Link-1 Ace: se tributa como efecto rápido para invocar un Ace del Extra Deck y vuelve del Cementerio si ese Ace se va por batalla o por un efecto rival.","en":"Sky Striker Ace - Raye swaps between the Link-1 Aces: it Tributes as a Quick Effect to Summon an Ace from the Extra Deck and comes back from the GY if that Ace leaves by battle or an opposing effect."},{"es":"El plan del primer turno según la guía de Konami: Ace - Shizuku en el campo con 4 o 5 cartas Seteadas (como Widow Anchor); al turno siguiente, Mobilize - Linkage! cierra la jugada.","en":"The turn 1 plan per Konami's guide: Ace - Shizuku on the field with 4 or 5 Set cards (such as Widow Anchor); next turn, Mobilize - Linkage! finishes the play."},{"es":"Sky Striker Mecha - Widow Anchor niega un efecto de monstruo y, con 3 Mágicas en el Cementerio, te deja robar el control de ese monstruo hasta la End Phase.","en":"Sky Striker Mecha - Widow Anchor negates a monster's effect and, with 3 Spells in the GY, lets you take control of that monster until the End Phase."}]},"starters":[{"cards":["Sky Striker Mobilize - Engage!"],"route":{"es":"Sin monstruos en la Zona Principal, suma una carta Sky Striker del Mazo (que no sea otra Engage!) y, con 3 Mágicas en el Cementerio, también robás una. Es el arranque estándar.","en":"With no monsters in the Main Monster Zone, it adds a Sky Striker card from the Deck (not another Engage!) and, with 3 Spells in the GY, you also draw one. The standard opener."}},{"cards":["Sky Striker Ace - Raye"],"route":{"es":"Raye se tributa como efecto rápido para invocar un Ace al Extra Monster Zone; Kagari recupera una Mágica Sky Striker del Cementerio al invocarse. Si el Ace se va por efecto rival, Raye vuelve.","en":"Raye Tributes as a Quick Effect to Summon an Ace into the Extra Monster Zone; Kagari recovers a Sky Striker Spell from the GY when Summoned. If the Ace leaves by an opposing effect, Raye returns."}},{"cards":["Sky Striker Mobilize - Linkage!","Sky Striker Ace - Roze"],"route":{"es":"Linkage! manda una carta al Cementerio e invoca un Ace; Roze se invoca de la mano cuando entra un Ace, y Raye + Roze permiten el Link Summon de Ace = Zero.","en":"Linkage! sends a card to the GY and Summons an Ace; Roze Summons itself from hand when an Ace comes in, and Raye + Roze allow the Link Summon of Ace = Zero."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre el efecto de Engage! o de Reinforcement of the Army.","en":"On the effect of Engage! or Reinforcement of the Army."},"loss":{"es":"Niega la búsqueda que da la Mágica o el Raye. Con Kagari o Hayate en el Extra Deck (que no dependen de una búsqueda del Mazo), seguís con la mano restante.","en":"Negates the search that gives the Spell or Raye. With Kagari or Hayate in the Extra Deck (which do not rely on a Deck search), you continue with the remaining hand."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera búsqueda del Mazo (Engage!, Reinforcement of the Army o Shizuku en la End Phase).","en":"After the first Deck search resolves (Engage!, Reinforcement of the Army or Shizuku in the End Phase)."},"loss":{"es":"Bloquea las búsquedas siguientes. Yugipedia indica que Kagari y Hayate pueden esquivar efectos anti-búsqueda, así que apuntá a ellos para seguir el turno.","en":"Blocks the following searches. Yugipedia notes Kagari and Hayate can get around anti-search effects, so aim for them to keep the turn going."}},{"card":"Solemn Accusation","step":"activation","stepText":{"es":"Contra la activación de Engage! o Hornet Drones.","en":"Against the activation of Engage! or Hornet Drones."},"loss":{"es":"Yugipedia lo cita entre las trampas más molestas contra esas cartas: niega y destruye la Mágica, y ninguno puede activar otra con el mismo nombre ese turno. Jugá primero la que menos duele.","en":"Yugipedia lists it among the most annoying Traps against those cards: it negates and destroys the Spell, and nobody can activate another with the same name that turn. Play the one that hurts least first."}},{"card":"Harpie's Feather Duster","step":"main","stepText":{"es":"En su Main Phase 1 cuando tenés las Mágicas Seteadas del turno anterior.","en":"In their Main Phase 1 when you have the previous turn's Set Spells."},"loss":{"es":"Destruye todas tus Mágicas/Trampas: perdés Widow Anchor y el resto del setup de primer turno. Yugipedia lo señala como el punto débil clásico.","en":"Destroys all of your Spells/Traps: you lose Widow Anchor and the rest of the turn 1 setup. Yugipedia points to it as the classic weakness."}},{"card":"Santa Claws","step":"summon","stepText":{"es":"Al invocarse en tu campo tributando un Ace de la Extra Monster Zone.","en":"When Summoned to your field by Tributing an Ace from the Extra Monster Zone."},"loss":{"es":"Queda un monstruo en la Zona Principal y las Mágicas Sky Striker que piden zona libre no se pueden activar. Además, Raye no vuelve porque el Ace no dejó el campo por un efecto rival (Yugipedia).","en":"A monster stays in the Main Monster Zone and the Sky Striker Spells that need a free zone cannot be activated. Also, Raye does not return because the Ace did not leave the field by an opposing effect (Yugipedia)."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Evenly Matched","qty":2,"why":{"es":"Con un tablero chico tuyo, en el fin de la Battle Phase rival podés hacerle desterrar boca abajo hasta igualar tus cartas.","en":"With a small board of yours, at the end of the opponent's Battle Phase you can make them banish face-down until card counts match."}}],"out":[{"card":"Forbidden Crown","qty":2,"why":{"es":"Interacción de monstruo que rinde poco con un tablero mínimo; mejor una respuesta masiva.","en":"Monster interaction that does little with a minimal board; a mass answer is better."}}]},"second":{"in":[{"card":"Mulcharmy Fuwalos","qty":3,"why":{"es":"Yendo segundo no controlás cartas en el primer turno rival, así que se activan; el mazo juega sin monstruos de campo.","en":"Going second you control no cards on the opponent's first turn, so they activate; the deck plays with no monsters on the field."}}],"out":[{"card":"Forbidden Crown","qty":2,"why":{"es":"Se cambia por interacción que se activa desde la mano.","en":"Swapped for interaction that activates from hand."}},{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Se cede una copia para sumar un Mulcharmy.","en":"One copy is given up to add a Mulcharmy."}}]}},"updated":"2026-10-26"},"adv/chaos-ritual":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"El objetivo es invocar por Ritual a Black Luster Soldier o a Magician of Dark Chaos - Black Chaos: ignoran los efectos activados rivales salvo los que los apuntan, y el segundo protege además tus Mágicas/Trampas.","en":"The goal is to Ritual Summon Black Luster Soldier or Magician of Dark Chaos - Black Chaos: they ignore the opponent's activated effects unless those target, and the latter also protects your Spells/Traps."},{"es":"Black Chaos se descarta para poner Mind Shuffle sin usar la invocación normal; Mind Shuffle suma un monstruo que mencione a Light and Darkness Ritual y cambia un monstruo de nivel 7+ por un Ritual desde la mano contra un efecto rival.","en":"Black Chaos discards itself to place Mind Shuffle without using your Normal Summon; Mind Shuffle adds a monster that mentions Light and Darkness Ritual and swaps a Level 7+ monster for a Ritual from hand against an opposing effect."},{"es":"Skull Archfiend of Chaos, al ir al Cementerio, manda una Mágica Ritual y suma el Ritual de ella; Light and Darkness Ritual vuelve de nuevo a la mano desde el Cementerio.","en":"Skull Archfiend of Chaos, sent to the GY, sends a Ritual Spell and adds its Ritual Monster; Light and Darkness Ritual returns to the hand from the GY."},{"es":"Yendo segundo es donde más rinde: Black Luster Soldier destierra una carta y Black Chaos destierra dos más sin apuntar, antes de atacar.","en":"Going second is where it shines most: Black Luster Soldier banishes a card and Black Chaos banishes two more without targeting, before attacking."}]},"starters":[{"cards":["Black Chaos"],"route":{"es":"Se descarta para poner Mind Shuffle boca arriba desde el Mazo o Cementerio, sin gastar la invocación normal y sin dar una activación que Ash pueda negar.","en":"Discards itself to place Mind Shuffle face-up from the Deck or GY, without using your Normal Summon and without giving an activation Ash can negate."}},{"cards":["Griffoh"],"route":{"es":"Se descarta como efecto rápido para Setear una Rápida o Trampa que mencione a Light and Darkness Ritual (Mind Shuffle) y activarla el mismo turno. También sirve de Tributo único para un Ritual de nivel 8.","en":"Discards as a Quick Effect to Set a Quick-Play or Trap that mentions Light and Darkness Ritual (Mind Shuffle) and activate it the same turn. It can also serve as the whole Tribute for a Level 8 Ritual."}},{"cards":["Ragged Records of Rites"],"route":{"es":"Muestra una Mágica Ritual (Light and Darkness Ritual) y suma un monstruo que la mencione, normalmente Black Chaos; vuelve a la mano si un Ritual tuyo deja el campo por efecto.","en":"Reveals a Ritual Spell (Light and Darkness Ritual) and adds a monster that mentions it, usually Black Chaos; it returns to the hand if one of your Ritual Monsters leaves the field by effect."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Sobre la primera suma de Mind Shuffle, la carta mandada por Archfiend o Ragged Records.","en":"On Mind Shuffle's first add, the card sent by Archfiend or Ragged Records."},"loss":{"es":"Niega el efecto, pero poner Mind Shuffle con Black Chaos no puede ser negado por Ash, así que abrí con esa ruta (guía de Archetypes Nexus).","en":"Negates the effect, but placing Mind Shuffle with Black Chaos cannot be negated by Ash, so open with that route (Archetypes Nexus guide)."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Tras resolverse la primera suma (Mind Shuffle o Ragged Records).","en":"After the first add resolves (Mind Shuffle or Ragged Records)."},"loss":{"es":"Frena las siguientes sumas del Mazo. Si ya tenés Light and Darkness Ritual en el Cementerio, su efecto trae la Mágica y una carta que la mencione sin pasar por el Mazo.","en":"Stops the following adds from the Deck. If you already have Light and Darkness Ritual in the GY, its effect returns the Spell and a card that mentions it without going through the Deck."}},{"card":"Ghost Ogre & Snow Rabbit","step":"activation","stepText":{"es":"Cuando se activa un efecto de Mind Shuffle (carta ya boca arriba).","en":"When a Mind Shuffle effect (an already face-up card) is activated."},"loss":{"es":"Destruye Mind Shuffle al activarse, salvo que ya tengas a Magician of Dark Chaos protegiendo (guía de Archetypes Nexus). Abrí con Black Chaos y Griffoh antes de comprometer a Mind Shuffle.","en":"Destroys Mind Shuffle as it activates, unless Magician of Dark Chaos is already out protecting (Archetypes Nexus guide). Open with Black Chaos and Griffoh before committing Mind Shuffle."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Black Chaos o el Ritual en el campo, antes de que resuelva su efecto de destierro.","en":"On Black Chaos or the Ritual on the field, before its banish effect resolves."},"loss":{"es":"Niega el efecto del monstruo y se pierde el destierro; la guía de Archetypes Nexus marca a Imperm y Veiler como las respuestas que sí funcionan contra Black Chaos.","en":"Negates the monster's effect and the banish is lost; the Archetypes Nexus guide marks Imperm and Veiler as the answers that do work against Black Chaos."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"Con una Mágica Ritual en tu Cementerio, sobre ella.","en":"With a Ritual Spell in your GY, targeting it."},"loss":{"es":"Destierra la Mágica Ritual y Black Chaos pierde su protección frente a efectos rivales, que depende de tener una Mágica Ritual en el Cementerio (texto de la carta).","en":"Banishes the Ritual Spell and Black Chaos loses its protection against opposing effects, which depends on having a Ritual Spell in the GY (card text)."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Cubre la invocación o la activación del turno rival, donde este mazo tiene menos protección.","en":"Covers the opponent's Summon or activation, where this deck has less protection."}},{"card":"Bystial Magnamhut","qty":1,"why":{"es":"Se invoca desterrando un LIGHT o DARK del Cementerio, incluidos tus Rituales.","en":"Summons itself by banishing a LIGHT or DARK from the GY, your Rituals included."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Se activa solo sin cartas propias: yendo primero tenés tablero.","en":"It only activates with no cards of your own: going first you have a board."}}]},"second":{"in":[{"card":"Harpie's Feather Duster","qty":1,"why":{"es":"Quita todo el fondo de campo rival antes del turno de quiebre.","en":"Removes the whole opposing backrow before the breaking turn."}},{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Responde a un tablero rival que invocó 5 veces mientras vos no tenés tablero que perder.","en":"Answers an opposing board that Summoned 5 times while you have no board to lose."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Con 3 Fuwalos y 3 Purulia hay lugar para recortar uno de cada uno.","en":"With 3 Fuwalos and 3 Purulia there is room to trim one of each."}},{"card":"Mulcharmy Purulia","qty":1,"why":{"es":"Se cede una copia para meter la respuesta.","en":"One copy is given up to add the answer."}}]}},"updated":"2026-10-26"},"dl/wyrms-rush":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Gana por combo de Fusión: Destructor Wyrm Bakhamut y Destructor Soldier Helmet se fusionan en Explosive Destructor Wyrm Dangerous Bakhamut (3000 de ATK), que destruye 1 o 2 monstruos rivales y quema 500 por cada uno.","en":"Wins with a Fusion combo: Destructor Wyrm Bakhamut and Destructor Soldier Helmet fuse into Explosive Destructor Wyrm Dangerous Bakhamut (3000 ATK), which destroys 1 or 2 enemy monsters and burns 500 for each."},{"es":"Todo el Main son Wyrms: eso enciende el Skill (tutor de 2 cartas) y deja que Helmet y Canteen reciclen la Magia de Fusión y los materiales desde el Cementerio, turno tras turno.","en":"The whole Main Deck is Wyrms: that turns on the Skill (2-card tutor) and lets Helmet and Canteen recycle the Fusion spell and the materials from the Graveyard, turn after turn."},{"es":"Autumn Leaves of Blisstopia da 300 de ATK y daño perforante a los Wyrms, y Destructor Claw Shield los vuelve inmunes a efectos si hay una Magia de Campo: un Wyrm grande remata de un solo golpe.","en":"Autumn Leaves of Blisstopia gives Wyrms 300 ATK and piercing damage, and Destructor Claw Shield makes them immune to effects while a Field Spell is out: one big Wyrm finishes in a single hit."},{"es":"Wyrm Excavator the Heavy Cavalry Draco (Maximum, 2500 de ATK) no se destruye por Trampas rivales; tributar ese Maximum habilita a Infinite Heavy Cavalry Buildragoon, que roba 1 y fusiona otra vez.","en":"Wyrm Excavator the Heavy Cavalry Draco (Maximum, 2500 ATK) cannot be destroyed by enemy Traps; Tributing that Maximum Monster enables Infinite Heavy Cavalry Buildragoon, which draws 1 and Fusion Summons again."}]},"starters":[{"cards":["Destructor Soldier Helmet","Destructor Wyrm Bakhamut"],"route":{"es":"Helmet (paga 500 LP) devuelve la Magia de Fusión del Cementerio a la mano; con Bakhamut en la mano o el campo fusionás Dangerous Bakhamut y limpiás hasta 2 monstruos.","en":"Helmet (pay 500 LP) returns the Fusion spell from the Graveyard to hand; with Bakhamut in hand or on the field you fuse Dangerous Bakhamut and clear up to 2 monsters."}},{"cards":["Destructor Soldier Canteen"],"route":{"es":"Canteen manda un Wyrm del Cementerio al Deck, da +100 de ATK y recupera a Helmet (o un Wyrm Normal): repone el material que gastaste en la fusión anterior.","en":"Canteen puts a Wyrm from the Graveyard back in the Deck, gives +100 ATK and retrieves Helmet (or a Wyrm Normal Monster): it refills the material you spent on the last fusion."}},{"cards":["Wyrm Excavator the Heavy Cavalry Draco","Infinite Heavy Cavalry Buildragoon"],"route":{"es":"Invocás el Maximum de Draco y después lo tributás para Buildragoon: robás 1 y fusionás con Wyrms de la mano o del campo. Es la ruta para el OTK yendo segundo.","en":"Maximum Summon Draco, then Tribute that Maximum Monster for Buildragoon: draw 1 and Fusion Summon with Wyrms from hand or field. This is the route for the going-second OTK."}}],"chokepoints":[{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, cuando invocás un Wyrm: da vuelta hasta 2 monstruos con efecto a Defensa boca abajo.","en":"On your turn, when you summon a Wyrm: flips up to 2 Effect Monsters to face-down Defense."},"loss":{"es":"Dangerous Bakhamut queda boca abajo y no ataca; si el monstruo tenía 2600 o más de ATK original, el rival además gana 1500 LP. Hacé primero la invocación que menos importe.","en":"Dangerous Bakhamut ends face-down and cannot attack; if the monster had 2600+ original ATK, the opponent also gains 1500 LP. Make the summon that matters least first."}},{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal a Buildragoon (2500 de ATK).","en":"When you Normal Summon Buildragoon (2500 ATK)."},"loss":{"es":"Manda al Buildragoon al fondo del Deck y se cae la fusión que venía detrás. El Maximum de Draco no es una Invocación Normal, así que esta carta no lo toca.","en":"Sends Buildragoon to the bottom of the Deck and the fusion that followed falls apart. Draco's Maximum Summon is not a Normal Summon, so this card does not touch it."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Destruye a tu monstruo en Ataque con más ATK justo antes del daño. Con Trampas boca abajo, abrí con Primal Howling o con Draco, que resiste Trampas.","en":"Destroys your Attack Position monster with the highest ATK right before damage. Into face-down Traps, open with Primal Howling or Draco, which resists Traps."}},{"card":"Ace Sword Slash","step":"main","stepText":{"es":"En su Main Phase.","en":"On their Main Phase."},"loss":{"es":"Destruye 1 carta tuya y revive un Ace Breaker. Draco no tiene protección contra Magias, así que cae igual: guardá un Wyrm de reserva en la mano para rearmar.","en":"Destroys 1 card of yours and revives an Ace Breaker. Draco has no protection against Spells, so it still falls: keep a spare Wyrm in hand to rebuild."}}],"skills":[{"name":"Activated Wyrm of Black Metal","why":{"es":"Desde el turno 2, si todo tu Deck son Wyrms, mostrás Bakhamut o Helmet y agregás hasta 2 cartas del Deck o Cementerio (monstruos de nivel 8, de 400 de DEF, la Magia de Fusión, Magias de Campo o de Equipo); después descartás 1. Es el motor del mazo.","en":"From turn 2, if your whole Deck is Wyrms, you reveal Bakhamut or Helmet and add up to 2 cards from Deck or Graveyard (Level 8 monsters, 400 DEF monsters, the Fusion spell, Field or Equip Spells); then discard 1. It is the deck engine."}}],"side":{"first":{"in":[{"card":"Destructor Art - Total Destruction","qty":1,"why":{"es":"Yendo primero no atacás el primer turno y el rival sí puede atacar el suyo: esta Trampa responde a su ataque, recicla Wyrms al Deck y, si suman nivel 16 o más, destruye sus monstruos en Ataque.","en":"Going first you do not attack on turn 1 and the opponent can attack on theirs: this Trap answers their attack, recycles Wyrms into the Deck and, with 16+ total Levels, destroys their Attack Position monsters."}}],"out":[{"card":"Destructor Soldier Haken","qty":1,"why":{"es":"Haken pide que el rival tenga 1 carta o menos en la mano: casi nunca pasa en tu primer turno.","en":"Haken needs the opponent to have 1 card or fewer in hand: that almost never happens on your first turn."}}]},"second":{"in":[{"card":"Destructor Integration Scrap Gate","qty":1,"why":{"es":"Yendo segundo la Magia de Campo habilita a Bakhamut y deja fusionar devolviendo solo Wyrms del Cementerio. Un jugador de KOG la cuenta como un buen habilitador.","en":"Going second this Field Spell enables Bakhamut and lets you fuse by returning only Wyrms from the Graveyard. A KOG player calls it a strong enabler."}}],"out":[{"card":"Destructor Soldier Haken","qty":1,"why":{"es":"Haken te obliga a atacar con un solo monstruo y depende de la mano rival; la ranura rinde más como Magia de Campo para Bakhamut.","en":"Haken limits you to one attacker and depends on the opponent's hand; the slot is worth more as a Field Spell for Bakhamut."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/ether-dragon":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Gana con Eternity Ether Dragon (nivel 9, 2500 de ATK): al invocarlo pagás 500 LP y destruís 1 carta rival. Se invoca por Tributo, y el Skill hace que cada monstruo cuente como 2 Tributos.","en":"Wins with Eternity Ether Dragon (Level 9, 2500 ATK): when summoned you pay 500 LP and destroy 1 enemy card. It is Tribute Summoned, and the Skill makes each monster count as 2 Tributes."},{"es":"Los monstruos baratos arman la mano: Evil Dragon of Darkness busca al Ether Dragon desde el Cementerio, Balloon Butier invoca de Especial lo que cae del Deck y Amazing Dealer cambia 3 cartas por 3.","en":"Cheap monsters build the hand: Evil Dragon of Darkness retrieves Ether Dragon from the Graveyard, Balloon Butier Special Summons what falls from the Deck and Amazing Dealer trades 3 cards for 3."},{"es":"La otra mitad es la línea Ultimate Flag: The Ultimate Flag trae a Ace Breaker y a Ace Sword Slash, y los dos destruyen cartas rivales. Ace Sword Slash es gratis el primer turno de quien va segundo.","en":"The other half is the Ultimate Flag line: The Ultimate Flag fetches Ace Breaker and Ace Sword Slash, and both destroy enemy cards. Ace Sword Slash is free on the first turn of the player going second."}]},"starters":[{"cards":["Evil Dragon of Darkness","Eternity Ether Dragon"],"route":{"es":"Evil Dragon manda 2 cartas al Cementerio y agrega a Eternity Ether Dragon (o un Dragón de nivel 9 con 2500 de ATK) a la mano; con el Skill lo invocás tributando un solo monstruo.","en":"Evil Dragon sends 2 cards to the Graveyard and adds Eternity Ether Dragon (or a Level 9, 2500 ATK Dragon) to hand; with the Skill you summon it by Tributing a single monster."}},{"cards":["The Ultimate Flag","Ace Sword Slash"],"route":{"es":"The Ultimate Flag se manda sola al Cementerio y agrega Ace Breaker y Ace Sword Slash; invocás Ace Breaker de Especial desde la mano y ya tenés dos destrucciones preparadas.","en":"The Ultimate Flag sends itself to the Graveyard and adds Ace Breaker and Ace Sword Slash; you Special Summon Ace Breaker from hand and already have two removals lined up."}},{"cards":["Amazing Dealer","Innocent Fadrawl"],"route":{"es":"Fadrawl hace robar a ambos jugadores; Amazing Dealer manda 3 cartas al Cementerio y roba 3. Con el Cementerio cargado, Evil Dragon y Ultimate Flag salen más fácil.","en":"Fadrawl makes both players draw; Amazing Dealer sends 3 cards to the Graveyard and draws 3. With a loaded Graveyard, Evil Dragon and Ultimate Flag come out easier."}}],"chokepoints":[{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal a Eternity Ether Dragon (2500 de ATK).","en":"When you Normal Summon Eternity Ether Dragon (2500 ATK)."},"loss":{"es":"Manda al Ether Dragon al fondo del Deck antes de que uses su efecto. Jugá primero el Ace Breaker o un Butier y dejá el Ether para después de ver si activan.","en":"Sends Ether Dragon to the bottom of the Deck before you can use its effect. Play Ace Breaker or a Butier first and keep Ether until you see whether they activate."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar un monstruo.","en":"On your turn, when you summon a monster."},"loss":{"es":"Da vuelta hasta 2 monstruos con efecto a Defensa boca abajo: Ether Dragon no ataca, y si tenía 2600 o más de ATK original el rival gana 1500 LP. Hacé primero la invocación menos importante.","en":"Flips up to 2 Effect Monsters to face-down Defense: Ether Dragon cannot attack, and if it had 2600+ original ATK the opponent gains 1500 LP. Make the least important summon first."}},{"card":"Star Protector's Protection","step":"summon","stepText":{"es":"Cuando Invocás de Normal o de Especial, o cuando robás en tu turno.","en":"When you Normal or Special Summon, or draw on your turn."},"loss":{"es":"Te obliga a mandar un monstruo de tu campo al Cementerio y solo podés declarar un ataque ese turno. Cada Fadrawl o invocación extra te cuesta un cuerpo.","en":"Forces you to send a monster from your field to the Graveyard and you can only declare one attack that turn. Every Fadrawl or extra summon costs you a body."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Destruye al monstruo en Ataque con más ATK, normalmente el Ether Dragon. Si hay Trampas boca abajo, limpiá antes con Ace Sword Slash.","en":"Destroys your Attack Position monster with the highest ATK, usually Ether Dragon. If Traps are face-down, clear them first with Ace Sword Slash."}}],"skills":[{"name":"Destiny Draw: Divine Dragons","why":{"es":"Desde el turno 2, antes de tu robo normal, pone a Eternity Ether Dragon del Deck arriba, te hace robar hasta 6 en lugar de 5 y cada monstruo tuyo cuenta como 2 Tributos para invocarlo. Se usa 2 veces yendo primero y 3 yendo segundo.","en":"From turn 2, before your normal draw, it puts Eternity Ether Dragon from the Deck on top, makes you draw up to 6 instead of 5 and each of your monsters counts as 2 Tributes to summon it. 2 uses going first, 3 going second."}}],"side":{"first":{"in":[{"card":"Ultimate Flag Beast Boltricorn","qty":1,"why":{"es":"Yendo primero conviene que el Ether Dragon entre sin Trampa de por medio: Boltricorn impide que una Magia/Trampa boca abajo se active hasta el final del próximo turno rival.","en":"Going first you want Ether Dragon to land without a Trap in the way: Boltricorn stops a face-down Spell/Trap from activating until the end of the opponent's next turn."}}],"out":[{"card":"Curse of the Rising Light","qty":1,"why":{"es":"Robar 2 solo vale con el rival sin mano o en el primer turno de quien va segundo: yendo primero rinde menos.","en":"Its draw-2 only works when the opponent has no hand or on the first turn of the player going second: weaker going first."}}]},"second":{"in":[{"card":"Ultimate Flag Beast Boltricorn","qty":1,"why":{"es":"Yendo segundo enfrentás un tablero con Trampas armadas: Boltricorn apaga una boca abajo para que Ace Sword Slash y Ether Dragon pasen.","en":"Going second you face a board with set Traps: Boltricorn shuts off a face-down card so Ace Sword Slash and Ether Dragon get through."}}],"out":[{"card":"Great Maju Garzett","qty":1,"why":{"es":"Maju es una carta de nicho (su ATK depende del monstruo tributado): un jugador de KOG la usa como tech suelta, así que es la primera que sale.","en":"Maju is a niche card (its ATK depends on the Tributed monster): a KOG player runs it as a loose tech, so it is the first to come out."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/dark-magician-rush":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"El mazo gira en torno a Dark Magician (nivel 7, 2500 de ATK, Normal): revivirlo desde el Cementerio con Wizened Dark Magician, Secret Order o Stone of the Dark Magicians evita el Tributo.","en":"The deck revolves around Dark Magician (Level 7, 2500 ATK, Normal Monster): reviving it from the Graveyard with Wizened Dark Magician, Secret Order or Stone of the Dark Magicians skips the Tribute."},{"es":"Con Dark Magician en el campo se habilitan Thousand Knives (destruye un monstruo) y Dark Magic Attack (destruye todas las Magias y Trampas rivales): abrís camino sin gastar monstruos.","en":"With Dark Magician on the field, Thousand Knives (destroys a monster) and Dark Magic Attack (destroys all enemy Spells and Traps) come online: you clear a path without spending monsters."},{"es":"Dark Resonance Burst suma +1000 de ATK, o +2000 si hay Dark Magician o Dark Magician Girl: cierra el duelo rápido. Dark Magician Girl crece 300 por cada Dark Magician en el Cementerio.","en":"Dark Resonance Burst adds +1000 ATK, or +2000 if Dark Magician or Dark Magician Girl is out: it closes the duel fast. Dark Magician Girl grows 300 per Dark Magician in the Graveyard."}]},"starters":[{"cards":["Wizened Dark Magician","Dark Magician"],"route":{"es":"Wizened manda de la mano un Lanzador de Conjuros OSCURO (por ejemplo el propio Dark Magician), roba 1 e invoca de Especial a Dark Magician desde el Cementerio.","en":"Wizened sends a DARK Spellcaster from hand (for example Dark Magician itself), draws 1 and Special Summons Dark Magician from the Graveyard."}},{"cards":["Stone of the Dark Magicians","Dark Eradicator Sorcerer"],"route":{"es":"Stone invoca de Especial un OSCURO de 2500 de ATK y/o uno de 2000 (Sorcerer y Dark Magician Girl) desde la mano o el Cementerio, sin Tributo: dos cuerpos en un turno.","en":"Stone Special Summons a DARK Spellcaster with 2500 ATK and/or one with 2000 ATK (Sorcerer and Dark Magician Girl) from hand or Graveyard, with no Tribute: two bodies in one turn."}},{"cards":["Secret Order","Dark Magician"],"route":{"es":"Secret Order invoca de Especial un Normal de nivel 7 (Dark Magician) desde la mano o el Cementerio con +700 de ATK (3200) e inmune a efectos de Trampa: la jugada más segura contra Trampas.","en":"Secret Order Special Summons a Level 7 Normal Monster (Dark Magician) from hand or Graveyard with +700 ATK (3200) and immunity to Trap effects: the safest play into Traps."}}],"chokepoints":[{"card":"Rice Terrace Crisis","step":"summon","stepText":{"es":"Cuando invocás de Especial desde la mano o el Cementerio (Wizened, Secret Order, Stone).","en":"When you Special Summon from hand or Graveyard (Wizened, Secret Order, Stone)."},"loss":{"es":"Da vuelta hasta 2 monstruos tuyos (niveles totales de 12 o menos) a Defensa boca abajo. Dark Magician pasa a Defensa y no ataca ese turno; guardá Thousand Knives para el turno siguiente.","en":"Flips up to 2 of your monsters (total Levels 12 or less) to face-down Defense. Dark Magician goes to Defense and cannot attack that turn; save Thousand Knives for the next turn."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu monstruo.","en":"On your turn, when you summon your monster."},"loss":{"es":"Solo da vuelta monstruos con efecto: Dark Magician (Normal) no se ve afectado, pero Dark Magician Girl, Dark Eradicator Sorcerer y Wizened sí. Invocá primero un Normal si podés.","en":"It only flips Effect Monsters: Dark Magician (a Normal Monster) is unaffected, but Dark Magician Girl, Dark Eradicator Sorcerer and Wizened are. Summon the Normal first if you can."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Se lleva a tu Dark Magician reforzado justo antes del daño. Usá Dark Magic Attack antes (borra las Trampas) y atacá después.","en":"Takes your boosted Dark Magician right before damage. Use Dark Magic Attack first (it wipes the Traps) and attack afterward."}},{"card":"Buffered Slime","step":"attack","stepText":{"es":"Cuando tu monstruo de nivel 8 o menos declara un ataque.","en":"When your Level 8 or lower monster declares an attack."},"loss":{"es":"Ese turno el rival no recibe daño de batalla y el OTK se corta. Dark Magic Attack antes del ataque borra la Trampa.","en":"The opponent takes no battle damage that turn and the OTK is cut. Dark Magic Attack before the attack removes the Trap."}}],"skills":[{"name":"Illusion of Execution","why":{"es":"Desde el turno 2, si todos los monstruos son Lanzadores de Conjuros y los de nivel 5+ son solo Dark Magician, Dark Magician Girl o Dark Eradicator Sorcerer, mostrás uno y excavás 3 cartas: agregás 1 Magia, mandás el resto al Cementerio y después podés mandar a Dark Magician del Deck. Una vez por Duelo.","en":"From turn 2, if all monsters are Spellcasters and Level 5+ ones are only Dark Magician, Dark Magician Girl or Dark Eradicator Sorcerer, you reveal one and excavate 3 cards: add 1 Spell, send the rest to the Graveyard and then you may send Dark Magician from the Deck. Once per Duel."}}],"side":{"first":{"in":[{"card":"Widespread Ruin","qty":1,"why":{"es":"Yendo primero no atacás el primer turno, así que una Trampa defensiva rinde más. Aparece en una lista de KOG del mazo.","en":"Going first you do not attack on turn 1, so a defensive Trap is worth more. It shows up in a KOG list of the deck."}}],"out":[{"card":"Pierce!","qty":1,"why":{"es":"Pierce! solo sirve al atacar a un monstruo en Defensa, algo que no vas a poder hacer el primer turno.","en":"Pierce! only helps when attacking a Defense Position monster, which you cannot do on the first turn."}}]},"second":{"in":[{"card":"Monster Calling","qty":1,"why":{"es":"Yendo segundo robás 1 y revivís un monstruo no-Efecto de 2000 de ATK o 2100 de DEF: Dark Magician (2500/2100) califica y vuelve sin Tributo. Aparece en una lista de KOG del mazo.","en":"Going second you draw 1 and revive a non-Effect monster with 2000 ATK or 2100 DEF: Dark Magician (2500/2100) qualifies and returns with no Tribute. It shows up in a KOG list of the deck."}}],"out":[{"card":"Stealthagic","qty":1,"why":{"es":"El robo extra de Stealthagic exige 1000 LP o menos; Monster Calling encaja mejor con tu plan de revivir.","en":"Stealthagic's extra draw needs 1000 LP or less; Monster Calling fits your revive plan better."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/elemental-hero-rush":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Combo de Fusión con Guerreros: Rising HERO Argent y Elemental Circulation buscan los materiales (Avian, Burstinatrix, Sparkman) y los fusionás en Wingmen de nivel 5 a 8.","en":"Warrior Fusion combo: Rising HERO Argent and Elemental Circulation find the materials (Avian, Burstinatrix, Sparkman) and you fuse them into Level 5 to 8 Wingmen."},{"es":"Los Normales son el material: Hero Descent y Star Restart los reviven desde el Cementerio, y Star Restart además devuelve la Magia de Fusión a la mano.","en":"The Normal Monsters are the material: Hero Descent and Star Restart revive them from the Graveyard, and Star Restart also returns the Fusion spell to hand."},{"es":"Elemental HERO Heliosphere (nivel 7, 2800) roba 1 y, si sale monstruo, destruye 1 carta rival; Shining Flare Wingman gana 300 por cada HERO del Cementerio y quema por el ATK del monstruo que destruye.","en":"Elemental HERO Heliosphere (Level 7, 2800) draws 1 and, if it is a monster, destroys 1 enemy card; Shining Flare Wingman gains 300 per HERO in the Graveyard and burns for the ATK of the monster it destroys."}]},"starters":[{"cards":["Rising HERO Argent","Elemental HERO Burst Wingman"],"route":{"es":"Argent muestra un Fusión Guerrero de nivel 6 o 7 (Burst Wingman), excava 4 y agrega hasta 2 Normales que sean sus materiales (Avian y Burstinatrix): fusión lista en el mismo turno.","en":"Argent reveals a Level 6 or 7 Warrior Fusion (Burst Wingman), excavates 4 and adds up to 2 Normal Monsters that are its materials (Avian and Burstinatrix): a fusion ready the same turn."}},{"cards":["Elemental Circulation","Star Restart"],"route":{"es":"Circulation manda un material al Cementerio y roba 3; Star Restart lo revive (Normal de nivel 5 o menos) y recupera la Magia de Fusión del Cementerio.","en":"Circulation sends a material to the Graveyard and draws 3; Star Restart revives it (Level 5 or lower Normal Monster) and returns the Fusion spell from the Graveyard."}},{"cards":["Elemental HERO Voltic Wingman","Elemental HERO Sparkman"],"route":{"es":"Voltic Wingman (Sparkman + Avian) fusiona de nuevo a un Guerrero de nivel 6 a 8 barajando monstruos del Cementerio como material: encadena una segunda fusión.","en":"Voltic Wingman (Sparkman + Avian) Fusion Summons a Level 6 to 8 Warrior by shuffling Graveyard monsters as material: it chains into a second fusion."}}],"chokepoints":[{"card":"Rice Terrace Crisis","step":"summon","stepText":{"es":"Cuando invocás de Especial desde la mano o el Cementerio (Hero Descent, Star Restart).","en":"When you Special Summon from hand or Graveyard (Hero Descent, Star Restart)."},"loss":{"es":"Da vuelta hasta 2 monstruos tuyos (niveles totales de 12 o menos) a Defensa boca abajo: se te cae el material antes de fusionar. Fusioná primero con lo que ya está en el campo.","en":"Flips up to 2 of your monsters (total Levels 12 or less) to face-down Defense: the material is lost before you fuse. Fuse first with what is already on the field."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu Wingman.","en":"On your turn, when you summon your Wingman."},"loss":{"es":"Da vuelta hasta 2 monstruos con efecto a Defensa boca abajo: los Wingmen tienen efecto y quedan sin atacar. Los Normales (Avian, Burstinatrix, Sparkman) no se ven afectados.","en":"Flips up to 2 Effect Monsters to face-down Defense: Wingmen have effects and cannot attack. Normals (Avian, Burstinatrix, Sparkman) are unaffected."}},{"card":"Widespread Ruin","step":"attack","stepText":{"es":"En tu declaración de ataque.","en":"On your attack declaration."},"loss":{"es":"Destruye al monstruo en Ataque con más ATK (el Heliosphere o el Wingman principal). Limpiá las Trampas con Burst Wingman o Avian Spell Tactics antes de pegar.","en":"Destroys your Attack Position monster with the highest ATK (Heliosphere or the main Wingman). Clear Traps with Burst Wingman or Avian Spell Tactics before attacking."}}],"skills":[{"name":"Hero Rush Rising","why":{"es":"Mandando 1 carta de tu campo al Cementerio (con los monstruos de 1600+ de ATK todos LIGHT Guerreros y el Extra solo Guerreros), un monstruo cualquiera pierde 600 de ATK/DEF y agregás la Magia de Fusión del Deck o el Cementerio. Te asegura el arranque.","en":"By sending 1 card from your field to the Graveyard (with all 1600+ ATK monsters being LIGHT Warriors and the Extra Deck only Warriors), a monster loses 600 ATK/DEF and you add the Fusion spell from Deck or Graveyard. It secures your start."}}],"side":{"first":{"in":[{"card":"Widespread Ruin","qty":1,"why":{"es":"Yendo primero no atacás el primer turno: una segunda copia de esta Trampa cubre el ataque rival de su primer turno.","en":"Going first you do not attack on turn 1: a second copy of this Trap covers the opponent's attack on their first turn."}}],"out":[{"card":"Avian Spell Tactics","qty":1,"why":{"es":"Su efecto destruye una Magia/Trampa rival, y el primer turno no hay ninguna que destruir.","en":"Its effect destroys an enemy Spell/Trap, and on the first turn there is none to destroy."}}]},"second":{"in":[{"card":"Rice Terrace Crisis","qty":1,"why":{"es":"Yendo segundo sufrís las invocaciones rivales: esta Trampa da vuelta hasta 2 monstruos que invoquen de la mano o el Cementerio.","en":"Going second you face their summons: this Trap flips up to 2 monsters they summon from hand or Graveyard."}}],"out":[{"card":"Hero Descent","qty":1,"why":{"es":"Obliga a atacar solo con Guerreros ese turno y es de las Magias menos necesarias cuando Argent y Circulation ya abren.","en":"It restricts attacks to Warriors that turn and is one of the least needed Spells when Argent and Circulation already open."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/voidvelg":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Plan de OTK con Voidvelg Requiem (nivel 8, 2500): gana 300 de ATK por cada monstruo OSCURO que controlás y 600 más si el rival tiene uno LIGHT. Con el Skill, un monstruo cuenta como 2 Tributos.","en":"OTK plan with Voidvelg Requiem (Level 8, 2500): gains 300 ATK per DARK monster you control and 600 more if the opponent has a LIGHT one. With the Skill, one monster counts as 2 Tributes."},{"es":"Dark Matter Requiem (Requiem + Contact Darkmatter Explorer, por Fusión por Contacto) llega a 3000 y gana 1300 de ATK con daño perforante, además de dar vuelta un monstruo rival.","en":"Dark Matter Requiem (Requiem + Contact Darkmatter Explorer, by Contact Fusion) reaches 3000 and gains 1300 ATK with piercing damage, while flipping an enemy monster face-down."},{"es":"Dark Hole Device destruye todos los monstruos (cuesta 3 OSCUROS Galaxy de la mano o un Fusión OSCURO Galaxy en el campo) y recupera un Galaxy del Cementerio. Un jugador de KOG armó la lista sin Trampas para ganar consistencia.","en":"Dark Hole Device destroys all monsters (costs 3 DARK Galaxy from hand or a DARK Galaxy Fusion on your field) and retrieves a Galaxy from the Graveyard. A KOG player built the list with no Traps for consistency."}]},"starters":[{"cards":["Voidvelg Whiterider","Voidvelg Requiem"],"route":{"es":"Whiterider se vuelve Palerider, excava 3 cartas y agrega a Voidvelg Requiem o un Galaxy OSCURO Normal: busca el cuerpo principal sin gastar la Invocación Normal.","en":"Whiterider becomes Palerider, excavates 3 cards and adds Voidvelg Requiem or a DARK Galaxy Normal Monster: it finds the main body without using your Normal Summon."}},{"cards":["Voidvelg Stork","Voidvelg Requiem"],"route":{"es":"Stork (descartando una carta de la mano) se vuelve Requiem, o mandando 2 cartas del Deck se vuelve Contact Darkmatter Explorer para la Fusión por Contacto con Requiem.","en":"Stork (discarding a card from hand) becomes Requiem, or by milling 2 cards becomes Contact Darkmatter Explorer for the Contact Fusion with Requiem."}},{"cards":["Chaos Coolstars","Voidvelg Requiem"],"route":{"es":"Coolstars descarta un Galaxy LIGHT/DARK para robar 1 y cuenta como 2 Tributos para Invocar de Tributo a Requiem en Ataque: el Tributo sale barato.","en":"Coolstars discards a LIGHT/DARK Galaxy to draw 1 and counts as 2 Tributes to Tribute Summon Requiem in Attack Position: the Tribute comes cheap."}}],"chokepoints":[{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal a Requiem (2500 de ATK).","en":"When you Normal Summon Requiem (2500 ATK)."},"loss":{"es":"Manda a Requiem al fondo del Deck y se corta el OTK de ese turno. Abrí con Palerider o con una Fusión por Contacto, que no son Invocación Normal de 2500.","en":"Sends Requiem to the bottom of the Deck and the OTK is cut that turn. Open with Palerider or a Contact Fusion, which are not a 2500 ATK Normal Summon."}},{"card":"Trap Hole","step":"summon","stepText":{"es":"Cuando Invocás de Normal un monstruo de 1000 o más de ATK.","en":"When you Normal Summon a monster with 1000 or more ATK."},"loss":{"es":"Destruye al monstruo recién invocado, sea Requiem o Palerider. Mostrá antes un cuerpo barato (Stork, Globule) si querés forzar la Trampa.","en":"Destroys the freshly summoned monster, Requiem or Palerider. Show a cheap body first (Stork, Globule) if you want to bait the Trap."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu monstruo.","en":"On your turn, when you summon your monster."},"loss":{"es":"Da vuelta hasta 2 monstruos con efecto a Defensa boca abajo. Palerider y Contact Darkmatter Explorer (Normales) no se ven afectados.","en":"Flips up to 2 Effect Monsters to face-down Defense. Palerider and Contact Darkmatter Explorer (Normals) are unaffected."}},{"card":"Buffered Slime","step":"attack","stepText":{"es":"Cuando tu monstruo de nivel 8 o menos declara un ataque.","en":"When your Level 8 or lower monster declares an attack."},"loss":{"es":"Ese turno el rival no recibe daño de batalla y el OTK pierde el último golpe. Universal Storm antes del ataque limpia la Trampa.","en":"The opponent takes no battle damage that turn and the OTK loses its last hit. Universal Storm before the attack clears the Trap."}}],"skills":[{"name":"Requiem Contact","why":{"es":"Desde el turno 2, con todos los monstruos del Deck OSCUROS Galaxy, pone a Voidvelg Requiem o a un Normal del Deck o Cementerio arriba de tu Deck, hace que cada monstruo cuente como 2 Tributos para invocar a Requiem en Ataque y podés robar 1. Una vez por Duelo.","en":"From turn 2, with all Deck monsters being DARK Galaxy, it puts Voidvelg Requiem or a Normal Monster from Deck or Graveyard on top of your Deck, makes each monster count as 2 Tributes to summon Requiem in Attack Position and lets you draw 1. Once per Duel."}}],"side":{"first":{"in":[{"card":"Universal Storm","qty":1,"why":{"es":"Yendo primero no atacás el primer turno: Universal Storm destruye una Magia/Trampa rival con un Galaxy en el campo y prepara el OTK siguiente. Aparece en una lista de KOG del mazo.","en":"Going first you do not attack on turn 1: Universal Storm destroys an enemy Spell/Trap with a Galaxy on the field and prepares the next-turn OTK. It shows up in a KOG list of the deck."}}],"out":[{"card":"Pot of Avarice","qty":1,"why":{"es":"Necesita 5 monstruos en el Cementerio, algo raro de tener en el primer turno.","en":"It needs 5 monsters in the Graveyard, which is rare on the first turn."}}]},"second":{"in":[{"card":"Talismanic Seal Array","qty":1,"why":{"es":"Un autor de KOG duda de Dark Hole Device y la cambiaría por esta: baja el ATK de un monstruo rival 200 por nivel sin borrar tus cuerpos, a cambio de barajar 4 monstruos del Cementerio.","en":"A KOG author doubts Dark Hole Device and would swap it for this: it lowers an enemy monster's ATK by 200 per Level without clearing your bodies, at the cost of shuffling 4 monsters from the Graveyard."}}],"out":[{"card":"Dark Hole Device","qty":1,"why":{"es":"Destruye también tus propios monstruos, y yendo segundo muchas veces ya tenés el campo armado.","en":"It destroys your own monsters too, and going second you often already have the board set up."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/royal-rebel-s":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Plan de OTK con Fiends de nivel 8 que se Invocan de Normal tributando uno o dos Fiends de nivel alto: Royal Rebel's Doom Metal (2 Tributos) destruye todos los monstruos rivales y quema según el nivel.","en":"OTK plan with Level 8 Fiends Normal Summoned by Tributing one or two high-Level Fiends: Royal Rebel's Doom Metal (2 Tributes) destroys all enemy monsters and burns by Level."},{"es":"Royal Rebel's Progrock (1 Tributo de nivel 5+) destruye una Magia/Trampa y una carta boca abajo y abre el camino. Hard Rock (2 Tributos) hace daño por la diferencia de ATK.","en":"Royal Rebel's Progrock (1 Tribute of Level 5+) destroys a Spell/Trap and a face-down card and opens the path. Hard Rock (2 Tributes) deals damage by ATK difference."},{"es":"El Skill pone 2 monstruos de nivel 7 u 8 en Defensa y esos turnos los monstruos de nivel original 7+ pueden atacar directo una vez: es el empujón final.","en":"The Skill places 2 Level 7 or 8 monsters in Defense and that turn monsters with original Level 7+ can attack directly once: that is the final push."}]},"starters":[{"cards":["Faceless Culdesac","Royal Rebel's Progrock"],"route":{"es":"Culdesac (nivel 6) se invoca de Especial desde la mano mostrando otro Fiend, da +300 de ATK a los Fiends y sirve de Tributo de nivel 5+ para Progrock sin gastar la Invocación Normal.","en":"Culdesac (Level 6) Special Summons from hand by revealing another Fiend, gives Fiends +300 ATK and serves as the Level 5+ Tribute for Progrock without spending your Normal Summon."}},{"cards":["Trade-In","Royal Rebel's Doom Metal"],"route":{"es":"Trade-In descarta un nivel 8 y roba 2: el nivel 8 en el Cementerio queda para revivirlo, y con la mano nueva juntás los 2 Tributos que pide Doom Metal.","en":"Trade-In discards a Level 8 and draws 2: the Level 8 in the Graveyard is left for revival, and the new hand gathers the 2 Tributes Doom Metal asks for."}},{"cards":["Royal Rebel's Doom Metal","Perion the Star Knight"],"route":{"es":"El Skill deja 2 monstruos de nivel 7/8 (por ejemplo Perion) en Defensa y los tributás para Doom Metal: ese turno destruís todos los monstruos rivales y atacás directo.","en":"The Skill places 2 Level 7/8 monsters (for example Perion) in Defense and you Tribute them for Doom Metal: that turn you destroy all enemy monsters and attack directly."}}],"chokepoints":[{"card":"Forever Freeze","step":"summon","stepText":{"es":"Cuando Invocás de Normal un jefe (todos tienen 2500 de ATK).","en":"When you Normal Summon a boss (all have 2500 ATK)."},"loss":{"es":"El jefe vuelve al fondo del Deck y perdés los Tributos. Jugá primero un Culdesac o un Shout para ver si hay Trampa.","en":"The boss goes to the bottom of the Deck and you lose the Tributes. Play Culdesac or Shout first to see whether there is a Trap."}},{"card":"Trap Hole","step":"summon","stepText":{"es":"Cuando Invocás de Normal un monstruo de 1000 o más de ATK.","en":"When you Normal Summon a monster with 1000 or more ATK."},"loss":{"es":"Destruye al jefe recién invocado antes de que uses su efecto. Por eso conviene Heavenly Selection o Genie's Fire Breath para sacar la Trampa antes.","en":"Destroys the freshly summoned boss before you use its effect. That is why Heavenly Selection or Genie's Fire Breath is worth running to remove the Trap first."}},{"card":"Shiny Shady","step":"summon","stepText":{"es":"En tu turno, al invocar tu monstruo.","en":"On your turn, when you summon your monster."},"loss":{"es":"Da vuelta tus monstruos con efecto a Defensa boca abajo (todos los jefes lo son) y no atacan. Se evita invocando recién después de limpiar las Trampas.","en":"Flips your Effect Monsters to face-down Defense (all bosses are) and they cannot attack. You avoid it by summoning only after clearing Traps."}},{"card":"Buffered Slime","step":"attack","stepText":{"es":"Cuando tu monstruo de nivel 8 o menos declara un ataque.","en":"When your Level 8 or lower monster declares an attack."},"loss":{"es":"Ese turno el rival no recibe daño de batalla y el ataque directo no hace nada. Progrock o Heavenly Selection antes de atacar lo evitan.","en":"The opponent takes no battle damage that turn and the direct attack does nothing. Progrock or Heavenly Selection before attacking avoids it."}}],"skills":[{"name":"Hard Rock Overture","why":{"es":"Mandando de la mano un monstruo de nivel 7 u 8 (con todo el Deck Fiend LIGHT) ponés hasta 2 monstruos de nivel 7/8 de la mano o el Cementerio en Defensa; desde el turno 2 sumás uno del Cementerio a la mano, y ese turno los de nivel original 7+ atacan directo una vez.","en":"By sending a Level 7 or 8 monster from hand (with a full LIGHT Fiend deck) you place up to 2 Level 7/8 monsters from hand or Graveyard in Defense; from turn 2 you also add one from the Graveyard to hand, and that turn monsters with original Level 7+ attack directly once."}}],"side":{"first":{"in":[{"card":"Widespread Ruin","qty":1,"why":{"es":"Yendo primero no atacás el primer turno: esta Trampa cubre el ataque rival de su primer turno mientras armás el tablero.","en":"Going first you do not attack on turn 1: this Trap covers the opponent's attack on their first turn while you build the board."}}],"out":[{"card":"Heavenly Selection","qty":1,"why":{"es":"Necesita 10 niveles en tu campo y una Magia/Trampa rival: en el primer turno no tenés ni lo uno ni lo otro.","en":"It needs 10 Levels on your field and an enemy Spell/Trap: on the first turn you have neither."}}]},"second":{"in":[{"card":"Genie's Fire Breath","qty":1,"why":{"es":"Con un Fiend en el campo devuelve una Magia/Trampa rival a la mano: despeja las Trampas que ya tiene armadas yendo segundo. Aparece en una lista de KOG del mazo.","en":"With a Fiend on the field it returns an enemy Spell/Trap to hand: it clears Traps they already have set when you go second. It shows up in a KOG list of the deck."}}],"out":[{"card":"Kheiron the Star Knight","qty":1,"why":{"es":"Su daño perforante solo sirve contra un monstruo en Defensa; yendo segundo preferís la remoción de Trampas.","en":"Its piercing damage only works against a Defense Position monster; going second you prefer Trap removal."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/branded":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Gana por combo de Fusión: Fallen of Albaz, Blazing Cartesia y Branded Fusion sacan Albion, Mirrorjade, Granguignol o Lubellion en el mismo turno y dejan un campo con negaciones y banish.","en":"Wins with a Fusion combo: Fallen of Albaz, Blazing Cartesia and Branded Fusion bring out Albion, Mirrorjade, Granguignol or Lubellion in one turn and leave a board of negates and banish effects."},{"es":"Los Bystial (Druiswurm, Magnamhut, Saronir) se Invocan solos desde la mano banqueando un monstruo LIGHT o DARK de algún Cementerio, y como Efecto Rápido si el rival controla un monstruo: así arman el turno del rival.","en":"The Bystials (Druiswurm, Magnamhut, Saronir) Special Summon themselves from hand by banishing a LIGHT or DARK monster from a GY, as a Quick Effect if the opponent controls a monster: that is how the deck plays on the opponent's turn."},{"es":"Magnamhut busca un Dragon en la End Phase (por ejemplo otro Fallen of Albaz), así que el combo sigue en el turno siguiente aunque te rompan el campo.","en":"Magnamhut adds a Dragon in the End Phase (for example another Fallen of Albaz), so the combo continues next turn even if your board gets broken."},{"es":"Skill Beasts from the Abyss: solo permite sacar del Extra Deck monstruos LIGHT o DARK de Nivel 8 o más; su segundo efecto (una vez por Duelo) manda un Fallen de tu Deck al Cementerio y te da un Bystial más un monstruo que lo mencione.","en":"Beasts from the Abyss Skill: only LIGHT or DARK Level 8 or higher monsters may come from the Extra Deck; its second effect (once per Duel) sends a Fallen from your Deck to the GY and gives you a Bystial plus a monster that mentions it."}]},"starters":[{"cards":["Fallen of Albaz","Branded Fusion"],"route":{"es":"Branded Fusion con Fallen of Albaz y un Bystial del Deck como material (Bystial es Dragon, DARK, 2500 de ATK): sale Lubellion, Titaniklad o Alba-Lenatus sin gastar la Invocación Normal.","en":"Branded Fusion with Fallen of Albaz and a Bystial from the Deck as material (Bystial is a DARK Dragon with 2500 ATK): Lubellion, Titaniklad or Alba-Lenatus comes out without using the Normal Summon."}},{"cards":["Blazing Cartesia, the Virtuous","Fallen of Albaz"],"route":{"es":"Con Fallen en el Cementerio (el Skill lo manda desde el Deck), Cartesia se Invoca de la mano y en la Main Phase hace una Fusión de Nivel 8 o más con monstruos de la mano o el campo, como Efecto Rápido.","en":"With Fallen in the GY (the Skill sends it from the Deck), Cartesia Special Summons from hand and, in the Main Phase, Fusion Summons a Level 8 or higher monster from hand or field as a Quick Effect."}},{"cards":["Bystial Magnamhut","Bystial Druiswurm"],"route":{"es":"Si el rival tiene un monstruo y hay un LIGHT o DARK en un Cementerio, el Bystial entra como Efecto Rápido en su turno; Magnamhut busca un Dragon al final y Druiswurm, al irse del campo al Cementerio, manda al Cementerio un monstruo Invocado Especial del rival.","en":"If the opponent has a monster and a LIGHT or DARK is in a GY, the Bystial comes in as a Quick Effect on their turn; Magnamhut adds a Dragon at the end and Druiswurm, when sent from the field to the GY, sends an opposing Special Summoned monster to the GY."}}],"chokepoints":[{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a la activación de un Bystial.","en":"In response to a Bystial's activation."},"loss":{"es":"Con Lancea resuelta ninguno puede banishear, y el Bystial necesita banishear para Invocarse. Jugá primero la Fusión que no depende de banish y guardá los Bystial para después de ver si la tienen.","en":"Once Lancea resolves neither player can banish, and the Bystial needs to banish to Summon itself. Play the Fusion that does not rely on banish first and keep the Bystials until you see if they have it."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse un Bystial o Springans Kitt.","en":"When a Bystial or Springans Kitt activates."},"loss":{"es":"Niega cualquier efecto que banishee del Cementerio o agregue desde el Cementerio, y casi todo el deck lo hace. Si ves que el rival juega Ghost Belle, aguantá y jugá la parte del combo que no toca el Cementerio.","en":"It negates any effect that banishes from the GY or adds from the GY, and most of the deck does one of the two. If the opponent plays Ghost Belle, wait it out and play the part of the combo that does not touch the GY."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Branded Lost, Springans Kitt, Tri-Brigade Mercourier).","en":"Right after the first search resolves (Branded Lost, Springans Kitt, Tri-Brigade Mercourier)."},"loss":{"es":"Después de esa búsqueda no podés agregar nada más del Deck en el turno. Ordená el combo para que la búsqueda que más necesitás sea la primera y el resto salga de Branded Fusion, que usa el Deck como material y no lo agrega a la mano.","en":"After that search nothing else can be added from the Deck this turn. Sequence the combo so the search you need most comes first and the rest comes from Branded Fusion, which uses the Deck as material instead of adding."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno (Fallen, Cartesia y dos o tres Fusiones llegan rápido).","en":"On the fifth Summon of the turn (Fallen, Cartesia and two or three Fusions get there fast)."},"loss":{"es":"Tributa todo tu campo y te deja un Token enorme. Contá las Invocaciones: si ya vas por cuatro, cerrá con una Fusión menos y dejá el Bystial para el turno del rival.","en":"It Tributes your whole board and leaves you a huge Token. Count Summons: if you are at four, stop one Fusion early and keep the Bystial for the opponent's turn."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"Cada Invocación Especial desde el Extra Deck le da una carta al rival (se activa si no controla cartas).","en":"Each Special Summon from the Extra Deck gives the opponent a card (it activates if they control no cards)."},"loss":{"es":"Branded hace varias Fusiones por turno y cada una le regala una carta al rival. Usá menos Fusiones intermedias si la ves venir.","en":"Branded makes several Fusions per turn and each one gifts the opponent a card. Use fewer intermediate Fusions if you see it coming."}}],"skills":[{"name":"Beasts from the Abyss","why":{"es":"Es el Skill del mazo (100% de las listas). Su segundo efecto asegura la apertura: revelás un Bystial o Cartesia, mandás un Fallen del Deck al Cementerio y agregás un Bystial y un monstruo que mencione a Fallen. El tercero, con solo el rival con monstruo, manda a The Bystial Alba Los desde fuera del Deck al Cementerio para buscar otro Bystial.","en":"The deck's Skill (100% of lists). Its second effect secures the opening: reveal a Bystial or Cartesia, send a Fallen from the Deck to the GY and add a Bystial plus a monster that mentions Fallen. The third, with only the opponent controlling a monster, sends The Bystial Alba Los from outside the Deck to the GY to add another Bystial."}}],"side":{"first":{"in":[{"card":"Ghost Belle & Haunted Mansion","qty":1,"why":{"es":"Yendo primero el rival juega su turno con el Cementerio lleno de efectos (Memento, Horus): Belle frena revivir y banish.","en":"Going first the opponent plays a GY-heavy turn (Memento, Horus): Belle stops revival and banish effects."}}],"out":[{"card":"Screams of the Branded","qty":1,"why":{"es":"Yendo primero ese Trap es de las cartas más lentas: no hay turno para recuperar una Fusión del Cementerio.","en":"Going first that Trap is among the slowest cards: there is no turn to bring a Fusion back from the GY."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo rompés el campo del rival con una sola carta y negás sus efectos de monstruo antes de tu combo.","en":"Going second you break the opponent's board with a single card and negate their monster effects before your combo."}},{"card":"Lava Golem","qty":1,"why":{"es":"Yendo segundo el rival ya tiene monstruos: Lava Golem tributa dos de ellos y es una salida que no pide Extra Deck.","en":"Going second the opponent already has monsters: Lava Golem Tributes two of them and is an out that does not need the Extra Deck."}}],"out":[{"card":"Screams of the Branded","qty":1,"why":{"es":"Se recorta la recuperación lenta para hacer lugar a cartas que rompen el campo.","en":"The slow recovery card is cut to make room for board breakers."}},{"card":"Branded Sword","qty":1,"why":{"es":"Las fichas de Branded Sword llegan tarde cuando necesitás romper primero el campo del rival.","en":"Branded Sword tokens arrive late when you first need to break the opponent's board."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/horus":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Arma un muro de monstruos Horus de Nivel 8 protegidos: King's Sarcophagus (o Walls of the Imperial Tomb, que toma ese nombre en la Zona de Campo) los hace inmunes a destrucción por efectos que no los apunten.","en":"Builds a wall of protected Level 8 Horus monsters: King's Sarcophagus (or Walls of the Imperial Tomb, which takes that name in the Field Zone) makes them immune to destruction by effects that do not target them."},{"es":"King's Sarcophagus manda cartas de tu mano al Cementerio para mandar Horus del Deck (hasta cuatro veces por turno), y Hapi, Imsety, Qebehsenuef y Duamutef vuelven solos del Cementerio mientras la controlás.","en":"King's Sarcophagus sends cards from your hand to the GY to send Horus monsters from the Deck (up to four times a turn), and Hapi, Imsety, Qebehsenuef and Duamutef come back on their own from the GY while you control it."},{"es":"Canopic Protector responde a cualquier activación del rival e Invoca un Horus de la mano o el Cementerio; Horus the Black Flame Deity entra si uno de los tuyos sale por un efecto del rival y puede mandar todo el resto al Cementerio.","en":"Canopic Protector answers any opposing activation and Special Summons a Horus from hand or GY; Horus the Black Flame Deity comes in if one of yours leaves the field to an opposing effect and can send all other monsters to the GY."},{"es":"Lleva muchos handtraps (Droll, Nibiru, Veiler, Ghost Belle, D.D. Crow) y Lava Golem: yendo primero, Droll más Nibiru suelen ser la mano ganadora.","en":"Plays many hand traps (Droll, Nibiru, Veiler, Ghost Belle, D.D. Crow) and Lava Golem: going first, Droll plus Nibiru is often the winning hand."}]},"starters":[{"cards":["Walls of the Imperial Tomb"],"route":{"es":"Activada como carta de campo es King's Sarcophagus y busca un monstruo Horus (normalmente Imsety) a la mano, dejando una carta de la mano abajo del Deck.","en":"Activated as a Field Spell it is King's Sarcophagus and adds a Horus monster (usually Imsety) to hand, putting a card from hand on the bottom of the Deck."}},{"cards":["Imsety, Glory of Horus"],"route":{"es":"Mandando dos cartas de la mano (incluida ella) al Cementerio agregás King's Sarcophagus del Deck y robás 1: una sola carta abre el turno.","en":"Sending two cards from hand (itself included) to the GY adds King's Sarcophagus from the Deck and draws 1: a single card opens the turn."}},{"cards":["King's Sarcophagus","Canopic Protector"],"route":{"es":"Sarcophagus vuelca Horus al Cementerio y Canopic Protector (seteada) los trae al campo en la respuesta a cualquier carta del rival: muro de cuerpos en su turno.","en":"Sarcophagus dumps Horus monsters into the GY and a Set Canopic Protector brings them to the field in response to any opposing card: a wall of bodies on their turn."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda o robo extra (Walls, Imsety).","en":"Right after the first search or extra draw resolves (Walls, Imsety)."},"loss":{"es":"Corta el resto de las búsquedas del turno. Buscá lo más importante primero (normalmente King's Sarcophagus) y recordá que Sarcophagus manda al Cementerio, no agrega a la mano.","en":"It stops the rest of the turn's searches. Search the most important card first (usually King's Sarcophagus) and remember Sarcophagus sends to the GY instead of adding to hand."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Cuando activás Canopic Protector, Hapi, Imsety o Qebehsenuef para Invocar desde el Cementerio.","en":"When you activate Canopic Protector, Hapi, Imsety or Qebehsenuef to Special Summon from the GY."},"loss":{"es":"Niega esa activación. Activá primero con la pieza que menos importa para gastar a Belle, y guardá a Horus the Black Flame Deity, que entra desde la mano y no desde el Cementerio.","en":"It negates that activation. Activate with the piece that matters least to bait Belle, and hold Horus the Black Flame Deity, which comes in from the hand rather than the GY."}},{"card":"Number 68: Sanaphond the Sky Prison","step":"main","stepText":{"es":"En la Main Phase del rival, desasocia un material: hasta el final de tu próximo turno nadie Invoca del Cementerio.","en":"In the opponent's Main Phase, detaching a material: until the end of your next turn neither player Special Summons from the GY."},"loss":{"es":"Apaga las revividas del Cementerio (Hapi, Imsety, Qebehsenuef, Duamutef, Canopic desde el Cementerio). Los jugadores de Horus la usan contra decks de Cementerio: armá el turno con lo que ya tenés en mano y campo.","en":"It shuts off GY revival (Hapi, Imsety, Qebehsenuef, Duamutef, Canopic from the GY). Horus players use it against GY decks: build the turn with what you already have in hand and on the field."}},{"card":"Necrovalley","step":"main","stepText":{"es":"En la Main Phase del rival, reemplazando a Walls of the Imperial Tomb en la Zona de Campo.","en":"In the opponent's Main Phase, replacing Walls of the Imperial Tomb in the Field Zone."},"loss":{"es":"Niega los efectos que mueven cartas del Cementerio a otro lugar, o sea toda la revivida de Horus, y saca a Walls de la Zona de Campo. Si tenés otro Walls en la mano, podés reemplazar a Necrovalley con él; si no, jugá con lo que hay en el campo.","en":"It negates effects that move cards from the GY to another place, which is all of Horus's revival, and it removes Walls from the Field Zone. If you have another Walls in hand you can replace Necrovalley with it; if not, play with what is on the field."}}],"skills":[{"name":"Precious Cards of the Dark","why":{"es":"El más usado (58%). Una vez por turno y hasta dos por Duelo (si el Deck tiene 6 o más monstruos DARK): mandás una carta al fondo del Deck o al Cementerio y robás 2, más 1 extra si vas segundo en tu primer turno. Sirve para llegar a Sarcophagus o a un handtrap.","en":"The most used (58%). Once per turn and up to twice per Duel (if the Deck has 6 or more DARK monsters): place a card on the bottom or send it to the GY and draw 2, plus 1 extra if you are going second on your first turn. It finds Sarcophagus or a hand trap."}},{"name":"Precious Cards of the Light","why":{"es":"La misma versión del Skill con otro requisito: 6 o más monstruos LIGHT en el Deck. También hay listas de Horus de King of Games que la usan.","en":"The same Skill with a different requirement: 6 or more LIGHT monsters in the Deck. Some King of Games Horus lists use it too."}},{"name":"Precious Cards of the Wind","why":{"es":"Otra variante del mismo robo: pide 6 o más monstruos WIND (Hapi, Mulcharmy Fuwalos y similares). Se elige según los atributos que lleve tu lista.","en":"Another variant of the same draw: it needs 6 or more WIND monsters (Hapi, Mulcharmy Fuwalos and similar). Pick by the attributes your list runs."}}],"side":{"first":{"in":[{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Yendo primero armás el muro y Ogre destruye un monstruo o una Continua que active su efecto: Canopic Protector del espejo, por ejemplo.","en":"Going first you build the wall and Ogre destroys a monster or Continuous card that activates its effect: the mirror's Canopic Protector, for example."}},{"card":"Ghost Mourner & Moonlit Chill","qty":1,"why":{"es":"Frena una Invocación Especial del rival en su turno y le cuesta daño si ese monstruo deja el campo.","en":"It stops an opposing Special Summon on their turn and costs them damage if that monster leaves the field."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Fuwalos solo se activa si no controlás cartas, y yendo primero ya tenés Walls o Canopic en la mesa en el turno del rival.","en":"Fuwalos only activates if you control no cards, and going first you already have Walls or Canopic on the table on the opponent's turn."}}]},"second":{"in":[{"card":"Lava Golem","qty":1,"why":{"es":"Yendo segundo el rival ya armó cuerpos: Lava Golem tributa dos de ellos y es la única \"invocación normal\" que usa el mazo.","en":"Going second the opponent already built bodies: Lava Golem Tributes two of them and is the only \"normal summon\" the deck uses."}}],"out":[{"card":"Soul Servant","qty":1,"why":{"es":"Es la carta de ranura libre de la lista (un +1 de Dark Magician of Destruction); un Lava Golem más rinde más cuando vas segundo.","en":"It is the list's flex slot (a +1 for Dark Magician of Destruction); one more Lava Golem does more when you go second."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/snake-eye":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Combo de FIRE de Nivel 1: Snake-Eye Ash, Oak, Birch y Poplar se encadenan para llegar a Snake-Eyes Flamberge Dragon, que deja monstruos en la Zona de Magias y Trampas como Magias Continuas y los trae de vuelta en el turno del rival.","en":"Level 1 FIRE combo: Snake-Eye Ash, Oak, Birch and Poplar chain into Snake-Eyes Flamberge Dragon, which leaves monsters in the Spell & Trap Zone as Continuous Spells and brings them back on the opponent's turn."},{"es":"Divine Temple of the Snake-Eye revive uno de esos monstruos cada vez que el rival Invoca, y Diabellstar the Black Witch busca los Sinful Spoils (Original, Subversion, Rciela, Silvera) que sostienen el campo.","en":"Divine Temple of the Snake-Eye brings back one of those monsters each time the opponent Summons, and Diabellstar the Black Witch fetches the Sinful Spoils (Original, Subversion, Rciela, Silvera) that hold the board."},{"es":"El cierre típico es Lyrilusc - Assembled Nightingale (Xyz Rango 1 que ataca directo) o Promethean Princess con Topologic Trisbaena, más I:P Masquerena y Knightmare Phoenix para romper cartas.","en":"The typical finish is Lyrilusc - Assembled Nightingale (a Rank 1 Xyz that attacks directly) or Promethean Princess with Topologic Trisbaena, plus I:P Masquerena and Knightmare Phoenix to break cards."},{"es":"Skill Eyes of Sovereign Defiance: tu daño de efecto es 0 y en tu Main Phase solo podés Invocar monstruos FIRE o Diabellstar (el Extra Deck queda libre). Su segundo efecto trae hasta 2 Sinful Spoils o Divine Temple.","en":"Eyes of Sovereign Defiance Skill: your effect damage is 0 and in your Main Phase you can only Summon FIRE monsters or Diabellstar (the Extra Deck is exempt). Its second effect fetches up to 2 Sinful Spoils or Divine Temple."}]},"starters":[{"cards":["Diabellstar the Black Witch"],"route":{"es":"Se Invoca de la mano mandando una carta al Cementerio y Setea un Sinful Spoils del Deck; es el único monstruo no FIRE que el Skill te deja Invocar, y WANTED la trae del Deck o del Cementerio.","en":"Special Summons from hand by sending a card to the GY and Sets a Sinful Spoils from the Deck; it is the only non-FIRE monster the Skill lets you Summon, and WANTED brings it from the Deck or GY."}},{"cards":["Snake-Eye Ash","Snake-Eye Oak"],"route":{"es":"Ash busca un FIRE de Nivel 1 y Ash u Oak, mandando 2 cartas boca arriba al Cementerio, Invocan otro Snake-Eye de la mano o el Deck: así llegás a Flamberge Dragon.","en":"Ash adds a Level 1 FIRE and Ash or Oak, sending 2 face-up cards to the GY, Special Summon another Snake-Eye from hand or Deck: that is how you reach Flamberge Dragon."}},{"cards":["Divine Temple of the Snake-Eye","Snake-Eyes Poplar"],"route":{"es":"Poplar (Invocación Normal) busca un Spell/Trap Snake-Eye; Temple deja un Snake-Eye como Magia Continua y le da +1100 de ATK a los FIRE de Nivel 1.","en":"Poplar (Normal Summon) adds a Snake-Eye Spell/Trap; Temple places a Snake-Eye as a Continuous Spell and gives Level 1 FIRE monsters +1100 ATK."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Poplar, Ash, WANTED).","en":"Right after the first search resolves (Poplar, Ash, WANTED)."},"loss":{"es":"Corta el resto de las búsquedas del turno. Abrí con la que más necesitás y apoyate en Oak y Original Sinful Spoils, que Invocan o recuperan del Cementerio.","en":"It cuts the rest of the turn's searches. Open with the one you need most and lean on Oak and Original Sinful Spoils, which Summon or recover from the GY."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Oak, Flamberge o Promethean para revivir o agregar desde el Cementerio.","en":"When Oak, Flamberge or Promethean activate to revive or add from the GY."},"loss":{"es":"Niega Invocar o agregar desde el Cementerio, y casi todo el recurso del mazo vive ahí. Jugá primero lo que no toca el Cementerio y guardá a Flamberge.","en":"It negates Summoning or adding from the GY and most of the deck's resources live there. Play what does not touch the GY first and hold Flamberge."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno (Snake-Eye llega a 5 sin esfuerzo).","en":"On the fifth Summon of the turn (Snake-Eye reaches 5 with ease)."},"loss":{"es":"Tributa todo tu campo y los Snake-Eye pierden su ventaja. Frená en 4 Invocaciones si ya tenés una buena base y dejá los Quick Effects de Birch y Temple para su turno.","en":"It Tributes your whole board and Snake-Eye loses its edge. Stop at 4 Summons if you already have a good base and leave Birch's and Temple's Quick Effects for their turn."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Snake-Eye Ash, Flamberge o Diabellstar apenas activan su efecto.","en":"On Snake-Eye Ash, Flamberge or Diabellstar as soon as they activate their effect."},"loss":{"es":"Anula el efecto clave y, seteada, también apaga las Magias/Trampas de esa columna (por ejemplo un Temple). Poné las piezas importantes en columnas distintas.","en":"It negates the key effect and, if Set, also shuts down Spells/Traps in that column (a Temple, for example). Put important pieces in different columns."}},{"card":"Canopic Protector","step":"activation","stepText":{"es":"En respuesta a tu primer efecto, Invoca un Horus de la mano o el Cementerio una vez por Cadena.","en":"In response to your first effect, it Special Summons a Horus from hand or GY once per Chain."},"loss":{"es":"Es la pesadilla del mazo: cada efecto tuyo puede ser respondido con un cuerpo de Nivel 8 protegido. Hay que atraer la primera Canopic con Phoenix o una pieza barata antes del resto.","en":"It is the deck's nightmare: each of your effects can be answered with a protected Level 8 body. Bait the first Canopic with Phoenix or a cheap piece before the rest."}}],"skills":[{"name":"Eyes of Sovereign Defiance","why":{"es":"Es el Skill del mazo (99%). Cambia el daño de efecto a 0 y te limita a FIRE y Diabellstar en la Main Phase, pero su segundo efecto te trae Divine Temple o Sinful Spoils, y el tercero (solo con monstruo rival) manda a Silvera al Cementerio y Setea un WANTED que se activa el mismo turno.","en":"The deck's Skill (99%). It turns your effect damage into 0 and limits you to FIRE and Diabellstar in the Main Phase, but its second effect fetches Divine Temple or Sinful Spoils, and the third (only with an opposing monster) sends Silvera to the GY and Sets a WANTED you can activate the same turn."}}],"side":{"first":{"in":[{"card":"Droll & Lock Bird","qty":2,"why":{"es":"Yendo primero el rival juega su turno con búsquedas: dos Droll cortan su plan, y tenés el turno siguiente completo para usarlas.","en":"Going first the opponent plays a turn full of searches: two Drolls cut their plan, and you have the whole following turn to use them."}}],"out":[{"card":"Hey, Trunade!","qty":2,"why":{"es":"Yendo primero el rival no tiene cartas Seteadas que devolver: Trunade no hace nada en tu primer turno.","en":"Going first the opponent has no Set cards to return: Trunade does nothing in your first turn."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo rompés el campo del rival y negás sus monstruos antes de empezar el combo.","en":"Going second you break the opponent's board and negate their monsters before starting the combo."}}],"out":[{"card":"Sinful Spoils of Doom - Rciela","qty":1,"why":{"es":"Rciela necesita un Spellcaster de Nivel 7 o más y un turno armado: la ranura rinde más como rompe-campo cuando vas segundo.","en":"Rciela needs a Level 7 or higher Spellcaster and an established turn: the slot does more as a board breaker when you go second."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/memento":{"win":{"plan":"otk","pace":"fast","bullets":[{"es":"Gana por ataque directo: Mementotlan Akihiron deja que los Memento de Nivel 9 o más ataquen directo, y Mementoal Tecuhtlica - Combined Creation tiene 5000 de ATK contra 4000 LP de partida. Yendo segundo se puede ganar en el primer turno.","en":"Wins by direct attack: Mementotlan Akihiron lets Level 9 or higher Memento attack directly, and Mementoal Tecuhtlica - Combined Creation has 5000 ATK against 4000 starting LP. Going second it can win on the first turn."},{"es":"Los Memento se destruyen entre sí para buscar o mandar al Cementerio (Dark Blade, Goblin, Mace, Tatsunootoshigo, Angwitch); Ghattic y Akihiron se Invocan solos del Cementerio cuando eso pasa.","en":"Memento destroy each other to search or send to the GY (Dark Blade, Goblin, Mace, Tatsunootoshigo, Angwitch); Ghattic and Akihiron Special Summon themselves from the GY when that happens."},{"es":"Combined Creation se Invoca barajando 5 Memento distintos de la mano y el Cementerio, y una vez por turno, cuando el rival activa algo, Invoca otro Memento. Cierra con respaldo de Trampas (Fracture Dance) y el campo Mementomictlan.","en":"Combined Creation is Special Summoned by shuffling 5 different Memento from hand and GY, and once per turn, when the opponent activates something, it Special Summons another Memento. It finishes with Trap backup (Fracture Dance) and the Mementomictlan field."},{"es":"Es un mazo difícil: el reloj de Duel Links castiga las rutas largas, así que conviene practicar las líneas.","en":"It is a hard deck: the Duel Links timer punishes long lines, so practice your routes."}]},"starters":[{"cards":["Mementotlan Dark Blade","Mementotlan Angwitch"],"route":{"es":"Dark Blade (Invocación Normal) se destruye y trae de Deck un Memento de Nivel 3 o menos (Angwitch); Angwitch busca otro Memento (por ejemplo Tatsunootoshigo) con el que seguís.","en":"Dark Blade (Normal Summon) destroys itself and brings a Level 3 or lower Memento from the Deck (Angwitch); Angwitch adds another Memento (Tatsunootoshigo, for instance) to keep going."}},{"cards":["Mementotlan Shleepy"],"route":{"es":"Shleepy se Invoca y hace una Fusión Memento con monstruos de la mano o el campo: Twin Dragon o Creation King, que a su vez buscan las piezas que faltan.","en":"Shleepy is Summoned and makes a Memento Fusion with monsters from hand or field: Twin Dragon or Creation King, which in turn fetch the missing pieces."}},{"cards":["Mementotlan Goblin","Mementotlan Tatsunootoshigo"],"route":{"es":"Goblin se destruye y manda Tatsunootoshigo y Ghattic al Cementerio; Ghattic se Invoca solo y agrega una carta. Tatsunootoshigo después manda lo que falte para Combined Creation.","en":"Goblin destroys itself and sends Tatsunootoshigo and Ghattic to the GY; Ghattic Special Summons itself and adds a card. Tatsunootoshigo then sends what Combined Creation still needs."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Angwitch, Mace, Twin Dragon, Bone Party).","en":"Right after the first search resolves (Angwitch, Mace, Twin Dragon, Bone Party)."},"loss":{"es":"Corta las demás búsquedas del turno y el mazo depende de varias. Practicá la línea que arranca por la búsqueda más importante y la que sigue usando solo el Cementerio.","en":"It stops the other searches of the turn and the deck relies on several. Practice the line that starts with the most important search and the one that keeps going with only the GY."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Ghattic, Akihiron o Angwitch para Invocarse o agregar desde el Cementerio.","en":"When Ghattic, Akihiron or Angwitch activate to Summon or add from the GY."},"loss":{"es":"Niega el efecto que reanima o recupera del Cementerio, y casi todos los Memento viven de eso. Dejá a Belle ir a una pieza menor antes de usar el combo largo.","en":"It negates the effect that revives or recovers from the GY, and nearly every Memento lives off that. Let Belle hit a minor piece before using the long combo."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno, algo que Memento alcanza con facilidad.","en":"On the fifth Summon of the turn, something Memento reaches easily."},"loss":{"es":"Tributa todos tus monstruos y deja un Token con el ATK combinado. Contá Invocaciones y no llegues a cinco sin tener el cierre ya resuelto.","en":"It Tributes all your monsters and leaves a Token with the combined ATK. Count Summons and do not reach five without the finish already secured."}},{"card":"Book of Eclipse","step":"main","stepText":{"es":"En tu Battle Phase, si la tenían Seteada, antes del ataque directo.","en":"In your Battle Phase, if they had it Set, before the direct attack."},"loss":{"es":"Pone todos los monstruos boca abajo en Defensa: Combined Creation no ataca directo ese turno. Es un Quick-Play que el rival debe Setear antes: si ves una Spell Seteada, dejá a otro Memento listo para el siguiente turno.","en":"It turns all monsters face-down Defense: Combined Creation does not attack directly that turn. It is a Quick-Play the opponent must Set first: if you see a Set Spell, leave another Memento ready for the next turn."}},{"card":"Forbidden Droplet","step":"attack","stepText":{"es":"En tu declaración de ataque (si la tenían Seteada) o en la activación de Combined Creation.","en":"On your attack declaration (if they had it Set) or on Combined Creation's activation."},"loss":{"es":"Baja a la mitad el ATK de Combined Creation (5000 a 2500) y niega sus efectos: el daño ya no alcanza para los 4000. Dejá un Memento más para hacer daño o tené otra vía de victoria.","en":"It halves Combined Creation's ATK (5000 to 2500) and negates its effects: the damage no longer reaches 4000. Keep another Memento for damage or have a second win route."}}],"skills":[{"name":"Precious Cards of the Dark","why":{"es":"El más usado (96%). Si el Deck tiene 6 o más monstruos DARK, una vez por turno y hasta dos veces por Duelo mandás una carta de la mano al fondo del Deck o al Cementerio y robás 2 (más 1 si vas segundo en tu primer turno). Es opcional: según la mano, a veces ni hace falta usarlo.","en":"The most used (96%). If the Deck has 6 or more DARK monsters, once per turn and up to twice per Duel you put a card from hand on the bottom or in the GY and draw 2 (plus 1 if you go second on your first turn). It is optional: depending on the hand you sometimes do not need it."}}],"side":{"first":{"in":[{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Yendo primero esperás el turno del rival: Nibiru castiga una jugada larga y Memento no la lleva en el Main.","en":"Going first you wait for the opponent's turn: Nibiru punishes a long play and Memento does not run it in the Main."}}],"out":[{"card":"Hey, Trunade!","qty":1,"why":{"es":"Yendo primero el rival no tiene cartas Seteadas en tu turno; Trunade queda muerta.","en":"Going first the opponent has no Set cards on your turn; Trunade is dead."}}]},"second":{"in":[{"card":"Lava Golem","qty":1,"why":{"es":"Yendo segundo el rival ya armó cuerpos: si Akihiron o Combined Creation quedan negados, Golem le saca dos monstruos y te deja pelear con ataques normales.","en":"Going second the opponent already built bodies: if Akihiron or Combined Creation get negated, Golem takes two monsters and lets you fight with normal attacks."}}],"out":[{"card":"Mementotlan-Horned Dragon","qty":1,"why":{"es":"Pide tres Memento distintos en el Cementerio: es una pieza de toolbox, más lenta que la presión de un Golem.","en":"It asks for three different Memento in the GY: it is a toolbox piece, slower than a Golem's pressure."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/vaalmonica":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Juega con Pendulum Zones (las da el Skill) y junta Resonance Counters ganando LP con un Hechizo y recibiendo daño con otro: Angello y Dimonno, en las escalas, los acumulan.","en":"Plays with Pendulum Zones (given by the Skill) and gathers Resonance Counters by gaining LP with one Spell and taking damage with another: Angello and Dimonno, in the scales, accumulate them."},{"es":"Con 3 contadores en la escala sale Duralume o Zebufera por Link; Zebufera protege lo tuyo de la destrucción gastando 3 contadores, y Varar niega y destruye una Invocación del rival.","en":"With 3 counters on a scale, Duralume or Zebufera comes out by Link Summon; Zebufera protects your cards from destruction by spending 3 counters, and Varar negates and destroys an opposing Summon."},{"es":"Los Traps cierran el turno: Vaalmonica Ereditare niega una carta si controlás un Link Vaalmonica, Followed Rhythm destruye o devuelve a la mano, y Creation Link Summon cuando el rival Invoca.","en":"Traps finish the turn: Vaalmonica Ereditare negates a card if you control a Vaalmonica Link, Followed Rhythm destroys or bounces, and Creation Link Summons when the opponent Summons."},{"es":"Gana las partidas largas: Ereditare baraja Vaalmonica del Cementerio y del banish al Deck y Disarmonia los recupera: el mazo se recarga solo.","en":"It wins long games: Ereditare shuffles Vaalmonica from the GY and banishment into the Deck and Disarmonia gets them back: the deck refills itself."}]},"starters":[{"cards":["Angello Vaalmonica","Dimonno Vaalmonica"],"route":{"es":"Descartando una carta, Angello trae a Dimonno del Deck (o viceversa) y los dos van a las Pendulum Zones: base para contadores y para Link Summon.","en":"Discarding a card, Angello takes Dimonno from the Deck (or vice versa) and both go to the Pendulum Zones: the base for counters and for Link Summons."}},{"cards":["Selettrice Vaalmonica"],"route":{"es":"Por Invocación Normal busca cualquier carta Vaalmonica, y si la mandás al Cementerio con dos Vaalmonica en las escalas, vuelve a la mano.","en":"Normal Summoned it adds any Vaalmonica card, and if you send it to the GY with two Vaalmonica in the Pendulum Zones it returns to hand."}},{"cards":["Vaalmonica Scelta"],"route":{"es":"Con un Vaalmonica en la escala elegís: ganar 500 LP y robar 2, o recibir 250 de daño y agregar un Vaalmonica Spell/Trap. Con las escalas puestas, los dos efectos dan contadores.","en":"With a Vaalmonica in the Pendulum Zone you choose: gain 500 LP and draw 2, or take 250 damage and add a Vaalmonica Spell/Trap. With the scales set, both effects give counters."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Selettrice, Scelta, Versare).","en":"Right after the first search resolves (Selettrice, Scelta, Versare)."},"loss":{"es":"Corta las búsquedas siguientes del turno y las listas ganadoras lo marcan como lo que más duele al mazo. Abrí con la búsqueda que más necesitás.","en":"It cuts the next searches of the turn and winning lists name it as what hurts the deck most. Open with the search you need most."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Selettrice o Disarmonia para agregar desde el Cementerio.","en":"When Selettrice or Disarmonia activate to add from the GY."},"loss":{"es":"Niega esa recuperación y con ella el bucle de Ereditare más Disarmonia. Guardá una segunda forma de recuperar y no dependas de un único recurso.","en":"It negates that recovery and with it the Ereditare plus Disarmonia loop. Keep a second way to recover and do not rely on a single resource."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"En cada Link Summon: roba una carta al rival por cada Invocación desde el Extra Deck.","en":"On each Link Summon: draws the opponent a card for each Extra Deck Summon."},"loss":{"es":"Vaalmonica hace varios Links por turno y las listas son de 20 a 23 cartas, así que cada robo regalado pesa. Limitá los Links intermedios.","en":"Vaalmonica makes several Links per turn and lists are 20 to 23 cards, so each gifted draw hurts. Limit intermediate Links."}},{"card":"Dark Ruler No More","step":"main","stepText":{"es":"En la Main Phase del rival, antes de tu Link Summon o durante su Battle Phase.","en":"In the opponent's Main Phase, before your Link Summon or during their Battle Phase."},"loss":{"es":"Niega los efectos de monstruos de tu campo y nadie responde con efectos de monstruo: Varar y Zebufera no pueden usar su negación ni su protección. Los Traps Vaalmonica siguen en pie.","en":"It negates your monsters' effects and nobody can respond with monster effects: Varar and Zebufera cannot use their negation or protection. The Vaalmonica Traps remain."}}],"skills":[{"name":"Whispers of Good and Evil","why":{"es":"Es el Skill del mazo (100%): al inicio del Duelo te da las Pendulum Zones y evita que te apunten los Vaalmonica de la escala. Su segundo efecto busca un Vaalmonica revelando un monstruo; el tercero (si el rival controla una carta) Setea un Vaalmonica Spell/Trap activable el mismo turno y, si venía de la mano, robás 2 y barajás 1.","en":"The deck's Skill (100%): at the start of the Duel it gives you the Pendulum Zones and prevents opponents from targeting the Vaalmonica in them. Its second effect adds a Vaalmonica by revealing a monster; the third (if the opponent controls a card) Sets a Vaalmonica Spell/Trap you can activate the same turn and, if from hand, you draw 2 and shuffle 1."}}],"side":{"first":{"in":[{"card":"Droll & Lock Bird","qty":2,"why":{"es":"Yendo primero esperás el turno del rival y Droll corta su búsqueda; las listas ganadoras la piden \"este formato\", sin pasarse.","en":"Going first you wait for the opponent's turn and Droll cuts their search; winning lists ask for it \"in this format\", without overdoing it."}}],"out":[{"card":"Forbidden Droplet","qty":1,"why":{"es":"Droplet rinde más yendo segundo (manda Creation al Cementerio con contadores); yendo primero queda floja.","en":"Droplet does more going second (it sends Creation to the GY for counters); going first it is weaker."}},{"card":"Book of Eclipse","qty":1,"why":{"es":"Yendo primero el rival no tiene campo que romper en tu primer turno.","en":"Going first the opponent has no board to break in your first turn."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo es el rompe-campo del rival antes de armar tu tablero, y se puede robar con las cartas de robo de Vaalmonica.","en":"Going second it is your board breaker before setting up, and it can be drawn with Vaalmonica's draw cards."}}],"out":[{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"El rival juega primero y rara vez llega a 5 Invocaciones; la ranura se usa mejor como rompe-campo.","en":"The opponent plays first and rarely reaches 5 Summons; the slot works better as a board breaker."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/centur-ion":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Centur-Ion deja sus monstruos en la Zona de Magias y Trampas como Trampas Continuas (con Trudea, Emblema Oath, Bonds) y los Invoca de ahí en la Main Phase; Emeth VI entra en el turno del rival.","en":"Centur-Ion places its monsters in the Spell & Trap Zone as Continuous Traps (with Trudea, Emblema Oath, Bonds) and Special Summons them from there in the Main Phase; Emeth VI comes in on the opponent's turn."},{"es":"Stand Up Centur-Ion! permite hacer un Synchro apenas se Invoca Especialmente un monstruo; el cierre usa Shooting Quasar Dragon (niega y destruye), Red Supernova Dragon (banishea todo el campo rival cuando activa un efecto o ataca) y Crimson Dragon.","en":"Stand Up Centur-Ion! lets you Synchro Summon whenever a monster is Special Summoned; the finish uses Shooting Quasar Dragon (negate and destroy), Red Supernova Dragon (banishes the opposing board when they activate an effect or attack) and Crimson Dragon."},{"es":"Skill The Courage to Rise: en tu turno solo podés Invocar Centur-Ion (el Extra Deck queda libre), y aun así hay lugar para handtraps (Effect Veiler, Ghost Belle, D.D. Crow) que juegan en el turno del rival.","en":"The Courage to Rise Skill: on your turn you can only Summon Centur-Ion (the Extra Deck is exempt), and there is still room for hand traps (Effect Veiler, Ghost Belle, D.D. Crow) that play on the opponent's turn."},{"es":"Una lista de King of Games dice que el mazo juega a través de los handtraps del meta (Droll, Fuwalos): buena parte de la apertura pone cartas del Deck en la Zona de Magias y Trampas en lugar de agregarlas a la mano.","en":"One King of Games list says the deck plays through the meta's hand traps (Droll, Fuwalos): much of the opening places cards from the Deck into the Spell & Trap Zone instead of adding them to hand."}]},"starters":[{"cards":["Centur-Ion Primera"],"route":{"es":"Invocación Normal: agrega una carta Centur-Ion; como Trampa Continua, se Invoca sola en la Main Phase. Es la apertura de una sola carta.","en":"Normal Summon: adds a Centur-Ion card; as a Continuous Trap, it Special Summons itself in the Main Phase. It is a one-card opening."}},{"cards":["Centur-Ion Trudea"],"route":{"es":"Pone a Trudea y a otro Centur-Ion de la mano o el Deck en la Zona de Magias y Trampas; Trudea vuelve al campo y puede subir a Nivel 8 para el Synchro.","en":"Places Trudea and another Centur-Ion from hand or Deck in the Spell & Trap Zone; Trudea returns to the field and can go up to Level 8 for the Synchro."}},{"cards":["Emblema Oath","Stand Up Centur-Ion!"],"route":{"es":"Emblema Oath pone un Centur-Ion del Deck como Trampa Continua o Setea una Spell/Trap Centur-Ion; Stand Up hace el Synchro en cuanto se Invoca un monstruo.","en":"Emblema Oath places a Centur-Ion from the Deck as a Continuous Trap or Sets a Centur-Ion Spell/Trap; Stand Up Synchro Summons as soon as a monster is Summoned."}}],"chokepoints":[{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta Invocación del turno, justo antes del Synchro final.","en":"On the fifth Summon of the turn, right before the final Synchro."},"loss":{"es":"Tributa todos los monstruos del campo y deja un Token con el ATK combinado de lo que armaste. Armá la parte de Synchro más cara en cuarto lugar y guardá el resto para el turno del rival.","en":"It Tributes every monster on the field and leaves a Token with the combined ATK of what you built. Do the most expensive Synchro fourth and save the rest for the opponent's turn."}},{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a Emblema Salvation, Phalanx o Red Supernova Dragon.","en":"In response to Emblema Salvation, Phalanx or Red Supernova Dragon."},"loss":{"es":"Ninguno puede banishear por el resto del turno, y el mazo banishea para romper cartas: Salvation, Phalanx y Red Supernova quedan sin efecto. Jugá primero lo que no banishea (Quasar, True Awakening).","en":"Neither player can banish for the rest of the turn, and the deck banishes to break cards: Salvation, Phalanx and Red Supernova lose their effect. Play what does not banish first (Quasar, True Awakening)."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Legatia, Primera Primus o Auxila apenas activan su efecto al ser Invocados.","en":"On Legatia, Primera Primus or Auxila as soon as they activate on Summon."},"loss":{"es":"Anula el efecto de búsqueda o de roba/destrucción del Synchro. Dejá que respondan con Impermanence a una pieza menor antes de lo importante.","en":"It negates the Synchro's search or draw/destroy effect. Let them spend Impermanence on a minor piece before the important one."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (Primera, Auxila o Primera Primus).","en":"Right after the first search resolves (Primera, Auxila or Primera Primus)."},"loss":{"es":"Corta las búsquedas siguientes, pero Emblema Oath (que Setea desde el Deck) y las colocaciones en la Zona de Magias y Trampas siguen funcionando. Por eso el mazo juega bien contra Droll.","en":"It stops later searches, but Emblema Oath (which Sets from the Deck) and placements into the Spell & Trap Zone still work. That is why the deck plays well against Droll."}}],"skills":[{"name":"The Courage to Rise","why":{"es":"Es el Skill del mazo (95%). Durante tu turno solo podés Invocar Centur-Ion (salvo Extra Deck), su segundo efecto revela un Centur-Ion y agrega otro del Deck, y el tercero (con Legatia o monstruo rival) busca una carta Emblema y pone un Centur-Ion en el Cementerio o en la Zona de Magias y Trampas.","en":"The deck's Skill (95%). During your turn you can only Summon Centur-Ion (except from the Extra Deck), its second effect reveals a Centur-Ion and adds another from the Deck, and the third (with Legatia or an opposing monster) adds an Emblema card and sends a Centur-Ion to the GY or places it in the Spell & Trap Zone."}}],"side":{"first":{"in":[{"card":"Forbidden Droplet","qty":1,"why":{"es":"Quick-Play: Seteada en tu primer turno se activa en el turno del rival, que es cuando más necesitás frenar su jugada yendo primero.","en":"Quick-Play: Set in your first turn it activates on the opponent's turn, which is when you most need to stop their play going first."}}],"out":[{"card":"Synchro Rumble","qty":1,"why":{"es":"Yendo primero queda como seguimiento lento y su restricción de Extra Deck pesa en tu turno de armado.","en":"Going first it is a slow follow-up and its Extra Deck restriction weighs on your setup turn."}}]},"second":{"in":[{"card":"Dark Ruler No More","qty":1,"why":{"es":"Yendo segundo rompe el campo del rival antes de tu turno de armado y nadie responde con efectos de monstruo.","en":"Going second it breaks the opponent's board before your setup turn and nobody can respond with monster effects."}}],"out":[{"card":"Synchro Rumble","qty":1,"why":{"es":"Es la carta menos necesaria cuando ya tenés que romper campo en vez de revivir Synchros.","en":"It is the least necessary card when you need to break a board instead of reviving Synchros."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/dark-magician":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Roba muchas cartas con Soul Servant, Magicians' Souls y Coach King Giantrainer (7 u 8 cartas en el primer turno según las listas) y cierra con un tablero de interrupciones.","en":"Draws many cards with Soul Servant, Magicians' Souls and Coach King Giantrainer (7 or 8 cards on the first turn according to lists) and finishes with a board of interruptions."},{"es":"El cierre típico: I:P Masquerena, S:P Little Knight o Red-Eyes Dark Dragoon, Dark Magical Circle (banish), Eternal Soul, Magicians' Combination (negación) y Number 90: Galaxy-Eyes Photon Lord.","en":"The typical finish: I:P Masquerena, S:P Little Knight or Red-Eyes Dark Dragoon, Dark Magical Circle (banish), Eternal Soul, Magicians' Combination (negation) and Number 90: Galaxy-Eyes Photon Lord."},{"es":"Timaeus the United Dragon es el centro: se Invoca de la mano mandando al Cementerio un Spellcaster o una S/T de Dark Magician, y hace Fusión cada turno. Si lo abrís, jugás a través de Droll.","en":"Timaeus the United Dragon is the center: it Special Summons from hand by sending a Spellcaster or a Dark Magician S/T, and Fusion Summons each turn. If you open it, you play through Droll."},{"es":"Dark Magical Curtain (Quick-Play) pone un DARK Spellcaster en ambos lados sin efectos, y el Skill es de su propio arquetipo: busca dos cartas de Dark Magician en el turno 1.","en":"Dark Magical Curtain (Quick-Play) puts a DARK Spellcaster on both sides without effects, and the Skill belongs to the archetype: it adds two Dark Magician cards in turn 1."}]},"starters":[{"cards":["Timaeus the United Dragon"],"route":{"es":"Con el Skill (barajás una carta de la mano) se juega Timaeus de la mano y se agregan 2 cartas de Dark Magician; después Fusión con un Spellcaster para Dragoon.","en":"With the Skill (shuffle a card) Timaeus is played from hand and 2 Dark Magician cards are added; then Fusion with a Spellcaster for Dragoon."}},{"cards":["Dark Magical Curtain"],"route":{"es":"Invoca un DARK Spellcaster de la mano o el Deck de cada lado: tuyo es Dark Magician o Dark Magician Girl, que además te agrega una Spell/Trap que lo mencione.","en":"Special Summons a DARK Spellcaster from hand or Deck for each side: yours is Dark Magician or Dark Magician Girl, which also adds a Spell/Trap that mentions it."}},{"cards":["Magician's Rod"],"route":{"es":"Invocación Normal: agrega una Spell/Trap que mencione a Dark Magician (por ejemplo Soul Servant o Dark Magical Circle), que abre el robo masivo.","en":"Normal Summon: adds a Spell/Trap that mentions Dark Magician (such as Soul Servant or Dark Magical Circle), which opens the mass draw."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda o robo (Rod, Souls, Soul Servant).","en":"Right after the first search or draw resolves (Rod, Souls, Soul Servant)."},"loss":{"es":"Yendo primero las listas lo marcan como la carta que más cuesta superar: corta el robo masivo. Abrir Timaeus permite seguir jugando a través de Droll.","en":"Going first lists name it as the card that is hardest to beat: it cuts the mass draw. Opening Timaeus lets you keep playing through Droll."}},{"card":"Artifact Lancea","step":"activation","stepText":{"es":"En respuesta a Dark Magical Circle, S:P Little Knight o cualquier efecto que banishee.","en":"In response to Dark Magical Circle, S:P Little Knight or any banish effect."},"loss":{"es":"Ninguno puede banishear, y esos son los cierres de interrupción del mazo. Las listas la mencionan junto con Droll como lo más difícil yendo primero.","en":"Neither player can banish, and those are the deck's interruption finishers. Lists mention it together with Droll as the hardest thing going first."}},{"card":"Bystial Druiswurm","step":"activation","stepText":{"es":"Entra como Efecto Rápido en el turno del rival banishando un LIGHT o DARK de tu Cementerio.","en":"Comes in as a Quick Effect on the opponent's turn by banishing a LIGHT or DARK from your GY."},"loss":{"es":"Se lleva a tu Dark Magician o Girl del Cementerio, que sostienen Salvation, Eternal Soul y Combination. Con listas Branded el mazo se ve muy apretado.","en":"It takes your Dark Magician or Girl from the GY, which Salvation, Eternal Soul and Combination rely on. Against Branded lists the deck feels very tight."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"En cada Invocación Especial desde el Extra Deck (Dragoon, I:P, S:P, Photon Lord).","en":"On each Special Summon from the Extra Deck (Dragoon, I:P, S:P, Photon Lord)."},"loss":{"es":"Le da una carta al rival por cada monstruo del Extra Deck; con Decks tan chicos cada robo regalado pesa. Recortá las Invocaciones del Extra Deck innecesarias.","en":"It gives the opponent a card per Extra Deck monster; with such small Decks each gifted draw hurts. Cut the unnecessary Extra Deck Summons."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Al activarse Salvation, Eternal Soul o Magicians' Combination para Invocar del Cementerio.","en":"When Salvation, Eternal Soul or Magicians' Combination activate to Special Summon from the GY."},"loss":{"es":"Niega la reanimación de Dark Magician y Dark Magician Girl, que es el motor del mazo. Jugá primero la parte que no pasa por el Cementerio.","en":"It negates the revival of Dark Magician and Dark Magician Girl, the deck's engine. Play the part that does not use the GY first."}}],"skills":[{"name":"The Eye of the United Dragon","why":{"es":"El más usado (85%). Si el Deck tiene 15 o más Dark Magician o cartas que lo mencionen: una vez por Duelo barajás una carta, jugás a Timaeus de la mano y agregás 2 cartas de Dark Magician. El tercero juega a Dark Magician o Girl boca abajo y da The Eye of Timaeus.","en":"The most used (85%). If the Deck has 15 or more Dark Magician or cards that mention it: once per Duel you shuffle a card, play Timaeus from hand and add 2 Dark Magician cards. The third plays Dark Magician or Girl face-down and gives The Eye of Timaeus."}},{"name":"Master of the Dark & Chaos","why":{"es":"Alternativa que varias listas prefieren por consistencia: solo podés Invocar Level 8 LIGHT o EARTH y DARK Spellcasters, pero buscás dos cartas de Dark Magician mandando una Dark Magician Girl de la mano o el Deck al Cementerio. Según una lista, no se puede revivir al Dragon Knight del Cementerio.","en":"An alternative several lists prefer for consistency: you can only Summon Level 8 LIGHT or EARTH and DARK Spellcasters, but you add two Dark Magician cards by sending a Dark Magician Girl from hand or Deck to the GY. According to one list, the Dragon Knight cannot be revived from the GY."}}],"side":{"first":{"in":[{"card":"D.D. Crow","qty":1,"why":{"es":"Contra Branded, Memento y Horus, que viven del Cementerio, Crow quita un recurso en el turno del rival.","en":"Against Branded, Memento and Horus, which live off the GY, Crow removes a resource on the opponent's turn."}},{"card":"Ghost Belle & Haunted Mansion","qty":1,"why":{"es":"Frena el Cementerio del rival en su turno; tomada de las listas que cortaron Lava Golem para este plan.","en":"It stops the opponent's GY on their turn; taken from lists that cut Lava Golem for this plan."}}],"out":[{"card":"Lava Golem","qty":2,"why":{"es":"Yendo primero el rival no tiene monstruos que tributar en tu primer turno: Lava Golem queda muerto en la mano.","en":"Going first the opponent has no monsters to Tribute on your first turn: Lava Golem is dead in hand."}}]},"second":{"in":[{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Yendo segundo no controlás cartas en el turno del rival y Fuwalos se activa; roba por cada Invocación del Extra Deck.","en":"Going second you control no cards on the opponent's turn and Fuwalos activates; it draws for each Extra Deck Summon."}}],"out":[{"card":"Illusion of Chaos","qty":1,"why":{"es":"Dos copias son más de las que hacen falta; las listas recomiendan recortar una para sumar techs.","en":"Two copies are more than needed; lists recommend cutting one to add techs."}}]},"basis":"editorial"},"updated":"2026-10-27"},"dl/shining-sarcophagus":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Shining Sarcophagus busca cada turno una carta que lo mencione y no se destruye por efectos de monstruos; Dark Magician the Magician of Black Magic y Dark Magician Girl the Magician's Apprentice se Invocan solos alrededor de él.","en":"Shining Sarcophagus adds a card that mentions it each turn and cannot be destroyed by monster effects; Dark Magician the Magician of Black Magic and Dark Magician Girl the Magician's Apprentice Special Summon themselves around it."},{"es":"Silent Magician Zero niega una Spell del rival mientras Sarcophagus esté en el campo, Silent Swordsman Zero niega efectos que apunten a tus monstruos de Sarcophagus, y Future Silence y Turn Silence (Quick-Play) buscan y protegen.","en":"Silent Magician Zero negates an opposing Spell while Sarcophagus is on the field, Silent Swordsman Zero negates effects that target your Sarcophagus monsters, and Future Silence and Turn Silence (Quick-Plays) fetch and protect."},{"es":"Gandora-G the Dragon of Destruction se Invoca de la mano pagando la mitad de los LP y destruye y banishea las demás cartas del campo (también las tuyas); con Lava Golem es la salida para campos grandes.","en":"Gandora-G the Dragon of Destruction Special Summons from hand by paying half your LP and destroys and banishes the other cards on the field (yours too); with Lava Golem it is the out for big boards."},{"es":"Number 90 y Number 68 (Xyz de Nivel 8) son el cierre; según jugadores, Number 68 apaga el Cementerio y carga los duelos contra Horus y Memento.","en":"Number 90 and Number 68 (Level 8 Xyz) are the finish; according to players, Number 68 shuts off the GY and carries the matchups against Horus and Memento."}]},"starters":[{"cards":["Dark Magician Girl the Magician's Apprentice"],"route":{"es":"Se Invoca de la mano descartando una carta y, al Invocarse, agrega Shining Sarcophagus del Deck. Con el Skill, revelarla permite buscar hasta 2 cartas del arquetipo.","en":"Special Summons from hand by discarding a card and, when Summoned, adds Shining Sarcophagus from the Deck. With the Skill, revealing her lets you add up to 2 cards from the archetype."}},{"cards":["Gadget Trio"],"route":{"es":"Invocación Normal: agrega Shining Sarcophagus o una Spell/Trap que lo mencione. Si lo destruyen, Setea Stronghold the Hidden Fortress.","en":"Normal Summon: adds Shining Sarcophagus or a Spell/Trap that mentions it. If destroyed, it Sets Stronghold the Hidden Fortress."}},{"cards":["Shining Sarcophagus","Dark Magician the Magician of Black Magic"],"route":{"es":"Con Sarcophagus en el campo, Dark Magician the Magician of Black Magic se Invoca de la mano sin Tributo; una vez por turno Sarcophagus busca la pieza que falta.","en":"With Sarcophagus on the field, Dark Magician the Magician of Black Magic Special Summons from hand without Tribute; once per turn Sarcophagus adds the missing piece."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Apenas resuelve la primera búsqueda (DMG Apprentice, Gadget Trio, Sarcophagus).","en":"Right after the first search resolves (DMG Apprentice, Gadget Trio, Sarcophagus)."},"loss":{"es":"Corta las demás búsquedas del turno. Future Silence usada en tu Draw Phase evita a Droll (agregar en esa fase no activa su efecto); por eso se juegan tres.","en":"It cuts the other searches of the turn. Future Silence used in your Draw Phase avoids Droll (adding in that phase does not trigger it); that is why three are played."}},{"card":"Mulcharmy Fuwalos","step":"summon","stepText":{"es":"En cada Invocación del Extra Deck (Number 90, Number 68, Dragoon).","en":"On each Extra Deck Summon (Number 90, Number 68, Dragoon)."},"loss":{"es":"Le da una carta al rival por cada Xyz que sacás. Sacá solo los Xyz que cambian la partida.","en":"It gives the opponent a card for each Xyz you summon. Only summon the Xyz that change the game."}},{"card":"Powersink Stone","step":"activation","stepText":{"es":"Cada efecto de monstruo activado le pone un contador; con dos, los monstruos del campo dejan de activar efectos.","en":"Each activated monster effect puts a counter on it; with two, monsters on the field cannot activate effects."},"loss":{"es":"El mazo depende de efectos de monstruo (Gadget Trio, Silent Magician Zero, Gandora) y se traba. Activá primero los efectos de Spell (Sarcophagus, Future Silence) y evitá gastar el segundo contador.","en":"The deck relies on monster effects (Gadget Trio, Silent Magician Zero, Gandora) and locks up. Activate Spell effects first (Sarcophagus, Future Silence) and avoid spending the second counter."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Gandora-G apenas activa su efecto, o sobre Silent Magician Zero.","en":"On Gandora-G as soon as it activates, or on Silent Magician Zero."},"loss":{"es":"Anula el efecto con el costo de la mitad de los LP ya pagado en Gandora. Esperá a que respondan con Impermanence a otra pieza o activá Gandora con LP de sobra.","en":"It negates the effect with Gandora's half-LP cost already paid. Wait for them to spend Impermanence on another piece or activate Gandora with LP to spare."}}],"skills":[{"name":"Light the Way to the Future","why":{"es":"Es el Skill del mazo (100%). Anula el daño de efecto salvo el de cartas que mencionan a Shining Sarcophagus. Su segundo efecto busca hasta 2 cartas de Sarcophagus o monstruos que lo mencionen revelando un Spellcaster; el tercero, desde el turno 2, cambia Silent Swordsman Zero por Silent Swordsman LV7 boca abajo y agrega Silent Sword Slash.","en":"The deck's Skill (100%). It nullifies effect damage except from cards that mention Shining Sarcophagus. Its second effect adds up to 2 Sarcophagus cards or monsters that mention it by revealing a Spellcaster; the third, from turn 2, swaps Silent Swordsman Zero for a face-down Silent Swordsman LV7 and adds Silent Sword Slash."}}],"side":{"first":{"in":[{"card":"Ghost Belle & Haunted Mansion","qty":1,"why":{"es":"Contra Horus y Memento, que viven del Cementerio, Belle frena su turno sin depender de una Necrovalley.","en":"Against Horus and Memento, which live off the GY, Belle stops their turn without relying on a Necrovalley."}}],"out":[{"card":"Witch of the Black Forest","qty":1,"why":{"es":"Es la ranura de menos impacto; el handtrap la reemplaza mejor en el turno del rival.","en":"It is the lowest-impact slot; the hand trap replaces it better on the opponent's turn."}}]},"second":{"in":[{"card":"Lava Golem","qty":2,"why":{"es":"Yendo segundo el rival ya tiene monstruos y Golem los tributa; un jugador reportó que triple Golem rindió mucho más que Nibiru, que muchos rivales saben esquivar.","en":"Going second the opponent already has monsters and Golem Tributes them; one player reported triple Golem did far better than Nibiru, which many opponents know how to avoid."}}],"out":[{"card":"Nibiru, the Primal Being","qty":2,"why":{"es":"Yendo segundo Nibiru casi nunca llega a las 5 Invocaciones del rival; Golem rompe el campo ya armado.","en":"Going second Nibiru rarely reaches the opponent's 5 Summons; Golem breaks the board that is already built."}}]},"basis":"editorial"},"updated":"2026-10-27"},"edison/vayu-turbo":{"win":{"plan":"tempo","pace":"fast","bullets":[{"es":"Gana por tempo: llena el Cementerio con Blackwings y Vayu los convierte en Sincros grandes sin gastar Sintonizador ni materiales de la mano.","en":"Wins on tempo: fills the Graveyard with Blackwings and Vayu turns them into big Synchros without spending a Tuner or hand materials."},{"es":"El motor es tirar a Vayu y a Sirocco al Cementerio: Vayu se destierra con un Blackwing no Sintonizador y trae un Sincro cuyo nivel es la suma (Vayu 1 + Sirocco 5 da nivel 6, Armed Wing). Los efectos del Sincro quedan anulados.","en":"The engine is getting Vayu and Sirocco into the Graveyard: Vayu banishes itself plus a non-Tuner Blackwing and brings out a Synchro whose Level is the sum (Vayu 1 + Sirocco 5 gives Level 6, Armed Wing). The Synchro's effects are negated."},{"es":"Dark Grepher y Armageddon Knight mandan DARKs al Cementerio. Hamster y Ryko (motor HRC de la versión Turbo) resuelven los problemas del rival: Ryko destruye una carta y manda 3 del Deck al Cementerio.","en":"Dark Grepher and Armageddon Knight send DARK monsters to the Graveyard. Hamster and Ryko (the HRC engine of the Turbo version) handle the opponent's problem cards: Ryko destroys a card and mills 3."},{"es":"Armor Master (2500 de ATK, no se destruye en batalla) es el cuerpo que sostiene el campo cuando el Sincro de Vayu sale con los efectos anulados.","en":"Armor Master (2500 ATK, cannot be destroyed by battle) is the body that holds the board when Vayu's Synchro comes out with its effects negated."}]},"starters":[{"cards":["Dark Grepher","Blackwing - Sirocco the Dawn"],"route":{"es":"Dark Grepher entra desde la mano descartando a Sirocco (nivel 5 DARK) y su efecto manda a Vayu desde el Deck: los dos quedan en el Cementerio para el Sincro.","en":"Dark Grepher Special Summons from hand by discarding Sirocco (Level 5 DARK) and its effect sends Vayu from the Deck: both are in the Graveyard for the Synchro."}},{"cards":["Armageddon Knight"],"route":{"es":"Al invocarlo manda a Vayu desde el Deck al Cementerio. Es la entrada más barata cuando Sirocco ya está en el Cementerio.","en":"When Summoned it sends Vayu from the Deck to the Graveyard. It is the cheapest entry when Sirocco is already in the Graveyard."}},{"cards":["Super-Nimble Mega Hamster"],"route":{"es":"Hamster boca abajo, al darse vuelta, trae a Ryko boca abajo desde el Deck. Ryko destruye una carta y manda 3 al Cementerio (combustible para Vayu). Es el arranque de la versión Turbo con motor HRC.","en":"Hamster set face-down flips to bring Ryko face-down from the Deck. Ryko destroys a card and mills 3 (fuel for Vayu). It is the opening of the Turbo version with the HRC engine."}}],"chokepoints":[{"card":"Deck Devastation Virus","step":"resolution","stepText":{"es":"Al resolverse: destruye todos los monstruos rivales con 1500 o menos de ATK, durante 3 turnos.","en":"On resolution: destroys all opposing monsters with 1500 or less ATK, for 3 turns."},"loss":{"es":"Vayu (800), Necro Gardna, Plaguespreader y los Armageddon Knight (1400) caen. Guardá un monstruo grande o un Sincro en mano y evitá comprometer cuerpos chicos.","en":"Vayu (800), Necro Gardna, Plaguespreader and the Armageddon Knights (1400) all die. Hold a big monster or a Synchro in hand and avoid committing small bodies."}},{"card":"Imperial Iron Wall","step":"resolution","stepText":{"es":"Cuando Vayu intenta desterrarse a sí mismo y a un Blackwing para traer el Sincro.","en":"When Vayu tries to banish itself and a Blackwing to bring out the Synchro."},"loss":{"es":"Con el Muro puesto nadie puede desterrar, así que el efecto de Vayu no invoca nada. Sacalo con MST o Dust Tornado antes de activar a Vayu.","en":"With the Wall out nobody can banish, so Vayu's effect summons nothing. Remove it with MST or Dust Tornado before activating Vayu."}},{"card":"Royal Decree","step":"activation","stepText":{"es":"Cuando activás una de tus propias Trampas (Bottomless, Prison, Virus, Mirror Force).","en":"When you activate one of your own Traps (Bottomless, Prison, Virus, Mirror Force)."},"loss":{"es":"Anula los efectos de todas las demás Trampas: el mazo juega muchas y pierde su interacción. Sacala con Dust Tornado o MST.","en":"Negates the effects of all other Traps: the deck plays many and loses its interaction. Remove it with Dust Tornado or MST."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Durante tu Main Phase, cuando Grepher o Knight mandan cartas al Cementerio.","en":"During your Main Phase, when Grepher or Knight send cards to the Graveyard."},"loss":{"es":"Todo monstruo que iría al Cementerio se destierra: Vayu y Sirocco no llegan y el motor entero se apaga. Sacala del campo antes de armar la jugada.","en":"Every monster that would go to the Graveyard is banished: Vayu and Sirocco never arrive and the whole engine shuts off. Remove it before starting the play."}}],"side":{"first":{"in":[{"card":"Dust Tornado","qty":2,"why":{"es":"Responde a Royal Decree, Imperial Iron Wall y otras Trampas que cortan el motor, y te deja volver a setear una.","en":"Answers Royal Decree, Imperial Iron Wall and other Traps that cut the engine, and lets you set another one."}}],"out":[{"card":"Card Trooper","qty":1,"why":{"es":"Ocupa un lugar en la mano sin ayudar a mandar a Vayu al Cementerio.","en":"Takes a hand slot without helping send Vayu to the Graveyard."}},{"card":"Trap Dustshoot","qty":1,"why":{"es":"Lenta cuando vas primero y todavía no hay una mano rival que valga la pena mirar.","en":"Slow when you go first and there is no opposing hand worth looking at yet."}}]},"second":{"in":[{"card":"Royal Oppression","qty":2,"why":{"es":"Corta las invocaciones especiales del rival, que debe pagar 800 LP para anular. Los Blackwing la toleran mejor que otros mazos.","en":"Cuts the opponent's Special Summons, who must pay 800 LP to negate. Blackwings tolerate it better than most decks."}}],"out":[{"card":"Plaguespreader Zombie","qty":1,"why":{"es":"Cuerpo flojo cuando necesitás presionar el tablero del rival.","en":"A weak body when you need to pressure the opponent's board."}},{"card":"Chaos Sorcerer","qty":1,"why":{"es":"Pide DARK y LIGHT en el Cementerio para desterrar, y compite con tu propio uso del Cementerio.","en":"Needs DARK and LIGHT in the Graveyard to banish, and competes with your own Graveyard usage."}}]},"basis":"editorial"},"updated":"2026-10-26"},"edison/lightsworn":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gana a base de milling: manda cartas al Cementerio para juntar 4 Lightsworn de nombre distinto y tirar a Judgment Dragon (3000 de ATK) directo desde la mano.","en":"Wins through milling: send cards to the Graveyard to collect 4 differently named Lightsworn and drop Judgment Dragon (3000 ATK) straight from the hand."},{"es":"Judgment Dragon paga 1000 LP para destruir todas las demás cartas del campo: barre el tablero y vos te quedás con el único monstruo.","en":"Judgment Dragon pays 1000 LP to destroy every other card on the field: it wipes the board and leaves you with the only monster."},{"es":"Lyla, Ryko y Celestia sacan cartas del campo rival mientras llenan el Cementerio. Wulf se invoca solo si lo mandás del Deck al Cementerio, y Lumina revive Lightsworn de nivel 4 o menos.","en":"Lyla, Ryko and Celestia remove opposing cards while filling the Graveyard. Wulf Special Summons itself if sent from the Deck to the Graveyard, and Lumina revives Level 4 or lower Lightsworn."},{"es":"El riesgo propio es el Deck: varios Lightsworn mandan cartas al Cementerio cada End Phase y podés quedarte sin cartas antes de cerrar.","en":"The deck's own risk is decking out: several Lightsworn mill cards every End Phase and you can run out of cards before closing."}]},"starters":[{"cards":["Charge of the Light Brigade"],"route":{"es":"Manda 3 al Cementerio y agrega un Lightsworn de nivel 4 o menos: llena el Cementerio y arma la mano con una sola carta.","en":"Sends 3 to the Graveyard and adds a Level 4 or lower Lightsworn: fills the Graveyard and builds the hand with one card."}},{"cards":["Solar Recharge","Ryko, Lightsworn Hunter"],"route":{"es":"Descartás a Ryko (u otro Lightsworn), robás 2 y mandás 2 más al Cementerio. Gasta mano pero aporta Lightsworn distintos para Judgment Dragon.","en":"Discard Ryko (or another Lightsworn), draw 2 and send 2 more to the Graveyard. Costs hand but adds distinct Lightsworn for Judgment Dragon."}},{"cards":["Lumina, Lightsworn Summoner"],"route":{"es":"Descartando 1 carta revive un Lightsworn de nivel 4 o menos, y manda 3 al Cementerio en cada End Phase: motor de recursos y de Cementerio a la vez.","en":"Discarding 1 card revives a Level 4 or lower Lightsworn, and it mills 3 each End Phase: resource and Graveyard engine at once."}}],"chokepoints":[{"card":"Royal Oppression","step":"summon","stepText":{"es":"En la invocación especial de Judgment Dragon, de Wulf o de un Lightsworn revivido por Lumina.","en":"On the Special Summon of Judgment Dragon, Wulf or a Lightsworn revived by Lumina."},"loss":{"es":"El rival paga 800 LP, anula la invocación y la destruye. Duele sobre todo contra Judgment Dragon. Guardá Twister o Lightning Vortex para sacarla antes.","en":"The opponent pays 800 LP, negates the Summon and destroys it. It hurts most against Judgment Dragon. Keep Twister or Lightning Vortex to remove it first."}},{"card":"Macro Cosmos","step":"resolution","stepText":{"es":"Al resolverse: todo lo que va al Cementerio se destierra.","en":"On resolution: everything that goes to the Graveyard is banished."},"loss":{"es":"El milling deja de llenar el Cementerio y Judgment Dragon nunca llega a los 4 Lightsworn. Honest también queda inútil. Hay que sacarla del campo.","en":"Milling no longer fills the Graveyard and Judgment Dragon never reaches 4 Lightsworn. Honest also becomes useless. It has to be removed from the field."}},{"card":"Vanity's Fiend","step":"main","stepText":{"es":"Durante la Main Phase, una vez que está en el campo.","en":"During the Main Phase, once it is on the field."},"loss":{"es":"Ninguno de los dos puede invocar de forma especial: Judgment, Wulf y Lumina quedan bloqueados. Destruilo (Ryko, Lyla) o ponelo boca abajo (Book of Moon).","en":"Neither player can Special Summon: Judgment, Wulf and Lumina are locked out. Destroy it (Ryko, Lyla) or flip it face-down (Book of Moon)."}},{"card":"Light-Imprisoning Mirror","step":"activation","stepText":{"es":"Cuando activás el efecto de un Lightsworn, que son monstruos LIGHT.","en":"When you activate a Lightsworn effect, since they are LIGHT monsters."},"loss":{"es":"Anula los efectos de monstruos LIGHT en el campo y en el Cementerio. Lyla, Ryko, Celestia, Lumina y el revive de Wulf quedan inertes. Sacala con Lightning Vortex o MST.","en":"Negates LIGHT monster effects on the field and in the Graveyard. Lyla, Ryko, Celestia, Lumina and Wulf's revival go dead. Remove it with Lightning Vortex or MST."}}],"side":{"first":{"in":[{"card":"My Body as a Shield","qty":1,"why":{"es":"Protege a Lyla o a un Lightsworn del Heavy Storm, de Torrential Tribute o de Smashing Ground. Cuesta 1500 LP.","en":"Protects Lyla or a Lightsworn from Heavy Storm, Torrential Tribute or Smashing Ground. Costs 1500 LP."}},{"card":"Book of Moon","qty":1,"why":{"es":"Da vuelta una amenaza grande sin gastar cartas propias.","en":"Flips a big threat without spending your own cards."}}],"out":[{"card":"Card Trooper","qty":1,"why":{"es":"Con 400 de ATK pierde contra los beatsticks Blackwing cuando vas primero.","en":"With 400 ATK it loses to Blackwing beatsticks when you go first."}},{"card":"Plaguespreader Zombie","qty":1,"why":{"es":"Mano floja en un duelo que depende de la presión.","en":"A weak draw in a duel that comes down to pressure."}}]},"second":{"in":[{"card":"My Body as a Shield","qty":1,"why":{"es":"Protege a tu cuerpo principal de las cartas que destruyen.","en":"Protects your main body from destruction effects."}}],"out":[{"card":"Plaguespreader Zombie","qty":1,"why":{"es":"Cuerpo flojo contra un tablero Blackwing.","en":"A weak body against a Blackwing board."}}]},"basis":"tournament"},"updated":"2026-10-26"},"edison/gladiator-beast":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gladiator Beast pelea y escapa: al final de la Battle Phase vuelven al Deck y traen a otro Gladiador, que dispara su efecto por entrar invocado por un efecto de Gladiator Beast.","en":"Gladiator Beasts fight and escape: at the end of the Battle Phase they shuffle back and bring in another Gladiator, which fires its effect for being Special Summoned by a Gladiator Beast effect."},{"es":"Gyzarus (2400) es la jugada fuerte: fusión de contacto con Bestiari + otro Gladiador, destruye hasta 2 cartas al entrar y al salir invoca 2 Gladiadores más.","en":"Gyzarus (2400) is the strong play: a contact fusion of Bestiari + another Gladiator, it destroys up to 2 cards on entry and on leaving Special Summons 2 more Gladiators."},{"es":"Gladiator Beast War Chariot, seteada, anula un efecto de monstruo mientras controles un Gladiador boca arriba. Con Heraklinos (3000, descarta 1 para anular una Magia/Trampa) el mazo juega de control.","en":"Gladiator Beast War Chariot, set, negates a monster effect while you control a face-up Gladiator. With Heraklinos (3000, discard 1 to negate a Spell/Trap) the deck plays as control."},{"es":"Con Prisma y Test Tiger la versión combo gana tempo y va más rápido; la versión base con Bestiari es más lenta y se apoya en las Trampas.","en":"With Prisma and Test Tiger the combo version gains tempo and goes faster; the base version with Bestiari is slower and leans on Traps."}]},"starters":[{"cards":["Gladiator Beast Bestiari","Test Tiger"],"route":{"es":"Bestiari por invocación normal habilita a Test Tiger desde la mano. Contacto de los dos y sale Gyzarus en la Main Phase 1: destruye 2 cartas y, tras pelear, trae 2 Gladiadores más.","en":"Bestiari Normal Summoned enables Test Tiger from the hand. Contact fuse both and Gyzarus comes out in Main Phase 1: destroys 2 cards and after battle brings in 2 more Gladiators."}},{"cards":["Elemental HERO Prisma","Test Tiger"],"route":{"es":"Prisma muestra a Gyzarus y manda a Bestiari del Deck al Cementerio, tomando su nombre hasta el End Phase. Con Test Tiger ya hay fusión de contacto sin tener un Bestiari real.","en":"Prisma reveals Gyzarus and sends Bestiari from the Deck to the Graveyard, taking its name until the End Phase. With Test Tiger there is a contact fusion without holding a real Bestiari."}},{"cards":["Test Tiger"],"route":{"es":"Con un Gladiador boca arriba, Test Tiger sale de la mano. Tributarlo cambia ese Gladiador por otro del Deck (por ejemplo Murmillo, que destruye un monstruo) como si entrara por efecto.","en":"With a face-up Gladiator, Test Tiger comes out of the hand. Tributing it swaps that Gladiator for another from the Deck (for example Murmillo, which destroys a monster) as if effect-summoned."}}],"chokepoints":[{"card":"Royal Oppression","step":"summon","stepText":{"es":"En la invocación especial de Gyzarus, de Heraklinos o de cualquier Gladiador que entra por tag out.","en":"On the Special Summon of Gyzarus, Heraklinos or any Gladiator coming in through a tag out."},"loss":{"es":"El rival paga 800 LP, anula la invocación y la destruye. Los materiales de la fusión ya volvieron al Deck, así que perdés dos cartas por una. Hacé primero la invocación que menos importa.","en":"The opponent pays 800 LP, negates the Summon and destroys it. The fusion materials already returned to the Deck, so you lose two cards for one. Make the least important Summon first."}},{"card":"Fossil Dyna Pachycephalo","step":"resolution","stepText":{"es":"Al resolverse su efecto de Flip.","en":"On resolution of its Flip effect."},"loss":{"es":"Destruye todos los monstruos invocados especialmente y nadie puede invocar de forma especial. Como el tag out es una invocación especial, el mazo no puede reemplazar nada. Respondé con Book of Moon antes del Flip.","en":"Destroys all Special Summoned monsters and nobody can Special Summon. Since the tag out is a Special Summon, the deck cannot replace anything. Answer with Book of Moon before the Flip."}},{"card":"Vanity's Fiend","step":"main","stepText":{"es":"Mientras esté en el campo, durante tu Main Phase.","en":"While it is on the field, during your Main Phase."},"loss":{"es":"Bloquea toda invocación especial: sin tag out ni fusión de contacto el mazo queda con cuerpos de ATK bajo. Sacalo con Smashing Ground o Compulsory Evacuation Device.","en":"Blocks every Special Summon: with no tag out and no contact fusion the deck is left with low ATK bodies. Remove it with Smashing Ground or Compulsory Evacuation Device."}},{"card":"Solemn Judgment","step":"summon","stepText":{"es":"En la invocación de la fusión de contacto o al activar tu Trampa seteada.","en":"On the contact fusion Summon or when you activate your set Trap."},"loss":{"es":"Anula y destruye la invocación pagando la mitad de los LP. Una Gyzarus anulada son dos Gladiadores perdidos. Tené a mano Heraklinos o una Trampa de respaldo para forzar la anulación primero.","en":"Negates and destroys the Summon for half the LP. A negated Gyzarus costs two Gladiators. Keep Heraklinos or a backup Trap to bait it first."}}],"side":{"first":{"in":[{"card":"Starlight Road","qty":1,"why":{"es":"Anula Heavy Storm y Torrential Tribute y trae a un Stardust Dragon. Protege el campo de las limpiezas.","en":"Negates Heavy Storm and Torrential Tribute and brings out a Stardust Dragon. Protects the field from sweeps."}}],"out":[{"card":"Rescue Cat","qty":1,"why":{"es":"Más lenta que el arranque propio del mazo cuando vas primero.","en":"Slower than the deck's own opening when going first."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":1,"why":{"es":"Saca la Trampa que frena tu avance (Royal Decree, Solemn Judgment) cuando tenés que forzar el ritmo.","en":"Removes the Trap that stalls your advance (Royal Decree, Solemn Judgment) when you must force the pace."}}],"out":[{"card":"Cold Wave","qty":1,"why":{"es":"Cuando vas segundo necesitás tus propias Magias y Trampas activas.","en":"When going second you need your own Spells and Traps active."}}]},"basis":"editorial"},"updated":"2026-10-26"},"edison/frog-monarch":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Juego lento y consistente: Substitoad trae Frogs que no se destruyen en batalla, y Treeborn Frog vuelve del Cementerio cada Standby Phase si no controlás Magias ni Trampas.","en":"Slow, consistent play: Substitoad brings Frogs that cannot be destroyed by battle, and Treeborn Frog returns from the Graveyard each Standby Phase if you control no Spells or Traps."},{"es":"Los Frogs son el sacrificio: dos cuerpos baratos pagan el Tribute de Caius (destierra y pega 1000 si es DARK) y de Raiza (devuelve una carta a la cima del Deck).","en":"The Frogs are the sacrifice: two cheap bodies pay the Tribute for Caius (banish and 1000 damage if DARK) and Raiza (places a card on top of the Deck)."},{"es":"Dupe Frog repone la mano: al irse al Cementerio trae otro Frog, y Pot of Avarice y Salvage reciclan Frogs para seguir.","en":"Dupe Frog refills the hand: when it goes to the Graveyard it adds another Frog, and Pot of Avarice and Salvage recycle Frogs to keep going."}]},"starters":[{"cards":["Substitoad","Treeborn Frog"],"route":{"es":"Tributás a Treeborn con Substitoad para traer a Swap Frog del Deck. Treeborn vuelve en tu Standby Phase si no controlás Magias ni Trampas.","en":"Tribute Treeborn with Substitoad to bring Swap Frog from the Deck. Treeborn comes back on your Standby Phase if you control no Spells or Traps."}},{"cards":["Substitoad","Dupe Frog"],"route":{"es":"Tributás a Dupe Frog: Substitoad invoca otro Frog y Dupe, al ir al Cementerio, trae un Frog más a la mano.","en":"Tribute Dupe Frog: Substitoad Special Summons another Frog and Dupe, going to the Graveyard, adds one more Frog to hand."}},{"cards":["Substitoad","Caius the Shadow Monarch"],"route":{"es":"Substitoad arma dos cuerpos Frog para el doble Tribute de Caius, que destierra una carta rival y pega 1000 si es DARK.","en":"Substitoad makes two Frog bodies for Caius's double Tribute, which banishes an opposing card and deals 1000 if it is DARK."}}],"chokepoints":[{"card":"Fossil Dyna Pachycephalo","step":"resolution","stepText":{"es":"Al resolverse su Flip.","en":"On resolution of its Flip."},"loss":{"es":"Destruye los monstruos invocados especialmente y evita nuevas invocaciones: frena a Substitoad, Treeborn y Swap Frog. La remoción de Magias/Trampas no sirve: usá Book of Moon o Raiza antes del Flip.","en":"Destroys Special Summoned monsters and prevents new Summons: it stops Substitoad, Treeborn and Swap Frog. Spell/Trap removal does not help: use Book of Moon or Raiza before the Flip."}},{"card":"Vanity's Fiend","step":"main","stepText":{"es":"Mientras esté en el campo, durante tu Main Phase.","en":"While it is on the field, during your Main Phase."},"loss":{"es":"Nadie puede invocar de forma especial: Substitoad no trae nada y Treeborn no vuelve. Respondé con Raiza o Caius tributando un Frog normal, o con Soul Exchange.","en":"Nobody can Special Summon: Substitoad brings nothing and Treeborn does not return. Answer with Raiza or Caius Tributing a normal Frog, or with Soul Exchange."}},{"card":"Dimensional Fissure","step":"activation","stepText":{"es":"Cuando tributás con Substitoad: el Frog tributado se destierra.","en":"When you Tribute with Substitoad: the Tributed Frog is banished."},"loss":{"es":"Treeborn y Dupe Frog no llegan al Cementerio, así que no vuelven ni traen otro Frog. Pot of Avarice y Salvage quedan sin objetivo. Sacala con MST.","en":"Treeborn and Dupe Frog do not reach the Graveyard, so they neither return nor fetch another Frog. Pot of Avarice and Salvage have no targets. Remove it with MST."}},{"card":"Mask of Restrict","step":"activation","stepText":{"es":"Cuando querés tributar con Substitoad o para un Monarca.","en":"When you want to Tribute with Substitoad or for a Monarch."},"loss":{"es":"Nadie puede tributar: Substitoad, Caius y Raiza quedan apagados. Destruila con Heavy Storm o MST.","en":"Nobody can Tribute: Substitoad, Caius and Raiza are shut off. Destroy it with Heavy Storm or MST."}}],"side":{"first":{"in":[{"card":"D.D. Crow","qty":2,"why":{"es":"Quick Effect que desterra una carta del Cementerio rival (Vayu, Lightsworn) sin pagar con tu mano fuerte.","en":"A Quick Effect that banishes a card from the opposing Graveyard (Vayu, Lightsworn) without spending a key card."}}],"out":[{"card":"Phoenix Wing Wind Blast","qty":2,"why":{"es":"Setear Trampas rompe a Treeborn, que pide no controlar Magias ni Trampas.","en":"Setting Traps breaks Treeborn, which needs you to control no Spells or Traps."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":1,"why":{"es":"Saca la Trampa o el Fissure que apaga tu ciclo de Frogs.","en":"Removes the Trap or Fissure that shuts off your Frog loop."}},{"card":"Lightning Vortex","qty":1,"why":{"es":"Descartás 1 carta y destruís todos los monstruos rivales. Los Frogs resisten batalla, no efectos, así que barrés un tablero más rápido que el tuyo.","en":"Discard 1 card to destroy all opposing monsters. Frogs resist battle, not effects, so you sweep a board faster than yours."}}],"out":[{"card":"Phoenix Wing Wind Blast","qty":1,"why":{"es":"Lenta y con costo de mano cuando el rival ya te lleva ventaja.","en":"Slow and card-costly when the opponent is already ahead."}},{"card":"Spiritual Water Art - Aoi","qty":1,"why":{"es":"Pide tributar un WATER y, seteada, rompe a Treeborn.","en":"Needs a WATER Tribute and, set, breaks Treeborn."}}]},"basis":"editorial"},"updated":"2026-10-26"},"gen/blitzclique":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Juega desde la mano: Surge, Grain y Crackle se revelan para destruir una carta e invocar de Especial un Trueno de la mano, y Emi lo hace al ser agregado a la mano sin robarlo. No gasta la Invocación Normal.","en":"Plays from hand: Surge, Grain and Crackle are revealed to destroy a card and Special Summon a Thunder from hand, and Emi does the same when added to hand by a non-draw effect. It does not use the Normal Summon."},{"es":"Cada destrucción por efecto dispara a los monstruos que ya están en el campo: Surge busca otro Blitzclique, Grain una Magia o Hideout, Emi una Trampa. Steppleader, Breakaway, Overvolt y Hideout vuelven a la mano desde el Cementerio si un efecto Blitzclique destruyó algo.","en":"Every effect destruction triggers monsters already on the field: Surge searches another Blitzclique, Grain a Spell or Hideout, Emi a Trap. Steppleader, Breakaway, Overvolt and Hideout return to hand from the GY if a Blitzclique effect destroyed something."},{"es":"Cierra con Whisker Blitzclique (hasta 3 Truenos de la mano y destruye hasta 3 cartas) y se protege con Return Stroke y Alternator. Después de cada efecto solo se invoca de Especial desde la mano, así que el Extra Deck casi no se usa.","en":"It finishes with Whisker Blitzclique (up to 3 Thunders from hand, destroys up to 3 cards) and protects itself with Return Stroke and Alternator. After each effect you can only Special Summon from the hand, so the Extra Deck barely matters."},{"es":"Sin monstruos Link en Genesys, Link Apple revela, banea al azar una carta boca abajo del Extra, no encuentra un Link y se descarta para robar 1. Si banea un Toxic Boxfish, el Boxfish niega una carta rival boca arriba.","en":"With no Link monsters in Genesys, Link Apple reveals, banishes a random face-down Extra Deck card, finds no Link, and discards itself to draw 1. If it banishes a Toxic Boxfish, the Boxfish negates a face-up opposing card."}]},"starters":[{"cards":["Hideout in the Sky, Coulomb","Surge Blitzclique"],"route":{"es":"Coulomb pone un Mech Beast Token en el campo rival y busca un Blitzclique. Surge se revela, destruye ese Token, invoca un Trueno de la mano y busca otro Blitzclique.","en":"Coulomb puts a Mech Beast Token on the opponent's field and searches a Blitzclique. Surge is revealed, destroys that Token, Special Summons a Thunder from hand and searches another Blitzclique."}},{"cards":["Blitzclique - Steppleader","Surge Blitzclique"],"route":{"es":"Steppleader invoca de Especial a Surge desde la mano y se destruye: esa destrucción dispara a Surge, que busca un monstruo Blitzclique.","en":"Steppleader Special Summons Surge from hand and destroys itself: that destruction triggers Surge, which searches a Blitzclique monster."}},{"cards":["Crackle Blitzclique"],"route":{"es":"En el turno rival, cuando activan un efecto de monstruo en el campo, Crackle se revela, destruye ese monstruo e invoca un Trueno de la mano: la cadena arranca en su turno.","en":"On the opponent's turn, when they activate a monster effect on the field, Crackle is revealed, destroys that monster and Special Summons a Thunder from hand: the chain starts on their turn."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa la búsqueda de Surge, Grain o Emi, o el Token de Hideout que busca un Blitzclique.","en":"When a Surge, Grain or Emi search, or Hideout's Token plus search, is activated."},"loss":{"es":"Niega ese efecto entero: sin búsqueda ni Token no hay siguiente eslabón. Abrí con Steppleader u Overvolt, que no buscan del Deck, para que Ash caiga en una jugada menor.","en":"It negates that whole effect: no search or Token means no next link. Open with Steppleader or Overvolt, which do not search the Deck, so Ash lands on a minor play."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación del turno, por ejemplo cuando Whisker pone 3 Truenos de la mano.","en":"On the fifth summon of the turn, for example when Whisker puts out 3 Thunders from hand."},"loss":{"es":"Tributa todos tus monstruos y deja un Token enorme en tu lado. Contá las invocaciones y frená antes de la quinta si te quedan recursos para el turno siguiente.","en":"It Tributes all your monsters and leaves a huge Token on your side. Count your summons and stop before the fifth if you still have resources for next turn."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno, cuando se agrega una carta a tu mano desde el Deck.","en":"After the first search of the turn, when a card is added to your hand from the Deck."},"loss":{"es":"Ninguna otra búsqueda ese turno, y buena parte de la cadena depende de búsquedas. Hacé primero la destrucción que no busca y guardá la búsqueda importante para después.","en":"No other search that turn, and a good part of the chain depends on searches. Make the destruction that does not search first and save the important search for later."}},{"card":"Runick Slumber","step":"resolution","stepText":{"es":"En cadena sobre el monstruo que vas a destruir con Surge o Breakaway.","en":"In chain on the monster you are about to destroy with Surge or Breakaway."},"loss":{"es":"Esa vez no se destruye, falla el 'si lo hacés' y no hay Trueno ni disparos. Flipside Gaming lo marca como muy dañino para el mazo. Apuntá a una Magia o Trampa con Grain u Overvolt.","en":"That time it is not destroyed, the 'if you do' fails and there is no Thunder or trigger. Flipside Gaming calls it very damaging to the deck. Aim at a Spell or Trap with Grain or Overvolt."}},{"card":"The Eye of Truth","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase 1, con tu mano revelada.","en":"Face-up before your Main Phase 1, with your hand revealed."},"loss":{"es":"Flipside Gaming lo cita como el golpe a los mazos que necesitan revelar cartas, y Blitzclique es el caso principal. Sacala con Typhoon, MST o Double Cyclone.","en":"Flipside Gaming cites it as the hit to decks that need to reveal cards, and Blitzclique is the main case. Remove it with Typhoon, MST or Double Cyclone."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Debunk","qty":2,"why":{"es":"Frena un efecto de monstruo en la mano o el Cementerio (Ash, Nibiru, Shifter) y lo banea, justo lo que te interrumpe yendo primero.","en":"Stops a monster effect in the hand or GY (Ash, Nibiru, Shifter) and banishes it, exactly what interrupts you going first."}}],"out":[{"card":"D.D. Crow","qty":2,"why":{"es":"Yendo primero el Cementerio rival está vacío y Crow no tiene objetivo.","en":"Going first the opponent's GY is empty and Crow has no target."}}]},"second":{"in":[{"card":"Veidos the Eruption Dragon of Extinction","qty":2,"why":{"es":"Yendo segundo se juega al campo rival desde la mano sobre una Zona de Campo, la destruye y, si un efecto Blitzclique lo destruye ahí, barre todos los monstruos.","en":"Going second it goes to their field from hand against a Field Zone card, destroys it and, if a Blitzclique effect destroys it there, wipes every monster."}}],"out":[{"card":"Skull Meister","qty":2,"why":{"es":"Solo responde a efectos en el Cementerio; yendo segundo el problema es el tablero rival, no su Cementerio.","en":"It only answers GY effects; going second the problem is their board, not their GY."}}]}},"updated":"2026-10-26"},"gen/sacred-beast":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Arma los tres Sacred Beast de nivel 10 (Raviel, Hamon, Uria) con efectos de cartas Sacred Beast y sus monstruos y Magias de apoyo, sin pasar por la Invocación Normal.","en":"Builds the three Level 10 Sacred Beasts (Raviel, Hamon, Uria) through Sacred Beast card effects and their support monsters and Spells, without the Normal Summon."},{"es":"Raviel tributa 2 Sacred Beast para destruir todos los monstruos rivales que pueda y gana 1000 de ATK por carta destruida. Hamon inflige 1000 por cada monstruo que va al Cementerio rival.","en":"Raviel Tributes 2 Sacred Beasts to destroy as many opposing monsters as possible and gains 1000 ATK per card destroyed. Hamon deals 1000 for each monster sent to the opponent's GY."},{"es":"Fallen Paradise manda 3 cartas del mismo tipo al Cementerio (hasta tres veces por turno) para invocar un Sacred Beast; Thunderclap y Martyr dan ese combustible. The Chaotic Phantasmal Sacred Beasts (3 monstruos nivel 10) niega monstruos rivales.","en":"Fallen Paradise sends 3 cards of the same type to the GY (up to three times per turn) to Special Summon a Sacred Beast; Thunderclap and Martyr provide the fuel. The Chaotic Phantasmal Sacred Beasts (3 Level 10 monsters) negates opposing monsters."}]},"starters":[{"cards":["Sacred Beasts Released","Sacred Beasts Thunderclap"],"route":{"es":"Released agrega 3 Sacred Beast distintos y descarta 2; Thunderclap se pone 2 veces más y trae Fallen Paradise a la Zona de Campo, y esas 3 Magias son la ofrenda que invoca al Beast.","en":"Released adds 3 different Sacred Beasts and discards 2; Thunderclap places 2 more copies and brings Fallen Paradise to the Field Zone, and those 3 Spells are the cost that summons the Beast."}},{"cards":["Martyr of the Sacred Beasts"],"route":{"es":"Martyr pone un Campo o Continua Sacred Beast del Deck (Fallen Paradise) y, si controlás otro Sacred Beast, invoca 2 Martyr más: 3 monstruos como ofrenda de Fallen Paradise.","en":"Martyr places a Sacred Beast Field or Continuous card from the Deck (Fallen Paradise) and, if you control another Sacred Beast, summons 2 more Martyrs: 3 monsters as Fallen Paradise's offering."}},{"cards":["Summoner of the Sacred Beasts"],"route":{"es":"Summoner se revela, descarta 1 carta e invoca en Defensa un Sacred Beast que no sea de nivel 8 desde la mano, lo que cubre a Raviel, Hamon o Uria.","en":"Summoner is revealed, discards 1 card and Special Summons a non-Level 8 Sacred Beast from hand in Defense Position, which covers Raviel, Hamon or Uria."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Released o el efecto de revelar de Raviel, Hamon o Uria que agrega una carta del Deck.","en":"When Released or the reveal effect of Raviel, Hamon or Uria that adds a card from the Deck is activated."},"loss":{"es":"Niega esa búsqueda (y con Released, también el descarte). Tené otra ruta, por ejemplo Martyr o Summoner, para la segunda jugada.","en":"It negates that search (and with Released, the discard too). Keep another route, such as Martyr or Summoner, for the second play."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"En el efecto rápido de Raviel, después de pagar los dos Tributos.","en":"On Raviel's Quick Effect, after the two Tributes are paid."},"loss":{"es":"Niega a Raviel y perdés los dos Sacred Beast del costo sin destruir nada. Esperá a que la use antes de comprometer a Raviel, o tené Skyfall en la mano para negar la respuesta.","en":"It negates Raviel and you lose the two Sacred Beasts paid as cost without destroying anything. Wait for them to use it before committing Raviel, or hold Skyfall to negate the response."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de una búsqueda, cuando una carta se agrega a tu mano desde el Deck.","en":"After a search, when a card is added to your hand from the Deck."},"loss":{"es":"Corta las demás búsquedas del turno y el mazo depende de varias: Released, las revelaciones de los nivel 10. Hacé primero la búsqueda de menos valor.","en":"It cuts other searches that turn and the deck relies on several: Released, the Level 10 reveals. Make the lowest value search first."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"En la quinta invocación del turno; Martyr invoca 2 más y Fallen Paradise otra.","en":"On the fifth summon of the turn; Martyr summons 2 more and Fallen Paradise another."},"loss":{"es":"Tributa todo tu campo y deja un Token con el ATK sumado. Con Martyrs y Fallen Paradise llegás rápido al quinto monstruo: contá antes de invocar el último.","en":"It Tributes your whole field and leaves a Token with the combined ATK. With Martyrs and Fallen Paradise you reach the fifth monster fast: count before summoning the last."}},{"card":"Dimension Shifter","step":"activation","stepText":{"es":"En tu turno, con el Cementerio rival vacío: lo que va al Cementerio se banea.","en":"On your turn, with their GY empty: anything sent to the GY is banished."},"loss":{"es":"Thunderclap vuelve a la mano desde el Cementerio, y Martyr y Summoner actúan desde allí; con el Shifter eso no pasa. Planificá la jugada sin contar con lo que va al Cementerio.","en":"Thunderclap returns to hand from the GY, and Martyr and Summoner act from there; with Shifter that does not happen. Plan the turn without counting on what goes to the GY."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Cosmic Cyclone","qty":2,"why":{"es":"Banea una carta rival que frena el plan (Macro Cosmos, Eye of Truth) por 1000 LP.","en":"Banishes an opposing card that stops the plan (Macro Cosmos, Eye of Truth) for 1000 LP."}}],"out":[{"card":"Pot of Sloth","qty":2,"why":{"es":"Roba según las cartas del rival: en el primer turno no controla ninguna.","en":"It draws based on the opponent's cards: on turn one they control none."}}]},"second":{"in":[{"card":"Lava Golem","qty":2,"why":{"es":"Yendo segundo se juega al campo rival tributando 2 monstruos suyos y abre camino para Hamon y Raviel.","en":"Going second it goes to their field Tributing 2 of their monsters and opens the way for Hamon and Raviel."}}],"out":[{"card":"Light and Darkness Ritual","qty":1,"why":{"es":"Paquete lento de Ritual que no aporta cuando hay que romper tablero.","en":"A slow Ritual package that adds nothing when you need to break a board."}},{"card":"Nightmare Hands","qty":1,"why":{"es":"Paquete de Illusion fuera del plan principal.","en":"An Illusion package outside the main plan."}}]}},"updated":"2026-10-26"},"gen/chimera":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gana con ventaja de cartas: Fusiona Chimera the King of Phantom Beasts y Berfomet the Mythical King con Chimera Fusion, y los jefes se recuperan y se reemplazan solos.","en":"Wins on card advantage: Fusion Summons Chimera the King of Phantom Beasts and Berfomet the Mythical King with Chimera Fusion, and the bosses recover and replace themselves."},{"es":"Gazelle y Big-Winged Berfomet se buscan entre sí y a Chimera Fusion al invocarse; al ir al Cementerio como material, Gazelle trae un Illusion y Berfomet revive uno.","en":"Gazelle and Big-Winged Berfomet search each other and Chimera Fusion when summoned; sent to the GY as material, Gazelle adds an Illusion and Berfomet revives one."},{"es":"Chimera, al invocarse por Fusión, manda una carta al azar de la mano rival al Cementerio en la End Phase. Darkuriboh protege a los monstruos Fiend o de Fusión de blancos, destrucción y ataques, y evita que se les nieguen los efectos.","en":"Chimera, when Fusion Summoned, sends a random card from the opponent's hand to the GY in the End Phase. Darkuriboh protects Fiend or Fusion monsters from targeting, destruction and attacks, and stops their effects from being negated."}]},"starters":[{"cards":["Mirror Swordknight"],"route":{"es":"Swordknight, de Invocación Normal, se tributa (efecto rápido) para invocar a Big-Winged Berfomet del Deck, que agrega a Gazelle y a Chimera Fusion.","en":"Swordknight, Normal Summoned, is Tributed (Quick Effect) to Special Summon Big-Winged Berfomet from the Deck, which adds Gazelle and Chimera Fusion."}},{"cards":["Gazelle the King of Mythical Claws","Chimera Fusion"],"route":{"es":"Gazelle agrega un Fiend de nivel 5 o Chimera Fusion; con Fusion en mano se Fusiona usando un Beast o Fiend de la mano o el campo.","en":"Gazelle adds a Level 5 Fiend or Chimera Fusion; with Fusion in hand you Fusion Summon using a Beast or Fiend from hand or field."}},{"cards":["Nightmare Apprentice"],"route":{"es":"Apprentice se invoca de la mano descartando 1 carta y agrega un Illusion del Deck, por ejemplo Mirror Swordknight, para arrancar la ruta.","en":"Apprentice Special Summons itself from hand by discarding 1 card and adds an Illusion from the Deck, for example Mirror Swordknight, to start the route."}}],"chokepoints":[{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno, normalmente la de Swordknight, Berfomet o Gazelle.","en":"After the first search of the turn, normally Swordknight, Berfomet or Gazelle."},"loss":{"es":"El mazo necesita varias búsquedas en el mismo turno, y una guía de Branded Chimera lo marca como un freno principal. Abrí con lo que ya trae Fusion para no depender de la segunda búsqueda.","en":"The deck needs several searches in one turn, and a Branded Chimera guide flags it as a main brake. Open with what already brings Fusion so you do not depend on the second search."}},{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa la búsqueda de Berfomet, de Gazelle o de Small World.","en":"When a Berfomet, Gazelle or Small World search is activated."},"loss":{"es":"Corta esa búsqueda. Small World o Polymerization son buen señuelo, porque la ventaja real está en Chimera y Berfomet.","en":"It stops that search. Small World or Polymerization make a good bait, since the real advantage lies in Chimera and Berfomet."}},{"card":"Dimensional Barrier","step":"activation","stepText":{"es":"Declarando Fusion en tu Main Phase, antes de resolver Chimera Fusion.","en":"Declaring Fusion in your Main Phase, before Chimera Fusion resolves."},"loss":{"es":"No podés invocar Fusiones ese turno y las que están en el campo se niegan; la guía de Branded Chimera lo llama un desastre. Aguantá la Fusión y jugá monstruos del Deck principal.","en":"You cannot Special Summon Fusions that turn and those on the field are negated; the Branded Chimera guide calls it a blowout. Hold the Fusion and play Main Deck monsters."}},{"card":"Dimension Shifter","step":"activation","stepText":{"es":"En tu turno, antes de usar los materiales: todo lo que va al Cementerio se banea.","en":"On your turn, before you use materials: anything sent to the GY is banished."},"loss":{"es":"Los materiales se banean en lugar de ir al Cementerio, y los efectos 'al ir al Cementerio como material' de Gazelle y Berfomet no se activan. Fusioná igual, pero sin contar con ese valor.","en":"Materials are banished instead of going to the GY, so Gazelle's and Berfomet's 'sent to the GY as material' effects do not trigger. Fusion Summon anyway but do not count on that value."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, sobre Berfomet, Gazelle o el Chimera ya invocado.","en":"In your Main Phase, on Berfomet, Gazelle or an already summoned Chimera."},"loss":{"es":"Niega el efecto del monstruo elegido hasta el fin del turno. Dark Fusion deja a la Fusión sin blancos de efectos ese turno y Darkuriboh la cubre de negaciones.","en":"It negates the chosen monster's effect until end of turn. Dark Fusion makes the Fusion untargetable by effects that turn and Darkuriboh covers it from negation."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Chaos Hunter","qty":2,"why":{"es":"Se invoca de la mano cuando el rival invoca de Especial y evita que baneen cartas, útil contra Shifter y efectos de banish.","en":"It Special Summons from hand when the opponent Special Summons and stops banishing, useful against Shifter and banish effects."}}],"out":[{"card":"Kuriboh - Multiply!","qty":1,"why":{"es":"Pensado para reaccionar a ataques; yendo primero el rival aún no tiene tablero.","en":"Built to react to attacks; going first the opponent has no board yet."}},{"card":"Detonating Kuriboh","qty":1,"why":{"es":"Misma razón: depende de un monstruo rival atacando.","en":"Same reason: it depends on an opposing monster attacking."}}]},"second":{"in":[{"card":"Lightning Vortex","qty":2,"why":{"es":"Yendo segundo el tablero rival está armado y Vortex destruye todos sus monstruos boca arriba descartando 1.","en":"Going second their board is built and Vortex destroys all their face-up monsters for 1 discard."}}],"out":[{"card":"Small World","qty":2,"why":{"es":"Es una carta lenta; con el tablero rival hecho no te da ventaja.","en":"A slow card; against an established board it does not give you an edge."}}]}},"updated":"2026-10-26"},"gen/exosister":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Cada monstruo de nivel 4 del mazo puede ser el único material de un Xyz Exosister (se trata como Invocación Xyz) cuando una carta sale de cualquier Cementerio. Al rival le cuesta usar su Cementerio.","en":"Every Level 4 monster in the deck can be the sole material for an Exosister Xyz (treated as an Xyz Summon) whenever a card moves out of any Graveyard. The opponent has a hard time using their Graveyard."},{"es":"Martha entra de la mano y trae a Elis; Aratama busca a Sakitama o Ichiki, y Ichiki trae un LIGHT o DARK de nivel 4 con 800 de ATK o DEF. Eso asegura los cuerpos para dos Xyz.","en":"Martha enters from hand and brings Elis; Aratama searches Sakitama or Ichiki, and Ichiki brings a Level 4 LIGHT or DARK with 800 ATK or DEF. That secures the bodies for two Xyz."},{"es":"Exosisters Magnifica quita una carta rival por turno y puede cambiarse por otro Xyz en el turno rival; Mikailis y Gibrine disrumpen la jugada. Los costos de 800 LP de Pax, Vadis y Returnia limitan cuánto se puede apurar.","en":"Exosisters Magnifica banishes one opposing card per turn and can swap into another Xyz on the opponent's turn; Mikailis and Gibrine disrupt the play. The 800 LP costs of Pax, Vadis and Returnia cap how much you can rush."}]},"starters":[{"cards":["Exosister Martha"],"route":{"es":"Martha se invoca de la mano si no controlás monstruos o solo Xyz, y trae a Elis del Deck. Después usan 'cuando una carta sale del Cementerio' y suben a Rank 4.","en":"Martha Special Summons from hand if you control no monsters or only Xyz, and brings Elis from the Deck. They then use 'when a card moves out of a GY' and rank up."}},{"cards":["Aratama","Ichiki Sayori-Hime"],"route":{"es":"Aratama (Invocación Normal) busca otro Spirit; Ichiki se invoca de la mano si controlás un monstruo de 800 ATK o DEF, y trae a un nivel 4 LIGHT o DARK de 800 ATK o DEF.","en":"Aratama (Normal Summon) searches another Spirit; Ichiki is Normal Summoned from hand if you control an 800 ATK or DEF monster, and brings a Level 4 LIGHT or DARK with 800 ATK or DEF."}},{"cards":["Exosister Betrayal"],"route":{"es":"Betrayal agrega 2 Exosister y descarta 1, permite una Invocación Normal extra de un Exosister mencionado y banea un monstruo que vaya al Cementerio rival.","en":"Betrayal adds 2 Exosisters and discards 1, allows an extra Normal Summon of a mentioned Exosister and banishes a monster sent to the opponent's GY."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa la búsqueda de Aratama, Ichiki, Pax o Betrayal.","en":"When an Aratama, Ichiki, Pax or Betrayal search is activated."},"loss":{"es":"Niega esa búsqueda. Martha no busca sino que invoca a Elis del Deck, y eso Ash también lo frena: jugá primero la ruta de Martha y después las búsquedas.","en":"It negates that search. Martha does not search; she Special Summons Elis from the Deck, which Ash also stops. Play the Martha route first and the searches after."}},{"card":"Macro Cosmos","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase: ninguna carta va al Cementerio.","en":"Face-up before your Main Phase: no card goes to the GY."},"loss":{"es":"Si no hay cartas en el Cementerio, nada sale de él y los efectos de Exosister no se activan. Typhoon, MST o Cosmic Cyclone la sacan, y Unending Nightmare de tu Side también.","en":"If there are no cards in the GY, nothing leaves it and Exosister effects do not trigger. Typhoon, MST or Cosmic Cyclone remove it, and so does Unending Nightmare from your Side."}},{"card":"Dimension Shifter","step":"activation","stepText":{"es":"En tu turno, con el Cementerio rival vacío, antes de que algo se mueva de allí.","en":"On your turn, with their GY empty, before anything moves from there."},"loss":{"es":"Banea todo lo que va al Cementerio hasta el fin del próximo turno, y sin cartas en el Cementerio no hay disparos. Martha y Elis se invocan igual, pero armá los Xyz con material normal.","en":"It banishes anything sent to the GY through the end of the next turn, and without cards in the GY there are no triggers. Martha and Elis still summon, but build the Xyz with normal material."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Sobre Magnifica, Karmael o Mikailis, justo antes de usar su efecto.","en":"On Magnifica, Karmael or Mikailis, right before using its effect."},"loss":{"es":"Niega el efecto del Xyz ese turno. Si tenés otro Exosister podés cambiar a Magnifica por otro Xyz en respuesta, y Karmael protege la cadena.","en":"It negates the Xyz's effect that turn. If you have another Exosister you can swap Magnifica into another Xyz in response, and Karmael protects the chain."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Typhoon","qty":2,"why":{"es":"Yendo primero responde a una Magia o Trampa de campo rival (Macro Cosmos, floodgates) que frene el plan.","en":"Going first it answers an opposing field Spell or Trap (Macro Cosmos, floodgates) that stops the plan."}}],"out":[{"card":"Gordian Slicer","qty":2,"why":{"es":"Rebota cartas rivales baneando de la mano; yendo primero el rival no tiene nada que rebotar.","en":"It bounces opposing cards by banishing from hand; going first the opponent has nothing to bounce."}}]},"second":{"in":[{"card":"Typhoon","qty":1,"why":{"es":"Responde a una Magia o Trampa rival ya puesta.","en":"Answers an opposing Spell or Trap already set."}},{"card":"Blizzard","qty":1,"why":{"es":"Niega una Magia rival boca arriba, útil contra un campo que dependa de Magias.","en":"Negates a face-up opposing Spell, useful against a field built on Spells."}}],"out":[{"card":"Forbidden Chalice","qty":2,"why":{"es":"Pierde valor contra un tablero armado; es mejor ahorrar el espacio para responder.","en":"Loses value against an established board; better to save the slots to respond."}}]}},"updated":"2026-10-26"},"gen/invoked":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Fusiona Invoked usando monstruos propios, del Cementerio y baneados con Invocation, Sword y Grail. Magical Meltdown hace que esas Fusiones no se puedan negar y que el rival no pueda activar nada en respuesta.","en":"Fusion Summons Invoked monsters using its own monsters, the GY and banished cards via Invocation, Sword and Grail. Magical Meltdown makes those Fusions un-negatable and stops the opponent from activating anything in response."},{"es":"Aleister the Invoker agrega Invocation; Reminiscent se invoca de la mano y banea un Invoked del Extra para agregar Invocation. Aiwass se banea para traer un Aleister y vuelve del Cementerio cuando una de tus Fusiones se manda al Cementerio.","en":"Aleister the Invoker adds Invocation; Reminiscent Special Summons from hand and banishes an Invoked from the Extra Deck to add Invocation. Aiwass banishes itself to bring an Aleister and returns from the GY when one of your Fusions is sent to the GY."},{"es":"Los jefes son Invoked De Anima (destruye monstruos del Extra o Magias y Trampas), Mechaba (niega descartando una carta del mismo tipo) y Hyperinvoked Aeon, que banea cartas del campo y de los Cementerios.","en":"The bosses are Invoked De Anima (destroys Extra Deck monsters or Spells and Traps), Mechaba (negates by discarding a card of the same type) and Hyperinvoked Aeon, which banishes cards from the field and Graveyards."}]},"starters":[{"cards":["Magical Meltdown"],"route":{"es":"Meltdown agrega a Aleister the Invoker al activarse; con él, Invocation y Aleister hacen una Fusión a la que el rival no puede responder.","en":"Meltdown adds Aleister the Invoker when activated; with it, Invocation and Aleister make a Fusion the opponent cannot respond to."}},{"cards":["Aleister the Reminiscent"],"route":{"es":"Reminiscent se invoca de la mano apuntando a un Spellcaster o Fusión (que gana 1000 ATK) y, al invocarse, agrega Invocation baneando un Invoked del Extra.","en":"Reminiscent Special Summons itself from hand targeting a Spellcaster or Fusion (which gains 1000 ATK) and, when summoned, adds Invocation by banishing an Invoked from the Extra Deck."}},{"cards":["Aiwass, Divine Spirit of the Law","Sacred Spirit Sword Aiwass"],"route":{"es":"Aiwass se banea de la mano y trae un Aleister; Sacred Spirit Sword Aiwass lo invoca del Deck o Cementerio, o manda un Aleister al Cementerio para jugadas de recursos.","en":"Aiwass banishes itself from hand and brings an Aleister; Sacred Spirit Sword Aiwass Special Summons it from the Deck or GY, or sends an Aleister to the GY for resource plays."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Meltdown, el efecto de Aleister the Invoker o el de Reminiscent que agrega Invocation.","en":"When Meltdown, Aleister the Invoker's effect or Reminiscent's Invocation search is activated."},"loss":{"es":"Niega esa búsqueda. El mazo tiene pocas fuentes de Fusión consistentes, así que Ash en el primer eslabón suele costar la jugada: guardá Virakam o una segunda ruta.","en":"It negates that search. The deck has few consistent Fusion sources, so Ash at the first link often costs the play: keep Virakam or a second route."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno, normalmente Aleister o Invocation.","en":"After the first search of the turn, normally Aleister or Invocation."},"loss":{"es":"No hay más búsquedas ese turno: sin Invocation en la mano no hay Fusión. Abrí con Sword o Grail que ya estén en la mano para no depender de una segunda búsqueda.","en":"No more searches that turn: without Invocation in hand there is no Fusion. Open with Sword or Grail already in hand so you do not depend on a second search."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Cuando Aiwass se activa desde el Cementerio, o Invocation o Sword se mezclan de vuelta al Deck desde el Cementerio.","en":"When Aiwass activates from the GY, or Invocation or Sword shuffle back into the Deck from the GY."},"loss":{"es":"Niega esa activación (invocar del Cementerio, volver al Deck, banear del Cementerio). Sin recursión el mazo queda con las cartas de la mano, así que gastá primero lo que está en la mano.","en":"It negates that activation (Special Summon from the GY, return to the Deck, banish from the GY). Without recursion the deck is left with its hand, so spend what is in hand first."}},{"card":"Dimensional Barrier","step":"activation","stepText":{"es":"Declarando Fusion antes de tu Fusión, en respuesta a Invocation, Sword o Grail.","en":"Declaring Fusion before your Fusion, in response to Invocation, Sword or Grail."},"loss":{"es":"Meltdown evita la negación de la Fusión, pero esta Trampa no la niega: impide invocar Fusiones ese turno y niega las que están en el campo. Hay que rodearla con monstruos que no sean Fusión.","en":"Meltdown stops the Fusion from being negated, but this Trap does not negate it: it prevents Fusion Summons that turn and negates those on the field. You have to play around it with non-Fusion monsters."}}],"side":{"basis":"editorial","first":{"in":[{"card":"D.D. Crow","qty":2,"why":{"es":"Banea una carta del Cementerio rival en el turno rival, lo que corta sus efectos de Cementerio.","en":"Banishes a card in the opponent's GY on their turn, cutting their GY effects."}}],"out":[{"card":"Tuning","qty":2,"why":{"es":"Busca un Synchron y manda la carta de arriba al Cementerio; una carta lenta para el plan Invoked.","en":"Searches a Synchron and sends the top card to the GY; a slow card for the Invoked plan."}}]},"second":{"in":[{"card":"Veidos the Eruption Dragon of Extinction","qty":2,"why":{"es":"Yendo segundo, si hay una Zona de Campo rival, se juega a su campo y la destruye; si cae al Cementerio barre todos los monstruos.","en":"Going second, if a Field Zone card is out, it goes to their field and destroys it; if it reaches the GY it wipes every monster."}}],"out":[{"card":"Revolution Synchron","qty":2,"why":{"es":"Se juega en una ruta Synchro lenta; con el rival ya armado cuesta más que la ventaja que da.","en":"Used in a slow Synchro route; against an established opponent it costs more than the edge it gives."}}]}},"updated":"2026-10-26"},"gen/white-forest-azamina":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Una guía de YGOPRODeck dice que en Genesys quedan afuera el paquete Azamina y Sinful Spoils y White Forest queda como motor Sincro: Elzette, Astellar y Silvy llegan a Rciela y a los Sincro Angelechy.","en":"A YGOPRODeck guide says Genesys pushes the Azamina and Sinful Spoils packages out and leaves White Forest as a Synchro engine: Elzette, Astellar and Silvy reach Rciela and the Angelechy Synchros."},{"es":"Los Angelechy se colocan como Magias Continuas con efecto de campo: Shatranga limita a 5 los efectos de monstruo del rival, Destrier le hace 500 por cada activación y Bastion protege al resto de la destrucción.","en":"The Angelechy are placed as Continuous Spells with field effects: Shatranga limits the opponent to 5 monster effects, Destrier deals 500 per activation and Bastion protects the rest from destruction."},{"es":"Angelechy Problem es el punto de apoyo: descartando una Magia o Trampa invoca a un Angelechy de nivel 2 del Extra y pone otro como Magia. El mazo depende de él.","en":"Angelechy Problem is the fulcrum: discarding a Spell or Trap summons a Level 2 Angelechy from the Extra Deck and places another as a Spell. The deck depends on it."}]},"starters":[{"cards":["Elzette of the White Forest"],"route":{"es":"Elzette se invoca de la mano mandando una Magia o Trampa al Cementerio y agrega un White Forest, normalmente Silvy, que sigue con Tales of the White Forest.","en":"Elzette Special Summons from hand by sending a Spell or Trap to the GY and adds a White Forest, normally Silvy, which continues with Tales of the White Forest."}},{"cards":["Astellar of the White Forest","Silvy of the White Forest"],"route":{"es":"Astellar manda una Magia o Trampa al Cementerio e invoca un Tuner LIGHT Spellcaster; con Silvy (Tuner nivel 4) se llega a Rciela o a un Sincro de nivel 6.","en":"Astellar sends a Spell or Trap to the GY and summons a LIGHT Spellcaster Tuner; with Silvy (Level 4 Tuner) you reach Rciela or a Level 6 Synchro."}},{"cards":["Angelechy Problem"],"route":{"es":"Problem descarta una Magia o Trampa e invoca un Angelechy de nivel 2 del Extra Deck (Enlisted) y coloca un Angelechy más como Magia Continua.","en":"Problem discards a Spell or Trap and summons a Level 2 Angelechy from the Extra Deck (Enlisted) and places another Angelechy as a Continuous Spell."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Elzette (agrega un White Forest), Silvy o Rciela (agregan del Deck).","en":"When Elzette (adds a White Forest), Silvy or Rciela (add from the Deck) is activated."},"loss":{"es":"Corta la búsqueda: sin Silvy ni Tales el motor Sincro se frena. Elzette, Azamina (invoca desde la mano) y Problem (invoca desde el Extra) no se pueden frenar con Ash.","en":"It stops the search: without Silvy or Tales the Synchro engine stalls. Elzette, Azamina (summons from hand) and Problem (summons from the Extra Deck) cannot be stopped by Ash."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno.","en":"After the first search of the turn."},"loss":{"es":"Corta las demás búsquedas (Silvy, Tales, Rciela). Jugá primero la ruta que menos busca, por ejemplo Problem, y dejá la importante para después.","en":"It stops further searches (Silvy, Tales, Rciela). Play the least searching route first, such as Problem, and save the important one for later."}},{"card":"Nibiru, the Primal Being","step":"summon","stepText":{"es":"Con la quinta invocación del turno: Tuner, Sincro, Angelechy y token suman rápido.","en":"On the fifth summon of the turn: Tuners, Synchros, Angelechy and tokens add up fast."},"loss":{"es":"Tributa todo el campo (los Sincro incluidos) y deja un Token. Los Angelechy colocados como Magias no se tributan, así que el daño es menor si ya los pusiste.","en":"It Tributes the whole field (Synchros included) and leaves a Token. Angelechy placed as Spells are not Tributed, so the damage is smaller if you have placed them already."}},{"card":"Cosmic Cyclone","step":"main","stepText":{"es":"En tu Main Phase, sobre Angelechy Problem o un Angelechy colocado como Magia.","en":"In your Main Phase, on Angelechy Problem or an Angelechy placed as a Spell."},"loss":{"es":"Banear no es destruir, así que Bastion no lo protege. Sin Problem el plan se cae; guardá un segundo Angelechy en la mano o la fuente alternativa de Sincros.","en":"Banishing is not destroying, so Bastion does not protect it. Without Problem the plan falls apart; keep a second Angelechy in hand or the alternative Synchro source."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Annihilate Retroglight","qty":1,"why":{"es":"Niega un efecto de monstruo y banea todos los monstruos rivales boca arriba: una buena Trampa para yendo primero.","en":"Negates a monster effect and banishes all face-up opposing monsters: a good Trap going first."}},{"card":"Gravity Collapse","qty":1,"why":{"es":"Niega una invocación a cambio de mandar un Sincro al Cementerio.","en":"Negates a Summon by sending a Synchro to the GY."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Necesita no controlar cartas, algo que casi nunca pasa yendo primero tras armar el tablero.","en":"It needs you to control no cards, which almost never happens going first after building the board."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":1,"why":{"es":"Yendo segundo rompe una Magia o Trampa rival ya puesta.","en":"Going second it breaks an already set opposing Spell or Trap."}},{"card":"Twin Twisters","qty":1,"why":{"es":"Destruye hasta 2 cartas de campo a cambio de descartar 1.","en":"Destroys up to 2 field cards for 1 discard."}}],"out":[{"card":"Fifty Fifty?","qty":2,"why":{"es":"Es una apuesta al azar; con el rival ya armado conviene una respuesta fija.","en":"It is a random gamble; with the opponent already set up you want a fixed answer."}}]}},"updated":"2026-10-26"},"gen/fairy-tail":{"win":{"plan":"otk","pace":"medium","bullets":[{"es":"Fairy Tail Ball deja a los Fairy Tail atacar directo y niega un monstruo rival cuando invoca de Especial (queda como Prince of Fairies); varios Fairy Tail en el campo hacen daño directo rápido.","en":"Fairy Tail Ball lets Fairy Tail monsters attack directly and negates an opposing monster when it Special Summons (it becomes Prince of Fairies); several Fairy Tails on the field deal direct damage fast."},{"es":"Luna agrega un Spellcaster de 1850 de ATK, Matchgiru agrega una Magia Fairy Tail y Tails of the Fairy Tails Fusiona. Weaver y Teller usan Prince of Fairies como material, y Teller destruye cartas rivales e inflige 500 por cada una.","en":"Luna adds a Spellcaster with 1850 ATK, Matchgiru adds a Fairy Tail Spell and Tails of the Fairy Tails Fusion Summons. Weaver and Teller use Prince of Fairies as material, and Teller destroys opposing cards and deals 500 for each."},{"es":"Hay un motor Endymion (Regulus, Empire of Endymion) y un paquete Nekroz para Ritual y recursos. Una guía de YGOPRODeck sobre Genesys lo describe como un mazo Spellcaster de varios motores.","en":"There is an Endymion engine (Regulus, Empire of Endymion) and a Nekroz package for Ritual and resources. A YGOPRODeck Genesys guide describes it as a multi-engine Spellcaster deck."}]},"starters":[{"cards":["Fairy Tail - Luna","Fairy Tail - Matchgiru"],"route":{"es":"Luna (Invocación Normal) agrega un Spellcaster de 1850 de ATK; Matchgiru se invoca de la mano si hay uno en el campo y agrega una Magia o Trampa Fairy Tail, como Ball.","en":"Luna (Normal Summon) adds a Spellcaster with 1850 ATK; Matchgiru Special Summons from hand if one is on the field and adds a Fairy Tail Spell or Trap, such as Ball."}},{"cards":["Regulus, the Prince of Endymion"],"route":{"es":"Regulus se invoca de la mano revelando otro Spellcaster y perdiendo LP, y al invocarse agrega una Magia que lo menciona. Es el arranque del motor Endymion.","en":"Regulus Special Summons from hand revealing another Spellcaster and losing LP, and when summoned adds a Spell that mentions it. It starts the Endymion engine."}},{"cards":["Emilia, Dance Priestess of the Nekroz"],"route":{"es":"Emilia se invoca de la mano si hay un Nekroz Warrior y agrega un Ritual o Magia Nekroz; es la entrada al paquete Nekroz y a Brionac.","en":"Emilia Special Summons from hand if a Nekroz Warrior is around and adds a Nekroz Ritual or Spell; it enters the Nekroz package and Brionac."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Cuando se activa Luna, Matchgiru, Emilia o Regulus (agregar del Deck).","en":"When Luna, Matchgiru, Emilia or Regulus (add from the Deck) is activated."},"loss":{"es":"Corta esa búsqueda y con ella la jugada. Hay varios motores: si Ash cae en uno, pasá a otro en vez de insistir con el mismo.","en":"It stops that search and with it the play. There are several engines: if Ash lands on one, move to another instead of pushing the same one."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Después de la primera búsqueda del turno (Luna, Emilia, Regulus).","en":"After the first search of the turn (Luna, Emilia, Regulus)."},"loss":{"es":"Ninguna otra búsqueda ese turno. Usá primero el efecto que no busca, por ejemplo la invocación de Matchgiru desde la mano.","en":"No further searches that turn. Use the effect that does not search first, such as Matchgiru's Special Summon from hand."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Cuando Snow o Matchgiru se activan desde el Cementerio, o Genia / Nekroz recuperan cartas.","en":"When Snow or Matchgiru activate from the GY, or Genia / Nekroz recover cards."},"loss":{"es":"Niega esa activación (invocar desde el Cementerio o recuperar). Los Fairy Tail también se juegan desde la mano: gastá primero la mano y dejá el Cementerio para después.","en":"It negates that activation (Special Summon from the GY or recovery). Fairy Tails also play from hand: spend the hand first and leave the GY for later."}},{"card":"Dimensional Barrier","step":"activation","stepText":{"es":"Declarando Fusion, Ritual o Xyz en tu Main Phase, justo antes de Tails, Nekroz o Wiccat.","en":"Declaring Fusion, Ritual or Xyz in your Main Phase, right before Tails, Nekroz or Wiccat."},"loss":{"es":"Cierra la invocación de ese tipo ese turno y niega a los que ya están. El mazo juega los tres tipos, así que cambiá de motor al que no declararon.","en":"It closes Summons of that type this turn and negates those already out. The deck plays all three types, so switch to an engine they did not declare."}}],"side":{"basis":"editorial","first":{"in":[{"card":"The Eye of Truth","qty":2,"why":{"es":"Muestra la mano rival para jugar alrededor de handtraps; yendo primero ayuda a mover antes.","en":"Shows the opponent's hand so you can play around handtraps; going first it helps you plan ahead."}}],"out":[{"card":"D.D. Crow","qty":2,"why":{"es":"Yendo primero el Cementerio rival está vacío y Crow no tiene objetivo.","en":"Going first the opponent's GY is empty and Crow has no target."}}]},"second":{"in":[{"card":"Santa Claws","qty":2,"why":{"es":"Va al campo rival tributando uno de sus monstruos y roba al final: quita un obstáculo yendo segundo.","en":"Goes to their field Tributing one of their monsters and draws in the End Phase: removes an obstacle going second."}}],"out":[{"card":"Skull Meister","qty":2,"why":{"es":"Solo cubre efectos de Cementerio; yendo segundo conviene más sacar monstruos del tablero.","en":"It only covers GY effects; going second removing monsters from the board is better."}}]}},"updated":"2026-10-26"},"goat/chaos-turbo":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Gana por ventaja de cartas: los monstruos Flip (Magician of Faith, Night Assailant, Gravekeeper's Spy, Dekoichi) rinden solos y Graceful Charity y Card Destruction mantienen la mano llena.","en":"Wins on card advantage: Flip monsters (Magician of Faith, Night Assailant, Gravekeeper's Spy, Dekoichi) generate value on their own, and Graceful Charity and Card Destruction keep the hand full."},{"es":"Thunder Dragon es descarte gratis: llena el Cementerio de LIGHT para invocar Chaos Sorcerer o Black Luster Soldier sin gastar recursos.","en":"Thunder Dragon is free discard fodder: it fills the Graveyard with LIGHT so Chaos Sorcerer or Black Luster Soldier come out without spending resources."},{"es":"Raigeki Break y Night Assailant se apoyan en ese descarte: lo que tirás vuelve (Night Assailant recupera un Flip) o se convierte en destrucción.","en":"Raigeki Break and Night Assailant lean on that discard: what you throw away comes back (Night Assailant returns a Flip monster) or turns into removal."},{"es":"Chaos Sorcerer es la amenaza principal: banish por turno y 2300 de ATK. Si te falta LIGHT o DARK en el Cementerio, la mano se atasca.","en":"Chaos Sorcerer is the main threat: a banish each turn plus 2300 ATK. If you lack a LIGHT or DARK in the Graveyard, the hand clogs."}]},"starters":[{"cards":["Thunder Dragon","Graceful Charity"],"route":{"es":"Descartás Thunder Dragon con Graceful Charity: robás 3, dejás un LIGHT en el Cementerio y ya tenés media condición de Chaos Sorcerer.","en":"Discard Thunder Dragon to Graceful Charity: draw 3 and leave a LIGHT in the Graveyard, half the condition for Chaos Sorcerer."}},{"cards":["Night Assailant","Raigeki Break"],"route":{"es":"Mandás Night Assailant al Cementerio como costo de Raigeki Break: destruís una carta y Assailant devuelve un Flip del Cementerio a la mano.","en":"Send Night Assailant to the Graveyard as Raigeki Break's cost: destroy a card and Assailant returns a Flip monster from the Graveyard to your hand."}},{"cards":["Magician of Faith"],"route":{"es":"La seteás como cebo: al girar recupera un Pot of Greed, Graceful Charity o Heavy Storm ya usado.","en":"Set it as bait: on flip it gets back a used Pot of Greed, Graceful Charity or Heavy Storm."}}],"chokepoints":[{"card":"Nobleman of Crossout","step":"activation","stepText":{"es":"Al activarla sobre tu Flip seteado, antes de que se pueda girar.","en":"On activation against your set Flip monster, before it can flip."},"loss":{"es":"Destierra el monstruo y todas sus copias del Deck: perdés el valor de Faith o Spy. Seteá dos Flip distintos y no dependas de uno solo.","en":"Banishes the monster and every copy in the Deck: you lose the value of Faith or Spy. Set two different Flips and do not rely on one."}},{"card":"Tsukuyomi","step":"summon","stepText":{"es":"Al invocarla de Normal: da vuelta a Posición boca abajo a tu Chaos Sorcerer o Black Luster Soldier.","en":"On its Normal Summon: it turns your Chaos Sorcerer or Black Luster Soldier face-down."},"loss":{"es":"Tu amenaza grande queda anulada y se repite cada turno (vuelve a la mano en la End Phase). Tenés que sacarla con Sorcerer boca arriba antes o con Raigeki Break.","en":"Your big threat is neutralized and it repeats every turn (it returns to hand in the End Phase). Remove it with a face-up Sorcerer first or Raigeki Break."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba en el campo rival, antes de que invoques Chaos.","en":"Face-up on the opponent's field before you summon Chaos."},"loss":{"es":"Impide desterrar cartas de los Cementerios: Chaos Sorcerer y Black Luster Soldier no se pueden invocar. Hay que matarlo con Raigeki Break o Night Assailant primero.","en":"Stops banishing from Graveyards: Chaos Sorcerer and Black Luster Soldier cannot be summoned. Kill it with Raigeki Break or Night Assailant first."}},{"card":"Mystic Swordsman LV2","step":"attack","stepText":{"es":"En su ataque contra tu monstruo seteado, al empezar el daño.","en":"On its attack into your set monster, at the start of the Damage Step."},"loss":{"es":"Destruye el Flip seteado antes de que se pueda dar vuelta, sin efecto. Dejá un Flip de relleno adelante o matalo con Raigeki Break.","en":"Destroys the set Flip monster before it can flip, with no effect. Set a throwaway Flip in front or kill it with Raigeki Break."}},{"card":"Solemn Judgment","step":"summon","stepText":{"es":"En la invocación especial de Chaos Sorcerer o Black Luster Soldier.","en":"On the Special Summon of Chaos Sorcerer or Black Luster Soldier."},"loss":{"es":"Perdés el monstruo y los dos destierros ya se pagaron. Invocá primero lo menos importante para ver si lo gastan.","en":"You lose the monster and both banishes were already paid. Summon the least important piece first to see if they spend it."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Trap Dustshoot","qty":2,"why":{"es":"Yendo primero, el rival recoge hasta 6 cartas en su primer turno: Dustshoot le saca el monstruo clave.","en":"Going first, the opponent holds up to 6 cards on their first turn: Dustshoot removes their key monster."}}],"out":[{"card":"Jar of Greed","qty":2,"why":{"es":"Es la carta más débil si el rival ya tiene tempo.","en":"It is the weakest card when the opponent has tempo."}}]},"second":{"in":[{"card":"Sakuretsu Armor","qty":2,"why":{"es":"Yendo segundo no tenés el primer turno: frena sus primeros ataques sin gastar monstruos.","en":"Going second you lack the first turn: it stops their first attacks without spending monsters."}}],"out":[{"card":"Upstart Goblin","qty":2,"why":{"es":"Le regala 1000 LP al rival cuando ya vas atrás en el tablero.","en":"It gives the opponent 1000 LP when you are already behind on board."}}]}},"updated":"2026-10-26"},"goat/warrior":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"Presiona con monstruos de ataque alto y gana antes de que el rival arme el tablero: Blade Knight llega a 2000 de ATK con la mano casi vacía.","en":"Pressures with high ATK monsters and wins before the opponent builds a board: Blade Knight reaches 2000 ATK with a near-empty hand."},{"es":"Reinforcement of the Army es el motor: busca el Warrior que pide la situación (Exiled Force, D.D. Warrior Lady, Mystic Swordsman LV2, Blade Knight, Don Zaloog).","en":"Reinforcement of the Army is the engine: it fetches the Warrior the situation needs (Exiled Force, D.D. Warrior Lady, Mystic Swordsman LV2, Blade Knight, Don Zaloog)."},{"es":"Las trampas (Solemn Judgment, Sakuretsu Armor, Mirror Force, Torrential Tribute) defienden en el turno rival mientras los monstruos siguen atacando.","en":"Traps (Solemn Judgment, Sakuretsu Armor, Mirror Force, Torrential Tribute) defend on the opponent's turn while the monsters keep attacking."},{"es":"Genera poca ventaja propia: depende de ganar los intercambios en batalla y de descartes (Don Zaloog), por eso necesita el ritmo.","en":"It creates little card advantage of its own: it relies on winning battle trades and discard (Don Zaloog), so it needs the tempo."}]},"starters":[{"cards":["Reinforcement of the Army"],"route":{"es":"Una carta que se convierte en la respuesta: Exiled Force para un monstruo grande, D.D. Warrior Lady para un Flip o Mystic Swordsman LV2 para un seteado.","en":"One card that becomes the answer: Exiled Force for a big monster, D.D. Warrior Lady for a threat, or Mystic Swordsman LV2 for a set monster."}},{"cards":["Don Zaloog"],"route":{"es":"Invocación normal de 1400 de ATK: si conecta, descarta una carta al azar de la mano rival o manda 2 cartas de su Deck al Cementerio.","en":"A 1400 ATK Normal Summon: if it connects, it discards a random card from the opponent's hand or sends their top 2 cards to the Graveyard."}},{"cards":["Mystic Swordsman LV2"],"route":{"es":"Ataca un monstruo seteado y lo destruye al empezar el daño, sin que se resuelva el Flip.","en":"Attacks a set monster and destroys it at the start of the Damage Step, so the Flip never resolves."}}],"chokepoints":[{"card":"Tsukuyomi","step":"summon","stepText":{"es":"Al invocarla, da vuelta a Posición boca abajo a tu Blade Knight.","en":"On Normal Summon, it turns your Blade Knight face-down."},"loss":{"es":"Blade Knight es muy débil a Tsukuyomi. Tené Reinforcement o Mystic Swordsman para castigar la jugada y no pongas todo en un solo monstruo.","en":"Blade Knight is very weak to Tsukuyomi. Keep Reinforcement or Mystic Swordsman to punish the play and do not put everything on one monster."}},{"card":"Magician of Faith","step":"resolution","stepText":{"es":"Al resolverse el Flip: recupera un Pot of Greed, Graceful Charity o Heavy Storm.","en":"On the Flip resolving: it gets back Pot of Greed, Graceful Charity or Heavy Storm."},"loss":{"es":"Le da al rival una carta de poder que Warrior no iguala. Matala seteada con Mystic Swordsman o Nobleman antes de que gire.","en":"It hands the opponent a power spell Warrior cannot match. Kill it face-down with Mystic Swordsman or Nobleman before it flips."}},{"card":"Scapegoat","step":"main","stepText":{"es":"En la Main Phase rival: 4 Sheep Tokens en Defensa.","en":"In the opponent's Main Phase: 4 Sheep Tokens in Defense."},"loss":{"es":"Absorben ataques y habilitan Metamorphosis. Sin Book of Moon es difícil de pasar, así que Heavy Storm, Breaker o Mystic Swordsman buscan el valor detrás.","en":"They absorb attacks and enable Metamorphosis. Without Book of Moon it is hard to push through, so Heavy Storm, Breaker or Mystic Swordsman look for the value behind it."}},{"card":"Mirror Force","step":"attack","stepText":{"es":"En tu declaración de ataque con varios monstruos en Ataque.","en":"On your attack declaration with several monsters in Attack Position."},"loss":{"es":"Destruye todos tus monstruos en Ataque. Atacá con uno solo si hay trampas boca abajo, y guardá Dust Tornado o Heavy Storm para destapar.","en":"Destroys all your Attack Position monsters. Attack with one only if face-down Traps are present and save Dust Tornado or Heavy Storm to clear them."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Gravekeeper's Spy","qty":2,"why":{"es":"Contra control, un Flip de 2000 DEF frena a tus atacantes y trae más cuerpos.","en":"Against control, a 2000 DEF Flip body stalls their attackers and brings extra bodies."}},{"card":"Spirit Reaper","qty":1,"why":{"es":"No muere en batalla y descarta al conectar directo.","en":"It survives battle and discards on direct hits."}}],"out":[{"card":"Sakuretsu Armor","qty":2,"why":{"es":"Contra control seteado tiene pocos blancos.","en":"Against set control it has few targets."}},{"card":"Tribe-Infecting Virus","qty":1,"why":{"es":"Cuesta una carta y rara vez limpia algo relevante contra control.","en":"It costs a card and rarely clears anything relevant against control."}}]},"second":{"in":[{"card":"Book of Moon","qty":1,"why":{"es":"Respuesta a Thousand-Eyes Restrict o a un Chaos Sorcerer que da vuelta tu ataque.","en":"An answer to a Thousand-Eyes Restrict or a Chaos Sorcerer turning your attack."}},{"card":"Smashing Ground","qty":1,"why":{"es":"Mata el Flip de 2000 DEF (Spy) o el cuerpo defensivo más alto.","en":"Kills the 2000 DEF Flip (Spy) or the highest defensive body."}}],"out":[{"card":"Xing Zhen Hu","qty":1,"why":{"es":"Reactiva demasiado lento si el rival juega a su ritmo.","en":"Too slow if the opponent plays at their own pace."}},{"card":"Premature Burial","qty":1,"why":{"es":"Costo de 800 LP en una partida donde vas segundo y bajo presión.","en":"An 800 LP cost in a game where you are second and under pressure."}}]}},"updated":"2026-10-26"},"goat/chaos-control":{"win":{"plan":"grind","pace":"slow","bullets":[{"es":"Juega a largo plazo: Scapegoat da Sheep Tokens que sostienen la defensa y alimentan Metamorphosis para llegar a Thousand-Eyes Restrict, que frena el combate rival.","en":"Plays the long game: Scapegoat gives Sheep Tokens that hold the defense and feed Metamorphosis to reach Thousand-Eyes Restrict, which locks the opponent's combat."},{"es":"Chaos Sorcerer es la mejora tardía: destierra un monstruo al entrar y tiene techo mayor que el Goat Control clásico.","en":"Chaos Sorcerer is the late-game upgrade: it banishes a monster on entry and has a higher ceiling than classic Goat Control."},{"es":"Thunder Dragon adelgaza el Deck, deja LIGHT en el Cementerio para Chaos Sorcerer y Black Luster Soldier, y sirve de cuerpo de nivel 5 para Metamorphosis.","en":"Thunder Dragon thins the deck, leaves a LIGHT in the Graveyard for Chaos Sorcerer and Black Luster Soldier, and doubles as a Level 5 body for Metamorphosis."},{"es":"Tsukuyomi y Book of Moon reciclan los Flip (Magician of Faith, Spy) para ganar cartas turno a turno.","en":"Tsukuyomi and Book of Moon recycle Flip monsters (Magician of Faith, Spy) to gain cards turn after turn."}]},"starters":[{"cards":["Scapegoat","Metamorphosis"],"route":{"es":"Scapegoat y después Metamorphosis tributando un Sheep Token (nivel 1): entra Thousand-Eyes Restrict. Los otros monstruos del campo no pueden atacar ni cambiar de posición.","en":"Scapegoat, then Metamorphosis tributing a Sheep Token (Level 1): Thousand-Eyes Restrict comes out. Other monsters on the field cannot attack or change position."}},{"cards":["Thunder Dragon","Chaos Sorcerer"],"route":{"es":"Thunder Dragon al Cementerio con descarte (Graceful Charity) y un DARK después: Chaos Sorcerer destierra el mejor monstruo rival.","en":"Thunder Dragon to the Graveyard by discard (Graceful Charity) plus a DARK later: Chaos Sorcerer banishes the opponent's best monster."}},{"cards":["Magician of Faith"],"route":{"es":"Seteada, al girar recupera un Pot of Greed o Graceful Charity ya usado, o un Heavy Storm.","en":"Set, on flip it recovers a used Pot of Greed or Graceful Charity, or a Heavy Storm."}}],"chokepoints":[{"card":"Scapegoat","step":"main","stepText":{"es":"El rival la activa en su Main Phase y llena su campo de Sheep Tokens.","en":"The opponent activates it in their Main Phase and fills their field with Sheep Tokens."},"loss":{"es":"Pasás a ser el que no puede atacar. Asura Priest (ataca a todos los monstruos) es la respuesta de la lista y es una sola copia.","en":"You become the one who cannot attack. Asura Priest (attacks all monsters) is the list's answer and it is a single copy."}},{"card":"Nobleman of Crossout","step":"activation","stepText":{"es":"Al activarla sobre tu Magician of Faith seteado.","en":"On activation against your set Magician of Faith."},"loss":{"es":"Destierra el LIGHT principal para Black Luster Soldier y todas sus copias. Si ves Nobleman, poné el Flip menos valioso por delante.","en":"Banishes the main LIGHT for Black Luster Soldier and all its copies. If Nobleman shows up, put the less valuable Flip in front."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba en el campo rival antes de tu Chaos.","en":"Face-up on the opponent's field before your Chaos monster."},"loss":{"es":"Bloquea el destierro del Cementerio: Chaos Sorcerer y Black Luster Soldier quedan trabados. Sacalo con Chaos Sorcerer ya en juego, Tsukuyomi o una trampa.","en":"Blocks Graveyard banishing: Chaos Sorcerer and Black Luster Soldier stay locked. Remove it with an already-active Chaos Sorcerer, Tsukuyomi or a Trap."}},{"card":"Royal Decree","step":"main","stepText":{"es":"Boca arriba antes de tu turno: anula los efectos de todas las demás trampas.","en":"Face-up before your turn: negates every other Trap's effect."},"loss":{"es":"Mirror Force, Torrential Tribute y Ring of Destruction quedan inútiles. Sacalo con Heavy Storm o Mystical Space Typhoon y mientras tanto presioná con monstruos.","en":"Mirror Force, Torrential Tribute and Ring of Destruction become useless. Remove it with Heavy Storm or Mystical Space Typhoon and pressure with monsters meanwhile."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Trap Dustshoot","qty":2,"why":{"es":"Contra Chaos Turbo y combo: yendo primero ve su mano de 6 y le saca el monstruo clave.","en":"Against Chaos Turbo and combo: going first it sees their 6-card hand and strips the key monster."}}],"out":[{"card":"Jar of Greed","qty":2,"why":{"es":"Es robo barato pero lento cuando necesitás interactuar.","en":"A cheap draw but slow when you need to interact."}}]},"second":{"in":[{"card":"Mind Control","qty":1,"why":{"es":"Contra Chaos Turbo, roba el Chaos Sorcerer o el Thunder Dragon que defiende.","en":"Against Chaos Turbo, steals the Chaos Sorcerer or Thunder Dragon that defends."}},{"card":"Mystical Space Typhoon","qty":1,"why":{"es":"Saca una trampa o Magia continua del rival que frena el plan.","en":"Removes a Spell or Trap of the opponent that stops the plan."}}],"out":[{"card":"Delinquent Duo","qty":1,"why":{"es":"Cuesta 1000 LP y contra decks rápidos no compensa.","en":"Costs 1000 LP and does not pay off against fast decks."}},{"card":"Upstart Goblin","qty":1,"why":{"es":"Le da LP al rival cuando te tenés que ahorrar tempo.","en":"Gives LP to the opponent when you need to save tempo."}}]}},"updated":"2026-10-26"},"goat/goat-control":{"win":{"plan":"control","pace":"slow","bullets":[{"es":"Trampa de control clásica: Scapegoat da cuatro Sheep Tokens y Metamorphosis los convierte en Thousand-Eyes Restrict para trabar el combate rival.","en":"Classic control shell: Scapegoat gives four Sheep Tokens and Metamorphosis turns them into Thousand-Eyes Restrict to lock the opponent's combat."},{"es":"Royal Decree (3 copias) anula las trampas rivales, y como el Main casi no juega trampas propias no se perjudica a sí mismo.","en":"Royal Decree (3 copies) negates the opponent's Traps, and since the Main plays almost no Traps of its own it does not hurt itself."},{"es":"Magician of Faith y Thunder Dragon aportan el LIGHT que necesita Black Luster Soldier, y Faith recupera Pot of Greed o Heavy Storm.","en":"Magician of Faith and Thunder Dragon supply the LIGHT that Black Luster Soldier needs, and Faith recovers Pot of Greed or Heavy Storm."},{"es":"Su punto flojo es Nobleman of Crossout sobre Magician of Faith: sin ese LIGHT, Black Luster Soldier se complica.","en":"Its weak spot is Nobleman of Crossout on Magician of Faith: without that LIGHT, Black Luster Soldier gets harder."}]},"starters":[{"cards":["Scapegoat","Metamorphosis"],"route":{"es":"Scapegoat y Metamorphosis tributando un Sheep Token: Thousand-Eyes Restrict (se puede equipar el mejor monstruo rival).","en":"Scapegoat plus Metamorphosis tributing a Sheep Token: Thousand-Eyes Restrict, which can equip the opponent's best monster."}},{"cards":["Royal Decree"],"route":{"es":"Seteado al comienzo: apaga Mirror Force, Torrential Tribute y compañía hasta que lo destruyan.","en":"Set early: shuts off Mirror Force, Torrential Tribute and the like until it is destroyed."}},{"cards":["Magician of Faith"],"route":{"es":"Setearla como cebo, girar para recuperar una Magia gastada y dejar un LIGHT en el Cementerio.","en":"Set it as bait, flip to recover a spent Spell and leave a LIGHT in the Graveyard."}}],"chokepoints":[{"card":"Nobleman of Crossout","step":"activation","stepText":{"es":"Al activarla sobre tu Magician of Faith seteado.","en":"On activation against your set Magician of Faith."},"loss":{"es":"Destierra el LIGHT y las copias que quedaban. Guardá un Thunder Dragon o un segundo LIGHT para Black Luster Soldier.","en":"Banishes the LIGHT and its remaining copies. Keep a Thunder Dragon or second LIGHT for Black Luster Soldier."}},{"card":"Heavy Storm","step":"resolution","stepText":{"es":"Al resolverse: destruye tu Royal Decree y tus Magias de campo.","en":"On resolution: destroys your Royal Decree and your field Spells."},"loss":{"es":"Sin Decree, las trampas rivales vuelven a funcionar. Seteá un segundo Decree o jugá con monstruos que no dependan de él.","en":"Without Decree, the opponent's Traps work again. Set a second Decree or play monsters that do not depend on it."}},{"card":"Mobius the Frost Monarch","step":"summon","stepText":{"es":"En su invocación por tributo: destruye hasta 2 Magias/Trampas.","en":"On its Tribute Summon: destroys up to 2 Spells/Traps."},"loss":{"es":"Se lleva Royal Decree y otra carta. Restrict o un Sheep Token con Creature Swap lo frenan antes del ataque.","en":"It takes Royal Decree and another card. Restrict or a Sheep Token with Creature Swap stops it before the attack."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba antes de que invoques Black Luster Soldier.","en":"Face-up before you summon Black Luster Soldier."},"loss":{"es":"No se pueden desterrar cartas de los Cementerios: Black Luster Soldier no entra. Usá Tsukuyomi o Thousand-Eyes Restrict para sacarlo de juego.","en":"Cards cannot be banished from Graveyards: Black Luster Soldier cannot enter. Use Tsukuyomi or Thousand-Eyes Restrict to remove it from play."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Kycoo the Ghost Destroyer","qty":1,"why":{"es":"Contra Chaos Turbo, bloquea el destierro de sus Chaos.","en":"Against Chaos Turbo, blocks their Chaos banishing."}},{"card":"Mind Control","qty":1,"why":{"es":"Contra Chaos Turbo, roba Thunder Dragon o Chaos Sorcerer.","en":"Against Chaos Turbo, steals Thunder Dragon or Chaos Sorcerer."}}],"out":[{"card":"Tsukuyomi","qty":1,"why":{"es":"Pierde valor si hay que protegerse de Kycoo o del ataque del rival.","en":"Loses value when you must protect yourself from Kycoo or the opponent's attack."}},{"card":"Book of Moon","qty":1,"why":{"es":"Respuesta de nicho que no ayuda a cerrar la partida.","en":"A niche answer that does not help close the game."}}]},"second":{"in":[{"card":"Chaos Sorcerer","qty":1,"why":{"es":"Remueve monstruos que Restrict no cubre.","en":"Removes monsters Restrict does not cover."}}],"out":[{"card":"United We Stand","qty":1,"why":{"es":"Va segundo y necesitás respuestas, no un equipo que depende de tener tablero.","en":"Going second you need answers, not an equip that relies on having a board."}}]}},"updated":"2026-10-26"},"goat/chaos-warrior-turbo":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"Híbrido de Warrior y Chaos Turbo: Reinforcement of the Army busca el Warrior justo y Thunder Dragon llena el Cementerio para invocar Chaos Sorcerer o Black Luster Soldier.","en":"Hybrid of Warrior and Chaos Turbo: Reinforcement of the Army fetches the right Warrior and Thunder Dragon fills the Graveyard to summon Chaos Sorcerer or Black Luster Soldier."},{"es":"Los Chaos vuelven cuando tus monstruos mueren, por eso se puede atacar con confianza intercambiando 1 a 1 en batalla.","en":"Chaos monsters come back when your monsters die, so you can attack confidently and trade 1 for 1 in battle."},{"es":"Kycoo es el arma contra otros Chaos y Mystic Tomato o Sangan dan relleno DARK para el Cementerio.","en":"Kycoo is the weapon against other Chaos decks and Mystic Tomato or Sangan give DARK filler for the Graveyard."},{"es":"Se traba si tiene Chaos en la mano y no tiene LIGHT y DARK en el Cementerio: más de 15 monstruos y un solo Reinforcement ayudan a evitarlo.","en":"It stalls if you hold Chaos monsters without LIGHT and DARK in the Graveyard: a solid monster count and Reinforcement help avoid it."}]},"starters":[{"cards":["Reinforcement of the Army"],"route":{"es":"Busca Don Zaloog, Exiled Force, Sasuke o D.D. Warrior Lady; sirve también para encontrar el LIGHT o DARK que falta.","en":"Fetches Don Zaloog, Exiled Force, Sasuke or D.D. Warrior Lady; also finds the missing LIGHT or DARK."}},{"cards":["Thunder Dragon","Graceful Charity"],"route":{"es":"Descartás Thunder Dragon con Graceful Charity: LIGHT en el Cementerio y robás 3.","en":"Discard Thunder Dragon to Graceful Charity: LIGHT in the Graveyard and draw 3."}},{"cards":["Mystic Tomato"],"route":{"es":"Si lo destruyen en batalla, trae un DARK de 1500 de ATK o menos (Sangan, Don Zaloog) y deja el material de Chaos.","en":"If destroyed in battle, it brings a DARK with 1500 ATK or less (Sangan, Don Zaloog) and leaves Chaos material."}}],"chokepoints":[{"card":"Magician of Faith","step":"resolution","stepText":{"es":"Al resolverse el Flip del rival: recupera una Magia fuerte.","en":"When the opponent's Flip resolves: it recovers a strong Spell."},"loss":{"es":"Le da al rival Pot of Greed o Graceful Charity otra vez y el deck tiene pocas Magias de poder. Matalo seteado con Mystic Swordsman o Nobleman.","en":"Gives the opponent Pot of Greed or Graceful Charity again and the deck has few power spells. Kill it face-down."}},{"card":"Scapegoat","step":"main","stepText":{"es":"En la Main Phase rival: 4 Sheep Tokens en Defensa.","en":"In the opponent's Main Phase: 4 Sheep Tokens in Defense."},"loss":{"es":"Absorbe tus ataques y arma Metamorphosis. Con pocos Book of Moon no hay buena respuesta: usá Sorcerer y Dust Tornado para buscar valor.","en":"Absorbs your attacks and sets up Metamorphosis. With little Book of Moon there is no good answer: use Sorcerer and Dust Tornado to find value."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba en el campo rival antes de tu Chaos.","en":"Face-up on the opponent's field before your Chaos."},"loss":{"es":"Bloquea los destierros de Cementerio y traba a Chaos Sorcerer y Black Luster Soldier. Sacalo con Exiled Force o Raigeki Break.","en":"Blocks Graveyard banishing and locks Chaos Sorcerer and Black Luster Soldier. Remove it with Exiled Force or Raigeki Break."}},{"card":"Necrovalley","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase.","en":"Face-up before your Main Phase."},"loss":{"es":"Impide interactuar con el Cementerio: los Chaos y Premature Burial dejan de funcionar. Heavy Storm o Mystical Space Typhoon la sacan.","en":"Stops Graveyard interaction: Chaos monsters and Premature Burial stop working. Heavy Storm or Mystical Space Typhoon removes it."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Gravekeeper's Spy","qty":2,"why":{"es":"Contra Chaos Control y Goat Control, un Flip de 2000 DEF aguanta y trae cuerpos.","en":"Against Chaos Control and Goat Control, a 2000 DEF Flip holds and brings bodies."}}],"out":[{"card":"Mystic Tomato","qty":1,"why":{"es":"Poco valor contra control que no ataca.","en":"Low value against control that does not attack."}},{"card":"Card Destruction","qty":1,"why":{"es":"Le da cartas al rival que juega a largo plazo.","en":"Gives cards to an opponent playing the long game."}}]},"second":{"in":[{"card":"Sakuretsu Armor","qty":3,"why":{"es":"Yendo segundo defendés tu primer turno con trampas baratas.","en":"Going second you defend your first turn with cheap Traps."}}],"out":[{"card":"Jar of Greed","qty":3,"why":{"es":"Pierde valor si el rival va a presionar con el tempo.","en":"Loses value if the opponent is pressuring with tempo."}}]}},"updated":"2026-10-26"},"goat/chaos-return":{"win":{"plan":"tempo","pace":"medium","bullets":[{"es":"Variante de Chaos con Return from the Different Dimension: se destierran monstruos (propios con Nobleman o Chaos) y se devuelven todos de golpe pagando la mitad de los LP.","en":"A Chaos variant built around Return from the Different Dimension: monsters are banished (your own via Nobleman or Chaos) and all brought back at once for half your LP."},{"es":"Juega al máximo Spy y Dekoichi: los Flip rinden, y a veces te conviene que el rival los destierre con Nobleman.","en":"Plays Spy and Dekoichi at max: the Flips generate value, and sometimes it is fine for the opponent to Nobleman them."},{"es":"Zaborg the Thunder Monarch y los monstruos grandes mantienen el tempo cuando no hay Return, y Solemn Judgment protege los ataques fuertes.","en":"Zaborg the Thunder Monarch and the large monsters keep tempo when Return is not available, and Solemn Judgment protects the big attacks."},{"es":"Es agresivo: busca ganar el tempo frente a Warrior y Earth Aggro, y Kycoo (3 copias) es el seguro contra Chaos Turbo.","en":"It is aggressive: it aims to win tempo against Warrior and Earth Aggro, and Kycoo (3 copies) is the insurance against Chaos Turbo."}]},"starters":[{"cards":["Return from the Different Dimension","Nobleman of Crossout"],"route":{"es":"Nobleman sobre un Flip (propio o rival) destierra monstruos; cuando hay varios fuera, pagás la mitad de los LP y Return los devuelve para un golpe grande.","en":"Nobleman on a Flip monster (yours or theirs) banishes monsters; once several are out, pay half your LP and Return brings them back for a big hit."}},{"cards":["Shining Angel"],"route":{"es":"Si muere en batalla trae del Deck un LIGHT de 1500 de ATK o menos (Magician of Faith), que además deja LIGHT en el Cementerio para Chaos Sorcerer.","en":"If it dies in battle it brings a LIGHT with 1500 ATK or less from the Deck (Magician of Faith), which also feeds the Graveyard the LIGHT that Chaos Sorcerer needs."}},{"cards":["Gravekeeper's Spy","Dekoichi the Battlechanted Locomotive"],"route":{"es":"Flips que valen carta si los dan vuelta o los destierran: dejan DARK para Sorcerer y chequean la mano rival.","en":"Flips worth a card whether flipped or banished: they leave a DARK for Sorcerer and check the opponent's hand."}}],"chokepoints":[{"card":"Royal Decree","step":"activation","stepText":{"es":"Al activar Return from the Different Dimension: la trampa queda anulada.","en":"When you activate Return from the Different Dimension: the Trap is negated."},"loss":{"es":"Ese Royal Decree apaga tu Return. Sacalo con Dust Tornado o Heavy Storm antes de la jugada.","en":"That Royal Decree shuts off your Return. Clear it with Dust Tornado or Heavy Storm before the play."}},{"card":"Solemn Judgment","step":"activation","stepText":{"es":"Al activar Return: pagás la mitad de los LP y la carta se anula.","en":"When you activate Return: you pay half your LP and the card is negated."},"loss":{"es":"Return se pierde y ya pagaste los LP. Jugá primero otra trampa o monstruo para ver si lo gastan.","en":"Return is lost and you already paid the LP. Play another Trap or monster first to see if they spend it."}},{"card":"Torrential Tribute","step":"summon","stepText":{"es":"Al devolver monstruos con Return: es una invocación especial.","en":"When Return brings the monsters back: that is a Special Summon."},"loss":{"es":"Destruye todos los monstruos del campo, los tuyos incluidos, y perdés la ventaja. Mirá el campo rival antes y atacá con pocos monstruos.","en":"Destroys all monsters on the field, yours included, and you lose the advantage. Check their field first and attack with fewer monsters."}},{"card":"Kycoo the Ghost Destroyer","step":"main","stepText":{"es":"Boca arriba antes de tu Chaos Sorcerer o Black Luster Soldier.","en":"Face-up before your Chaos Sorcerer or Black Luster Soldier."},"loss":{"es":"Impide los destierros de Cementerio. Sacalo con Exiled Force o D.D. Warrior Lady antes de invocar Chaos.","en":"Prevents Graveyard banishing. Remove it with Exiled Force or D.D. Warrior Lady before summoning Chaos."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Sakuretsu Armor","qty":2,"why":{"es":"Yendo primero cubre los ataques de Warrior sin gastar monstruos.","en":"Going first it covers Warrior's attacks without spending monsters."}}],"out":[{"card":"Roulette Barrel","qty":1,"why":{"es":"Depende de dados y no suma si ya tenés tempo.","en":"Relies on dice and adds nothing when you already have tempo."}},{"card":"Dust Tornado","qty":1,"why":{"es":"Es la menos importante cuando no hay Royal Decree.","en":"The least important when there is no Royal Decree."}}]},"second":{"in":[{"card":"Smashing Ground","qty":1,"why":{"es":"Elimina un monstruo rival de DEF alta (Spy, Restrict).","en":"Removes a high DEF opposing monster (Spy, Restrict)."}},{"card":"Xing Zhen Hu","qty":1,"why":{"es":"Bloquea dos Magias o Trampas seteadas antes de la jugada.","en":"Locks two set Spells or Traps before the play."}}],"out":[{"card":"Roulette Barrel","qty":1,"why":{"es":"Poco útil si el rival no entra en el rango de niveles.","en":"Not useful if the opponent is outside the Level range."}},{"card":"Book of Moon","qty":1,"why":{"es":"Pierde valor si el plan es banishear y devolver.","en":"Loses value if the plan is to banish and return."}}]}},"updated":"2026-10-26"},"hat/artifact-traptrix":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Juega a responder: los Artifacts se Setean desde la mano como Magias y, si el rival los destruye en su turno, entran por Invocación Especial con su efecto (Moralltach destruye una carta boca arriba del rival).","en":"It plays to respond: Artifacts are Set from the hand as Spells and, if the opponent destroys them on their turn, they Special Summon with their effect (Moralltach destroys a face-up card the opponent controls)."},{"es":"Traptrix Myrmeleo busca una trampa Hole al invocarse por Normal y destruye una Magia/Trampa rival si entra por Invocación Especial; Dionaea revive un Traptrix y vuelve a Setear una Hole del Cementerio.","en":"Traptrix Myrmeleo searches a Hole Trap when Normal Summoned and destroys an opposing Spell/Trap if Special Summoned; Dionaea revives a Traptrix and re-Sets a Hole Trap from the Graveyard."},{"es":"Fire Hand e Ice Hand castigan que el rival los destruya: uno destruye un monstruo, el otro una Magia/Trampa, y cada uno trae a su par del Deck. Por eso el rival duda en atacarlos.","en":"Fire Hand and Ice Hand punish the opponent for destroying them: one destroys a monster, the other a Spell/Trap, and each brings out its partner from the Deck. That is why the opponent hesitates to attack them."},{"es":"Es lento y poco explosivo: aguanta bien a Lightsworn Ruler, pero arranca flojo contra un Geargia que juega a la defensiva. Cierra con Rank 5 (Artifact Durendal, Constellar Pleiades) o Number 103: Ragnazero.","en":"It is slow and not very explosive: it holds up well against Lightsworn Ruler but starts weak against a defensive Geargia. It closes with Rank 5 (Artifact Durendal, Constellar Pleiades) or Number 103: Ragnazero."}]},"starters":[{"cards":["Traptrix Myrmeleo"],"route":{"es":"Normal Summon de Myrmeleo: buscás Bottomless Trap Hole, Void Trap Hole o Traptrix Trap Hole Nightmare y dejás el campo cubierto de trampas.","en":"Normal Summon Myrmeleo: you search Bottomless Trap Hole, Void Trap Hole or Traptrix Trap Hole Nightmare and leave the field covered in Traps."}},{"cards":["Artifact Moralltach","Artifact Ignition"],"route":{"es":"Ignition (rápida) destruye tu propio Moralltach Seteado en el turno del rival: entra por Invocación Especial y destruye una carta boca arriba, y además Seteás otro Artifact del Deck.","en":"Ignition (Quick-Play) destroys your own Set Moralltach on the opponent's turn: it Special Summons and destroys a face-up card, and you also Set another Artifact from the Deck."}},{"cards":["Artifact Sanctum","Soul Charge"],"route":{"es":"Sanctum trae un Artifact del Deck y Soul Charge revive otro del Cementerio: dos monstruos de Nivel 5 LIGHT para Constellar Pleiades o Artifact Durendal (ninguna de las dos te deja pasar a Battle Phase).","en":"Sanctum brings out an Artifact from the Deck and Soul Charge revives another from the Graveyard: two Level 5 LIGHT monsters for Constellar Pleiades or Artifact Durendal (neither lets you go to the Battle Phase)."}}],"chokepoints":[{"card":"Royal Decree","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Anula los efectos de las demás Trampas: Sanctum, Call of the Haunted y las Hole no hacen nada. Se saca con Double Cyclone, Artifact Ignition o Myrmeleo invocado por Invocación Especial.","en":"Negates the effects of all other Traps: Sanctum, Call of the Haunted and the Hole Traps do nothing. Remove it with Double Cyclone, Artifact Ignition or a Special Summoned Myrmeleo."}},{"card":"Trap Stun","step":"resolution","stepText":{"es":"En respuesta a tu Trampa, antes de que se resuelva.","en":"In response to your Trap, before it resolves."},"loss":{"es":"Anula el efecto de tu Trampa y de las demás ese turno. Activá primero la menos importante para que gaste Trap Stun.","en":"Negates the effect of your Trap and every other Trap this turn. Activate the least important one first so they spend Trap Stun."}},{"card":"Skill Drain","step":"main","stepText":{"es":"Boca arriba antes de tu Main Phase.","en":"Face-up before your Main Phase."},"loss":{"es":"Anula Myrmeleo, las Hands y el destruir de Moralltach al entrar al campo. Sacalo con Double Cyclone o Artifact Ignition antes de jugar monstruos.","en":"Negates Myrmeleo, the Hands and Moralltach's destruction effect when it enters the field. Remove it with Double Cyclone or Artifact Ignition before playing monsters."}},{"card":"Black Horn of Heaven","step":"summon","stepText":{"es":"Cuando un Artifact entra por Invocación Especial en el turno del rival.","en":"When an Artifact Special Summons on the opponent's turn."},"loss":{"es":"Anula la invocación y destruye al Artifact antes de que dispare su efecto. Tené más de un Artifact Seteado para que no sea tu única jugada.","en":"Negates the Summon and destroys the Artifact before its effect triggers. Keep more than one Artifact Set so it is not your only play."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Myrmeleo.","en":"In your Main Phase, in response to Myrmeleo's effect."},"loss":{"es":"Anula el efecto y no buscás la Hole. Normal Summon de Myrmeleo solo cuando ya tengas otra jugada de reserva en la mano.","en":"Negates the effect and you do not search the Hole. Normal Summon Myrmeleo only when you already have another play in hand."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Black Horn of Heaven","qty":1,"why":{"es":"Frena la Invocación Especial clave del rival, que va segundo y tiene la mano completa.","en":"Stops the key Special Summon of the opponent, who goes second with a full hand."}}],"out":[{"card":"Dark Hole","qty":1,"why":{"es":"Sin monstruos que destruir en tu primer turno.","en":"No monsters to destroy on your first turn."}}]},"second":{"in":[{"card":"Debunk","qty":2,"why":{"es":"Anula efectos de monstruos activados desde la mano o el Cementerio (Dragon Rulers, Mermail) de un rival que ya armó campo.","en":"Negates monster effects activated from the hand or Graveyard (Dragon Rulers, Mermail) from an opponent who already built a board."}}],"out":[{"card":"Cardcar D","qty":2,"why":{"es":"Termina tu turno y no se invoca por Invocación Especial; yendo segundo necesitás la Battle Phase y los recursos para responder.","en":"It ends your turn and cannot be Special Summoned; going second you need the Battle Phase and resources to respond."}}]}},"updated":"2026-10-26"},"hat/mermail":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Todo gira alrededor de descartar monstruos WATER: Abyssteus (descarta 1) y Abyssmegalo (descarta 2) salen de la mano, y Abyssteus busca un Mermail de Nivel 4 o menos.","en":"Everything revolves around discarding WATER monsters: Abyssteus (discard 1) and Abyssmegalo (discard 2) come out of the hand, and Abyssteus searches a Level 4 or lower Mermail."},{"es":"El descarte dispara otros efectos: Abyssgunde revive un Mermail del Cementerio al ser descartado, y Atlantean Marksman o Heavy Infantry, mandados como coste, destruyen una carta Seteada o una boca arriba del rival.","en":"The discard triggers other effects: Abyssgunde revives a Mermail from the Graveyard when discarded, and Atlantean Marksman or Heavy Infantry, sent as a cost, destroy a Set card or a face-up card of the opponent."},{"es":"Soul Charge devuelve 2 o 3 monstruos de Nivel 7 del Cementerio para armar Mermail Abyssgaios (Rank 7) u otro Xyz que cierra la partida.","en":"Soul Charge brings back 2 or 3 Level 7 monsters from the Graveyard to build Mermail Abyssgaios (Rank 7) or another Xyz that finishes the game."},{"es":"Funciona bien en un formato lleno de trampas porque desgasta al rival hasta resolver Soul Charge o Abyssmegalo, pero depende del Cementerio y de tener WATER en la mano para pagar los descartes.","en":"It works well in a trap-heavy format because it grinds the opponent down until Soul Charge or Abyssmegalo resolves, but it depends on the Graveyard and on holding WATER monsters in hand to pay the discards."}]},"starters":[{"cards":["Mermail Abyssteus","Atlantean Marksman"],"route":{"es":"Descartás Marksman como coste de Abyssteus: destruye una carta Seteada del rival, y Abyssteus entra de la mano y busca otro Mermail de Nivel 4 o menos.","en":"Discard Marksman as Abyssteus's cost: it destroys a Set card of the opponent, and Abyssteus comes in from the hand and searches another Level 4 or lower Mermail."}},{"cards":["Mermail Abyssmegalo","Mermail Abyssgunde"],"route":{"es":"Abyssgunde descartado como coste de Megalo revive otro Mermail del Cementerio, y Megalo busca Abyss-sphere para seguir invocando Mermail del Deck.","en":"Abyssgunde discarded as Megalo's cost revives another Mermail from the Graveyard, and Megalo searches Abyss-sphere to keep summoning Mermail from the Deck."}},{"cards":["Soul Charge","Mermail Abyssteus"],"route":{"es":"Abyssteus de Nivel 7 queda en el Cementerio como descarte; Soul Charge lo trae de vuelta con otro Nivel 7 para Mermail Abyssgaios (cada monstruo invocado te cuesta 1000 LP).","en":"Level 7 Abyssteus sits in the Graveyard as a discard; Soul Charge brings it back with another Level 7 for Mermail Abyssgaios (each monster Summoned costs you 1000 LP)."}}],"chokepoints":[{"card":"Maxx \"C\"","step":"activation","stepText":{"es":"Antes de tu primera Invocación Especial, desde la mano.","en":"Before your first Special Summon, from the hand."},"loss":{"es":"Cada Invocación Especial le da una carta al rival, y Mermail hace muchas. Soul Charge invoca varios a la vez y cuenta como un solo robo.","en":"Each Special Summon gives the opponent a card, and Mermail makes many. Soul Charge summons several at once and counts as a single draw."}},{"card":"Black Horn of Heaven","step":"summon","stepText":{"es":"Cuando Abyssteus o Abyssmegalo se invoca de la mano.","en":"When Abyssteus or Abyssmegalo is summoned from the hand."},"loss":{"es":"Anula la invocación y la destruye con los descartes ya pagados. No frena Soul Charge si invocás 2 o más monstruos a la vez.","en":"Negates the Summon and destroys it with the discards already paid. It cannot stop Soul Charge if you summon 2 or more monsters at once."}},{"card":"Debunk","step":"activation","stepText":{"es":"Cuando activás el efecto de Abyssteus o Abyssmegalo desde la mano.","en":"When you activate Abyssteus's or Abyssmegalo's effect from the hand."},"loss":{"es":"Anula el efecto y destierra el monstruo; los descartes no vuelven. Abrí con un Mermail de menos valor para gastarle el Debunk.","en":"Negates the effect and banishes the monster; the discards do not come back. Open with a lower-value Mermail to bait the Debunk."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los monstruos mandados al Cementerio se destierran: Abyssgunde, Atlantean y Soul Charge dejan de funcionar. Se saca con Mystical Space Typhoon.","en":"Monsters sent to the Graveyard are banished: Abyssgunde, Atlantean and Soul Charge stop working. Remove it with Mystical Space Typhoon."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En respuesta a Soul Charge, con sus objetivos ya elegidos.","en":"In response to Soul Charge, with its targets already chosen."},"loss":{"es":"Destierra uno de los monstruos objetivo y Soul Charge trae uno menos. Apuntá a la mayor cantidad posible y repartí los Nivel 7 para no perderlo todo.","en":"Banishes one of the targeted monsters and Soul Charge brings back one fewer. Target as many as possible and spread out the Level 7s so you do not lose everything."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"El rival que va segundo invoca mucho en su turno: cada invocación te hace robar.","en":"The opponent going second summons a lot on their turn: each summon draws you a card."}}],"out":[{"card":"Forbidden Lance","qty":2,"why":{"es":"Sin Battle Phase en tu primer turno, solo sirve para proteger o ganar un combate.","en":"With no Battle Phase on your first turn, it only protects or wins a combat."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"En un formato de backrow pesado, abre las trampas Seteadas del rival que ya movió primero.","en":"In a backrow-heavy format, it opens the Set Traps of an opponent who already moved first."}}],"out":[{"card":"Upstart Goblin","qty":2,"why":{"es":"Le da 1000 LP al rival, y yendo segundo ya tenés un robo extra del primer turno.","en":"It gives the opponent 1000 LP, and going second you already have the extra draw of your first turn."}}]}},"updated":"2026-10-26"},"hat/geargia":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Mazo de desgaste y defensa: pone monstruos baratos en Defensa y trampas atrás (Fiendish Chain, Solemn Warning, Torrential Tribute) en lugar de atacar.","en":"A grinding, defensive deck: it puts cheap monsters in Defense and Traps behind them (Fiendish Chain, Solemn Warning, Torrential Tribute) instead of attacking."},{"es":"Geargiarmor se Setea y, al voltearse, busca otro Geargia; Geargiarsenal se tributa para invocar uno del Deck; Geargiaccelerator y Gear Gigant X recuperan Geargia del Cementerio.","en":"Geargiarmor is Set and, when flipped, searches another Geargia; Geargiarsenal Tributes itself to summon one from the Deck; Geargiaccelerator and Gear Gigant X recover Geargia from the Graveyard."},{"es":"Geargiagear es el cierre en la End Phase del rival: trae 2 Geargiano de Nivel 4 para armar Gear Gigant X, y al rival le cuesta responder.","en":"Geargiagear is the closer on the opponent's End Phase: it brings 2 Level 4 Geargiano to build Gear Gigant X, and the opponent struggles to answer."},{"es":"Arranca lento: le gana a casi todo el campo, pero pierde contra un Lightsworn Ruler explosivo, que destruye a Geargiarmor con Judgment Dragon o Lightray Diabolos.","en":"It starts slowly: it beats most of the field but loses to an explosive Lightsworn Ruler, which wrecks Geargiarmor with Judgment Dragon or Lightray Diabolos."}]},"starters":[{"cards":["Geargiano Mk-II","Geargiaccelerator"],"route":{"es":"Mk-II invoca a Geargiarmor (de la mano o el Cementerio) en Defensa y Geargiaccelerator entra de la mano: dos Nivel 4 Machine para Gear Gigant X.","en":"Mk-II summons Geargiarmor (from the hand or Graveyard) in Defense and Geargiaccelerator enters from the hand: two Level 4 Machines for Gear Gigant X."}},{"cards":["Geargiarmor"],"route":{"es":"Seteado en Defensa: cuando lo ataquen se voltea y busca otro Geargia del Deck, así que el rival no sabe si atacarlo.","en":"Set in Defense: when attacked it flips and searches another Geargia from the Deck, so the opponent does not know whether to attack it."}},{"cards":["Geargiagear"],"route":{"es":"Seteada y activada en la End Phase del rival: dos Geargiano de Nivel 4 que armás en Gear Gigant X en tu turno.","en":"Set and activated on the opponent's End Phase: two Level 4 Geargiano that you turn into Gear Gigant X on your turn."}}],"chokepoints":[{"card":"Judgment Dragon","step":"activation","stepText":{"es":"Al pagar 1000 LP para destruir todas las demás cartas.","en":"When paying 1000 LP to destroy all other cards."},"loss":{"es":"Barre tus trampas y monstruos de un solo efecto. Geargiaccelerator y Gear Gigant X recuperan Geargia del Cementerio al irse, así que conservá esos dos para reponer.","en":"Wipes your Traps and monsters with one effect. Geargiaccelerator and Gear Gigant X recover Geargia from the Graveyard when they leave, so keep those two to rebuild."}},{"card":"Lightray Diabolos","step":"activation","stepText":{"es":"En cualquier turno, apuntando a tu carta Seteada.","en":"On any turn, targeting your Set card."},"loss":{"es":"Manda al Deck una trampa o a Geargiarmor Seteados sin que se activen. No dependas de una sola carta Seteada para frenarlo.","en":"Sends a Set Trap or Geargiarmor to the Deck without it activating. Do not rely on a single Set card to stop it."}},{"card":"Nobleman of Crossout","step":"activation","stepText":{"es":"Contra Geargiarmor boca abajo, antes de que se voltee.","en":"Against a face-down Geargiarmor, before it flips."},"loss":{"es":"Lo destruye y lo destierra sin que busque nada. Jugá otro Geargia delante para que el rival no lo apunte primero.","en":"Destroys and banishes it without it searching anything. Play another Geargia in front so the opponent does not target it first."}},{"card":"Mind Crush","step":"resolution","stepText":{"es":"Al resolverse, nombrando Geargiaccelerator o Geargiano Mk-II.","en":"On resolution, naming Geargiaccelerator or Geargiano Mk-II."},"loss":{"es":"Descartás todas las copias de esa carta de la mano. Jugá primero la carta que más temés que nombren.","en":"You discard every copy of that card from your hand. Play first the card you fear they will name."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los monstruos que irían al Cementerio se destierran: Geargiaccelerator, Gear Gigant X y Geargiano Mk-II pierden su recursión. Sacalo con Mystical Space Typhoon.","en":"Monsters that would go to the Graveyard are banished: Geargiaccelerator, Gear Gigant X and Geargiano Mk-II lose their recursion. Remove it with Mystical Space Typhoon."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Black Horn of Heaven","qty":1,"why":{"es":"Frena la Invocación Especial clave del rival que va segundo.","en":"Stops the key Special Summon of the opponent going second."}},{"card":"Debunk","qty":1,"why":{"es":"Anula un efecto activado desde la mano o el Cementerio del rival.","en":"Negates an effect activated from the opponent's hand or Graveyard."}}],"out":[{"card":"Mind Control","qty":1,"why":{"es":"Sin monstruos rivales que robar en el primer turno.","en":"No opposing monsters to steal on the first turn."}},{"card":"Trap Stun","qty":1,"why":{"es":"Anula también tus propias Trampas (Fiendish Chain, Geargiagear) ese turno.","en":"It also negates your own Traps (Fiendish Chain, Geargiagear) that turn."}}]},"second":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"Contra Mermail, Lightsworn o Madolche, cada Invocación Especial que hagan en su turno te roba una carta.","en":"Against Mermail, Lightsworn or Madolche, each Special Summon they make on their turn draws you a card."}}],"out":[{"card":"Trap Stun","qty":1,"why":{"es":"Anula también tus propias Trampas (Fiendish Chain, Geargiagear) ese turno.","en":"It also negates your own Traps (Fiendish Chain, Geargiagear) that turn."}},{"card":"Needle Ceiling","qty":1,"why":{"es":"Destruye monstruos boca arriba con 4 o más en el campo, y vos solés armar ese campo.","en":"Destroys face-up monsters with 4 or more on the field, and you are often the one building that field."}}]}},"updated":"2026-10-26"},"hat/lightsworn-ruler":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Muele el Deck para llenar el Cementerio: Raiden manda 2 cartas por turno, Lumina 3 en la End Phase, Needlebug Nest manda 5 y Solar Recharge roba 2 y manda 2.","en":"It mills the Deck to fill the Graveyard: Raiden sends 2 cards per turn, Lumina 3 on the End Phase, Needlebug Nest sends 5 and Solar Recharge draws 2 and sends 2."},{"es":"Con el Cementerio lleno entra Judgment Dragon (4 Lightsworn distintos, destruye todo pagando 1000 LP) o Lightray Diabolos (5 LIGHT distintos, devuelve al Deck una carta Seteada).","en":"With the Graveyard loaded, Judgment Dragon comes in (4 different Lightsworn, destroys everything for 1000 LP) or Lightray Diabolos (5 different LIGHT, sends a Set card back to the Deck)."},{"es":"Raiden (Tuner Nivel 4) más Lumina arma a Michael, the Arch-Lightsworn (Nivel 7), que destierra una carta por 1000 LP; Eclipse Wyvern y los Dragon Rulers dan juego extra.","en":"Raiden (Level 4 Tuner) plus Lumina builds Michael, the Arch-Lightsworn (Level 7), which banishes a card for 1000 LP; Eclipse Wyvern and the Dragon Rulers add extra plays."},{"es":"Tiene un inicio frágil: sin Charge of the Light Brigade o Solar Recharge depende de moler en la End Phase, y un Breakthrough Skill o Fiendish Chain a tiempo lo frena.","en":"It has a fragile start: without Charge of the Light Brigade or Solar Recharge it depends on milling in the End Phase, and a well-timed Breakthrough Skill or Fiendish Chain slows it down."}]},"starters":[{"cards":["Lumina, Lightsworn Summoner","Raiden, Hand of the Lightsworn"],"route":{"es":"Lumina (Normal Summon) descarta una carta y revive a Raiden si ya estaba en el Cementerio; Raiden (4) más Lumina (3) hacen Michael de Nivel 7.","en":"Lumina (Normal Summon) discards a card and revives Raiden if it is already in the Graveyard; Raiden (4) plus Lumina (3) make Level 7 Michael."}},{"cards":["Charge of the Light Brigade","Solar Recharge"],"route":{"es":"Charge manda 3 cartas y busca un Lightsworn de Nivel 4 o menos; Solar Recharge descarta un Lightsworn para robar 2: dos jugadas que dejan listo a Judgment Dragon.","en":"Charge sends 3 cards and searches a Level 4 or lower Lightsworn; Solar Recharge discards a Lightsworn to draw 2: two plays that set up Judgment Dragon."}},{"cards":["Needlebug Nest"],"route":{"es":"La Seteás el primer turno y la activás en el turno del rival: 5 cartas al Cementerio para que Judgment Dragon o Diabolos entren en tu turno.","en":"Set it on turn 1 and activate it on the opponent's turn: 5 cards to the Graveyard so Judgment Dragon or Diabolos come in on your turn."}}],"chokepoints":[{"card":"Breakthrough Skill","step":"activation","stepText":{"es":"Contra Raiden o Lumina, en tu Main Phase.","en":"Against Raiden or Lumina, in your Main Phase."},"loss":{"es":"Anula su efecto de moler y cortás la acumulación del Cementerio. Si ves una trampa Seteada, jugá primero un Lightsworn de poco valor.","en":"Negates its milling effect and cuts the Graveyard build-up. If you see a Set Trap, play a low-value Lightsworn first."}},{"card":"Fiendish Chain","step":"activation","stepText":{"es":"Apuntando a Raiden o Lumina.","en":"Targeting Raiden or Lumina."},"loss":{"es":"Los deja anulados y sin atacar: quedás dependiendo de Needlebug Nest y Solar Recharge. Sacala con Mystical Space Typhoon o destruyendo al monstruo.","en":"Leaves them negated and unable to attack: you depend on Needlebug Nest and Solar Recharge. Remove it with Mystical Space Typhoon or by destroying the monster."}},{"card":"Chaos Trap Hole","step":"summon","stepText":{"es":"Cuando Judgment Dragon, Diabolos o Michael se invocan.","en":"When Judgment Dragon, Diabolos or Michael is summoned."},"loss":{"es":"Casi todo tu mazo es LIGHT o DARK: anula la invocación pagando 2000 LP y la destierra. Jugá cebos antes de tu carta clave.","en":"Almost your whole deck is LIGHT or DARK: it negates the Summon for 2000 LP and banishes it. Play bait before your key card."}},{"card":"Vanity's Emptiness","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Ninguno puede invocar de forma especial: Judgment Dragon, Diabolos, Michael y los Dragon Rulers quedan trabados. Tu molienda no la destruye, es del rival. Se saca con Mystical Space Typhoon o Lyla.","en":"Neither player can Special Summon: Judgment Dragon, Diabolos, Michael and the Dragon Rulers are locked out. Your own milling does not destroy it, it is the opponent's. Remove it with Mystical Space Typhoon or Lyla."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Lo molido se destierra y el Cementerio nunca se llena: Judgment Dragon, Diabolos y Soul Charge se apagan. Sacala con Mystical Space Typhoon o Lyla.","en":"Milled cards are banished and the Graveyard never fills: Judgment Dragon, Diabolos and Soul Charge shut off. Remove it with Mystical Space Typhoon or Lyla."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"El rival que va segundo invoca en su turno y cada Invocación Especial te hace robar.","en":"The opponent going second summons on their turn and each Special Summon makes you draw."}}],"out":[{"card":"Mind Control","qty":1,"why":{"es":"Sin monstruo rival que robar en tu primer turno.","en":"No opposing monster to steal on your first turn."}},{"card":"Forbidden Lance","qty":1,"why":{"es":"Sin Battle Phase en el primer turno, solo protege.","en":"With no Battle Phase on the first turn, it only protects."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"Contra backrow ya Seteada (Skill Drain, Fiendish Chain), abre el camino a Judgment Dragon.","en":"Against already Set backrow (Skill Drain, Fiendish Chain), it clears the way for Judgment Dragon."}}],"out":[{"card":"Honest","qty":1,"why":{"es":"Sirve para combate, y yendo segundo lo urgente es abrir el campo.","en":"It serves combat, and going second the priority is opening the field."}},{"card":"Rainbow Kuriboh","qty":1,"why":{"es":"Frena un ataque, pero tu plan es llenar el Cementerio, no defender.","en":"It stops an attack, but your plan is filling the Graveyard, not defending."}}]}},"updated":"2026-10-26"},"hat/madolche":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Los Madolche destruidos por una carta rival vuelven al Deck, y Madolche Ticket convierte cada regreso en otro Madolche a la mano (o invocado, si controlás un Madolche Hada boca arriba).","en":"Madolche destroyed by an opposing card go back to the Deck, and Madolche Ticket turns each return into another Madolche to hand (or summoned, if you control a face-up Fairy Madolche)."},{"es":"Anjelly se tributa para traer cualquier Madolche del Deck; Hootcake destierra un monstruo del Cementerio para hacer lo mismo y Messengelato busca una Magia/Trampa Madolche si controlás un Madolche Bestia boca arriba.","en":"Anjelly Tributes to bring any Madolche from the Deck; Hootcake banishes a monster from the Graveyard to do the same and Messengelato searches a Madolche Spell/Trap if you control a face-up Beast Madolche."},{"es":"Madolche Queen Tiaramisu (Rank 4) devuelve Madolche del Cementerio al Deck y mezcla tantas cartas del rival como Madolche devolviste.","en":"Madolche Queen Tiaramisu (Rank 4) returns Madolche from the Graveyard to the Deck and shuffles as many of the opponent's cards as Madolche you returned."},{"es":"Es lento y vive de la Normal Summon; en esta época se juega con las Hands, que castigan que el rival destruya sus monstruos. Si no hay material en el Cementerio, Hootcake no hace nada.","en":"It is slow and lives off the Normal Summon; in this era it is played with the Hands, which punish the opponent for destroying its monsters. If the Graveyard has no fodder, Hootcake does nothing."}]},"starters":[{"cards":["Madolche Anjelly"],"route":{"es":"Normal Summon de Anjelly: la tributás para traer un Madolche del Deck (indestructible en batalla), y el que sale se baraja de vuelta en la End Phase de tu siguiente turno.","en":"Normal Summon Anjelly: Tribute her to bring a Madolche from the Deck (indestructible by battle), and the one that comes out shuffles back on the End Phase of your next turn."}},{"cards":["Madolche Magileine"],"route":{"es":"Normal Summon de Magileine: buscás otro Madolche de la lista (Hootcake o Messengelato) para la jugada del turno siguiente.","en":"Normal Summon Magileine: you search another Madolche from your list (Hootcake or Messengelato) for the next turn's play."}},{"cards":["Madolche Hootcake","Madolche Messengelato"],"route":{"es":"Hootcake destierra un monstruo del Cementerio e invoca a Messengelato del Deck; Messengelato busca Madolche Chateau o Madolche Ticket mientras Hootcake siga boca arriba.","en":"Hootcake banishes a monster from the Graveyard and summons Messengelato from the Deck; Messengelato searches Madolche Chateau or Madolche Ticket while Hootcake stays face-up."}}],"chokepoints":[{"card":"Skill Drain","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Anula los efectos de los Madolche: los destruidos ya no se barajan, Magileine y Mewfeuille no buscan y Anjelly no trae a nadie. Se saca con Mystical Space Typhoon.","en":"Negates Madolche effects: destroyed ones no longer shuffle back, Magileine and Mewfeuille do not search and Anjelly brings nothing. Remove it with Mystical Space Typhoon."}},{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los Madolche destruidos se destierran en vez de barajarse, y Hootcake y Soul Charge no tienen material. Se saca con Mystical Space Typhoon.","en":"Destroyed Madolche are banished instead of shuffling back, and Hootcake and Soul Charge have no fodder. Remove it with Mystical Space Typhoon."}},{"card":"Mistake","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Nadie añade cartas del Deck a la mano: Magileine, Messengelato, Madolche Ticket y Reinforcement of the Army se anulan. Invocá con Anjelly y Hootcake, que traen al campo, o sacala con MST.","en":"Nobody adds cards from the Deck to the hand: Magileine, Messengelato, Madolche Ticket and Reinforcement of the Army are shut off. Summon with Anjelly and Hootcake, which bring monsters to the field, or remove it with MST."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Magileine.","en":"In your Main Phase, in response to Magileine's effect."},"loss":{"es":"Anula la búsqueda y perdés la Normal Summon del turno. Tené a Mewfeuille o Anjelly de reserva para reabrir la jugada.","en":"Negates the search and you lose the turn's Normal Summon. Keep Mewfeuille or Anjelly in reserve to reopen the play."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Black Horn of Heaven","qty":1,"why":{"es":"Frena la Invocación Especial clave del rival que va segundo.","en":"Stops the key Special Summon of the opponent going second."}}],"out":[{"card":"Mind Control","qty":1,"why":{"es":"Sin monstruo rival que robar el primer turno.","en":"No opposing monster to steal on the first turn."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"Contra backrow Seteada del rival, abre el camino para que tus Madolche no choquen con una trampa.","en":"Against the opponent's Set backrow, it opens the way so your Madolche do not run into a Trap."}}],"out":[{"card":"Photon Thrasher","qty":2,"why":{"es":"Solo entra con tu campo vacío, y querés armar un campo de Madolche.","en":"It only enters with your field empty, and you want to build a Madolche field."}}]}},"updated":"2026-10-26"},"hat/infernity":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Funciona con la mano vacía: Infernity Archfiend entra si la robás sin otras cartas en la mano y busca una carta Infernity; Infernity Break, Launcher y Barrier también piden mano vacía.","en":"It runs on an empty hand: Infernity Archfiend comes in if you draw it with no other cards in hand and searches an Infernity card; Infernity Break, Launcher and Barrier also require an empty hand."},{"es":"Para vaciar la mano usa Summoner Monk, Instant Fusion, Stygian Street Patrol, Tin Goldfish y Dynatherium, y arma Rank 3 y 4 como Lavalval Chain y Leviair the Sea Dragon.","en":"To empty the hand it uses Summoner Monk, Instant Fusion, Stygian Street Patrol, Tin Goldfish and Dynatherium, and builds Rank 3 and 4 like Lavalval Chain and Leviair the Sea Dragon."},{"es":"Leviair trae de vuelta a Stygian Street Patrol, que invoca a Infernity Archfiend de la mano; Lavalval Chain manda monstruos al Cementerio o pone uno arriba del Deck.","en":"Leviair brings back Stygian Street Patrol, which summons Infernity Archfiend from the hand; Lavalval Chain sends monsters to the Graveyard or puts one on top of the Deck."},{"es":"Tiene techo muy alto pero sin cartas en mano casi no tiene juego largo: si el rival le corta el arranque, no hay plan de desgaste.","en":"It has a very high ceiling but with no cards in hand it has almost no long game: if the opponent breaks the opening, there is no grinding plan."}]},"starters":[{"cards":["Stygian Street Patrol","Infernity Archfiend"],"route":{"es":"Stygian Street Patrol se destierra del Cementerio e invoca a Archfiend de la mano (1800 de ATK, entra bajo el límite de 2000); si queda la mano vacía, Archfiend busca una carta Infernity.","en":"Stygian Street Patrol banishes itself from the Graveyard and summons Archfiend from the hand (1800 ATK, under the 2000 limit); if the hand is empty, Archfiend searches an Infernity card."}},{"cards":["Summoner Monk","Instant Fusion"],"route":{"es":"Monk descarta una Magia e invoca un Nivel 4 del Deck; Instant Fusion (1000 LP) pone a Kamionwizard: dos Nivel 4 para Lavalval Chain.","en":"Monk discards a Spell and summons a Level 4 from the Deck; Instant Fusion (1000 LP) puts out Kamionwizard: two Level 4s for Lavalval Chain."}},{"cards":["Tin Goldfish","Dynatherium"],"route":{"es":"Tin Goldfish invoca otro Nivel 4 de la mano y Dynatherium entra gratis: dos Nivel 4 para Rank 4 sin gastar la mano en Magias (el rival puede revivir un Nivel 4 con Dynatherium).","en":"Tin Goldfish summons another Level 4 from the hand and Dynatherium enters for free: two Level 4s for a Rank 4 without spending your hand on Spells (the opponent can revive a Level 4 off Dynatherium)."}}],"chokepoints":[{"card":"Maxx \"C\"","step":"activation","stepText":{"es":"Antes de tu primera Invocación Especial.","en":"Before your first Special Summon."},"loss":{"es":"Cada Invocación Especial le da una carta al rival, y Infernity invoca mucho. Armá la jugada con pocos eventos de invocación: Soul Charge e Instant Fusion cuentan una sola vez cada uno.","en":"Each Special Summon gives the opponent a card, and Infernity summons a lot. Build the play with few summon events: Soul Charge and Instant Fusion count only once each."}},{"card":"Debunk","step":"activation","stepText":{"es":"Cuando Archfiend o Dark Grepher activan su efecto desde la mano.","en":"When Archfiend or Dark Grepher activate their effect from the hand."},"loss":{"es":"Anula el efecto y destierra la carta. Si tenés Stygian Street Patrol o Tin Goldfish, empezá por esos para no depender de un único Archfiend.","en":"Negates the effect and banishes the card. If you have Stygian Street Patrol or Tin Goldfish, start with those so you do not rely on a single Archfiend."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Archfiend.","en":"In your Main Phase, in response to Archfiend's effect."},"loss":{"es":"Anula la búsqueda de Infernity Break o Barrier. Tené otro monstruo de Nivel 4 en el campo para seguir con el Xyz.","en":"Negates the search for Infernity Break or Barrier. Keep another Level 4 monster on the field to continue into the Xyz."}},{"card":"Vanity's Emptiness","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Nadie invoca de forma especial: Archfiend, Stygian Street Patrol y los Xyz quedan bloqueados. Se saca con Mystical Space Typhoon.","en":"Nobody Special Summons: Archfiend, Stygian Street Patrol and the Xyz are locked out. Remove it with Mystical Space Typhoon."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Forbidden Chalice","qty":2,"why":{"es":"Carta rápida: se puede usar con la mano vacía para anular a un monstruo clave del rival.","en":"A Quick-Play: usable with an empty hand to negate a key monster of the opponent."}}],"out":[{"card":"Dynatherium","qty":1,"why":{"es":"Deja que el rival invoque un Nivel 4 de cualquier Cementerio.","en":"Lets the opponent summon a Level 4 from either Graveyard."}},{"card":"Photon Thrasher","qty":1,"why":{"es":"Solo entra con el campo vacío y no ataca con otro monstruo.","en":"It only enters with an empty field and cannot attack with another monster."}}]},"second":{"in":[{"card":"Night Beam","qty":3,"why":{"es":"Destruye una Magia/Trampa Seteada sin darle respuesta: el rival que fue primero tiene backrow.","en":"Destroys a Set Spell/Trap without giving a response: the opponent who went first has backrow."}}],"out":[{"card":"Vanity's Emptiness","qty":3,"why":{"es":"Bloquea también tus propias Invocaciones Especiales, que necesitás para romper el campo.","en":"It also blocks your own Special Summons, which you need to break the board."}}]}},"updated":"2026-10-26"},"hat/sylvan":{"win":{"plan":"combo","pace":"medium","bullets":[{"es":"Excavar es el motor: Marshalleaf, Komushroomo y Hermitree miran cartas del Deck, mandan los Plantas al Cementerio y disparan los efectos de 'cuando es excavado'.","en":"Excavating is the engine: Marshalleaf, Komushroomo and Hermitree look at cards from the Deck, send Plants to the Graveyard and trigger the 'when excavated' effects."},{"es":"Lo excavado pega: Marshalleaf destruye un monstruo, Komushroomo una Magia/Trampa y Sagequoia recupera una Magia/Trampa Sylvan; Sagequoia entra de la mano cuando un Sylvan va al Cementerio.","en":"What you excavate hits: Marshalleaf destroys a monster, Komushroomo a Spell/Trap and Sagequoia recovers a Sylvan Spell/Trap; Sagequoia enters from the hand when a Sylvan goes to the Graveyard."},{"es":"Soul Charge y Miracle Fertilizer ponen cuerpos de Nivel 7 u 8 para Orea, Alsei o Divine Dragon Knight Felgrand, que cierran la partida.","en":"Soul Charge and Miracle Fertilizer put out Level 7 or 8 bodies for Orea, Alsei or Divine Dragon Knight Felgrand, which close the game."},{"es":"Pide una sexta carta para arrancar y es difícil de jugar bien; Divine Wrath (descartá una carta para anular un efecto de monstruo) cubre el hueco cuando el rival la interrumpe.","en":"It needs a sixth card to get going and is hard to play well; Divine Wrath (discard a card to negate a monster effect) covers the gap when the opponent interrupts it."}]},"starters":[{"cards":["Sylvan Marshalleaf"],"route":{"es":"Normal Summon de Marshalleaf: excavás 1 o 2 cartas, mandás los Plantas al Cementerio y, si una es Sylvan, empieza la cadena de efectos.","en":"Normal Summon Marshalleaf: excavate 1 or 2 cards, send the Plants to the Graveyard and, if one is Sylvan, the chain of effects begins."}},{"cards":["Sylvan Komushroomo"],"route":{"es":"Seteado el primer turno: al voltearse excavás de 1 a 5 cartas y dejás cargado el Cementerio de Plantas.","en":"Set on the first turn: when flipped you excavate 1 to 5 cards and load the Graveyard with Plants."}},{"cards":["Sylvan Hermitree","Miracle Fertilizer"],"route":{"es":"Hermitree en el Cementerio vuelve con Miracle Fertilizer y excava cada turno: si es Planta va al Cementerio y robás una carta.","en":"Hermitree in the Graveyard returns with Miracle Fertilizer and excavates every turn: if it is a Plant it goes to the Graveyard and you draw a card."}}],"chokepoints":[{"card":"Dimensional Fissure","step":"main","stepText":{"es":"Boca arriba antes de tu turno.","en":"Face-up before your turn."},"loss":{"es":"Los Plantas excavados se destierran en vez de ir al Cementerio, así que no se dispara ningún efecto de 'cuando es excavado'. Sacala con Mystical Space Typhoon.","en":"Excavated Plants are banished instead of going to the Graveyard, so no 'when excavated' effect triggers. Remove it with Mystical Space Typhoon."}},{"card":"D.D. Crow","step":"activation","stepText":{"es":"En respuesta a Miracle Fertilizer, apuntando a la Planta.","en":"In response to Miracle Fertilizer, targeting the Plant."},"loss":{"es":"Destierra el objetivo y la revivida queda sin nada. Tené otro Planta en el Cementerio como alternativa.","en":"Banishes the target and the revival is left with nothing. Keep another Plant in the Graveyard as an alternative."}},{"card":"Black Horn of Heaven","step":"summon","stepText":{"es":"Cuando Sagequoia entra de la mano.","en":"When Sagequoia enters from the hand."},"loss":{"es":"Anula la invocación y la destruye. Soul Charge con 2 o más monstruos no se puede frenar con ella.","en":"Negates the Summon and destroys it. Soul Charge with 2 or more monsters cannot be stopped by it."}},{"card":"Effect Veiler","step":"activation","stepText":{"es":"En tu Main Phase, en respuesta al efecto de Hermitree o Marshalleaf.","en":"In your Main Phase, in response to Hermitree's or Marshalleaf's effect."},"loss":{"es":"Anula la excavación del turno. Reservá Komushroomo Seteado para el turno siguiente.","en":"Negates the turn's excavation. Save a Set Komushroomo for the next turn."}}],"side":{"basis":"editorial","first":{"in":[{"card":"Maxx \"C\"","qty":2,"why":{"es":"Penaliza las Invocaciones Especiales del rival en su turno; Super Solar Nutrient y Cherubsprout solo suman si la jugada sale entera.","en":"Penalizes the opponent's Special Summons on their turn; Super Solar Nutrient and Cherubsprout only add value if the full play comes together."}}],"out":[{"card":"Super Solar Nutrient","qty":1,"why":{"es":"Pide un Planta de Nivel 2 o menos para tributar, un requisito que no siempre tenés.","en":"It needs a Level 2 or lower Plant to Tribute, a requirement you do not always have."}},{"card":"Sylvan Cherubsprout","qty":1,"why":{"es":"Solo suma con una excavación específica.","en":"It only adds value with a specific excavation."}}]},"second":{"in":[{"card":"Mystical Space Typhoon","qty":2,"why":{"es":"Contra backrow Seteada, protege a Hermitree y al resto de la excavación.","en":"Against Set backrow, it protects Hermitree and the rest of the excavation."}}],"out":[{"card":"Spore","qty":1,"why":{"es":"Solo se puede usar una vez por Duelo y depende de otro Planta en el Cementerio.","en":"It can only be used once per Duel and depends on another Plant in the Graveyard."}},{"card":"Terraforming","qty":1,"why":{"es":"Ya tenés 2 Mount Sylvania para buscar; la tercera búsqueda no hace falta.","en":"You already have 2 Mount Sylvania to search; a third search is not needed."}}]}},"updated":"2026-10-26"},"ocg/elfnote":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Arma una mesa de interrupciones a base de Sincros: Elfnote Power Patron sube 3 niveles al monstruo de la zona central y sincroniza en el acto, y los Elfnote de nivel 6 se mueven a esa zona.","en":"Builds an interruption board through Synchros: Elfnote Power Patron raises the center-zone monster by 3 Levels and Synchro Summons right away, and Level 6 Elfnotes move into that zone."},{"es":"En el turno rival los Elfnote se cambian de lugar con el monstruo central: Lucina devuelve un monstruo de nivel 6 o menos a la mano, Tinia destierra una carta al azar de la mano rival y Fortuna devuelve un Mágica/Trampa boca arriba.","en":"On the opponent's turn Elfnotes swap with the center monster: Lucina returns a Level 6 or lower monster to the hand, Tinia banishes a random card from the opponent's hand and Fortuna returns a face-up Spell/Trap."},{"es":"Las cartas Ars Magna suman remoción: Ars Magna the Finite and the Infinite destierra un monstruo si controlás un Link Power Patron, y Mediclius (con 3 enlaces) se destierra con todo el campo rival como efecto rápido.","en":"Ars Magna cards add removal: Ars Magna the Finite and the Infinite banishes a monster if you control a Power Patron Link, and Mediclius (pointing to 3) banishes itself and the opponent's whole field as a Quick Effect."},{"es":"Los reportes de torneo OCG de 2026 lo ubican segundo mazo más jugado, con una jugada larga que termina en Baronne de Fleur, Artmage Diactorus y Rhapsodia of Madness.","en":"OCG 2026 tournament reports place it as the second most played deck, with a long line ending on Baronne de Fleur, Artmage Diactorus and Rhapsodia of Madness."}]},"starters":[{"cards":["Elfnote Lucina","Elfnote Power Patron"],"route":{"es":"Lucina entra a la zona central desde la mano y busca a Power Patron; este sube su nivel 3 y sincroniza (Baronne de Fleur u otro Elfnote Sincro).","en":"Lucina Special Summons to the center zone from hand and adds Power Patron; it raises her Level by 3 and Synchro Summons (Baronne de Fleur or another Elfnote Synchro)."}},{"cards":["Theorealize Past Lull","Medius the Pure"],"route":{"es":"Past Lull invoca a Medius the Pure desde la mano o el Deck sin que el rival pueda responder; Medius busca o invoca un monstruo Power Patron.","en":"Past Lull Special Summons Medius the Pure from hand or Deck and the opponent cannot respond; Medius adds or Special Summons a Power Patron monster."}},{"cards":["Elfnotes: Welcome Home"],"route":{"es":"Manda un monstruo al Cementerio e invoca de Defensa un Elfnote de otro Atributo desde el Deck, y protege de destrucción por efecto al monstruo central.","en":"Sends a monster to the GY and Special Summons an Elfnote of a different Attribute from the Deck in Defense Position, and protects the center monster from effect destruction."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Al activar la búsqueda de Lucina, de Medius the Pure o la invocación desde el Deck de Regina.","en":"When Lucina's search, Medius the Pure's add or Regina's Deck Special Summon is activated."},"loss":{"es":"Sin la búsqueda de Lucina no llega Power Patron y se corta la ruta de Sincros. Conviene empezar por la carta que menos duele perder.","en":"Without Lucina's search Power Patron never arrives and the Synchro route is cut. Start with the card you mind losing least."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación de la jugada.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"La línea invoca muchos monstruos y Nibiru tributa todo el campo. Una fuente de la comunidad (YGOrganization) lo cubre con Crystal Wing Synchro Dragon en el final de la jugada.","en":"The line Summons many monsters and Nibiru Tributes the whole field. A YGOrganization deck profile covers it with Crystal Wing Synchro Dragon at the end of the line."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno (Lucina, Medius o el Sincro Power Patron).","en":"On resolution of the first search of the turn (Lucina, Medius or the Power Patron Synchro)."},"loss":{"es":"No frena la primera carta, pero corta el resto de las búsquedas del turno: queda sin los Elfnote y Ars Magna que buscaba después.","en":"It does not stop the first card, but cuts every later search that turn: you lose the Elfnotes and Ars Magna cards you wanted next."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto rápido de Elfnote Power Patron (subir nivel y sincronizar).","en":"When Elfnote Power Patron's Quick Effect (raise Level and Synchro Summon) is activated."},"loss":{"es":"Si se niega, no sube el nivel y no hay Sincro: se pierde el paso clave. Guardá un segundo camino (Seraphim Strelitzia o Regina) para la mano que se queda sin esa activación.","en":"If negated, the Level never rises and there is no Synchro: the key step is lost. Keep a second route (Seraphim Strelitzia or Regina) for hands that lose that activation."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o la activación que invoca, así protege la mesa cuando el rival juega segundo.","en":"Negates the Summon or an activation that Special Summons, so it protects the board when the opponent goes second."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Solo se activa si no controlás cartas: yendo primero, con mesa armada queda muerta.","en":"Only activates if you control no cards: going first, with a board up, it is dead."}}]},"second":{"in":[{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Corta de raíz la jugada rival cuando junta cinco invocaciones.","en":"Ends the opponent's line the moment they reach five Summons."}},{"card":"Triple Tactics Talent","qty":1,"why":{"es":"Se activa si el rival usó un efecto de monstruo en tu Main Phase: roba 2 o roba el monstruo.","en":"Activates if the opponent used a monster effect in your Main Phase: draw 2 or take the monster."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a una búsqueda del rival; yendo segundo ya jugó casi todo.","en":"It reacts to an opponent search; going second they have already played most of it."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de que el rival arme su mesa que después.","en":"Worth more before the opponent builds the board than after."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/raise-moon":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Juega con el robo: casi todos los monstruos son de nivel 7 y al robarlos se muestran y se invocan solos, así que cada robo extra es una jugada. No hay búsquedas en el tema.","en":"It plays off drawing: almost every monster is Level 7 and is revealed and Special Summoned when drawn, so each extra draw is a play. The theme has no searches."},{"es":"Blade Shayna manda un monstruo rival al fondo del Deck y Lamp Croucier hace lo mismo con un Mágica/Trampa, ambos al entrar por robo.","en":"Blade Shayna sends an opposing monster to the bottom of the Deck and Lamp Croucier does the same to a Spell/Trap, both when they come out by a draw."},{"es":"Cierra con Xyz de rango 7: Cielo No More Bets en la Zona de Monstruos Extra es inmune a otros efectos y convierte las búsquedas rivales en un robo.","en":"It finishes with Rank 7 Xyz: Cielo No More Bets in the Extra Monster Zone is unaffected by other effects and turns opposing searches into a draw."},{"es":"Las notas de jugadores lo describen como control y recomiendan ir segundo; con la mano baja y bajo ATK/DEF le cuesta pelear contra monstruos grandes.","en":"Player notes describe it as control and recommend going second; with low ATK/DEF it struggles to fight big monsters."}]},"starters":[{"cards":["Cielo, the Veil of Raise Moon"],"route":{"es":"Se invoca desde la mano mandando otra carta al fondo del Deck y roba 1 como efecto rápido: es la mejor carta para dejar en el campo final.","en":"Special Summons from hand by putting another card on the bottom of the Deck and draws 1 as a Quick Effect: the best draw engine to leave on the final board."}},{"cards":["The Stars of Raise Moon","Pot of Desires"],"route":{"es":"Stars deja un Raise Moon arriba del Deck y Pot of Desires roba 2: al robarlo entra solo y sigue la cadena de robos.","en":"Stars puts a Raise Moon on top of the Deck and Pot of Desires draws 2: it is Special Summoned on the draw and the chain of draws continues."}},{"cards":["The Glitter of Raise Moon"],"route":{"es":"Trampa que invoca de Especial un Xyz Raise Moon (Cielo No More Bets o Jackpot) y se adjunta a él; es lenta si vas segundo sin materiales.","en":"Trap that Special Summons a Raise Moon Xyz (Cielo No More Bets or Jackpot) and attaches itself to it; it is slow going second without setup."}}],"chokepoints":[{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de Blade Shayna o Lamp Croucier tras entrar por robo.","en":"When Blade Shayna's or Lamp Croucier's effect is activated after coming out by a draw."},"loss":{"es":"Niega la remoción al fondo del Deck y te deja un cuerpo de 2800 de ATK sin efecto. Seguí con los robos: el siguiente Raise Moon vuelve a tener efecto.","en":"It negates the bottom-of-Deck removal and leaves a 2800 ATK body with no effect. Keep drawing: the next Raise Moon has its effect again."}},{"card":"Dominus Impulse","step":"summon","stepText":{"es":"Al activarse el \"al robar esta carta, invocala\" de cualquier Raise Moon.","en":"When any Raise Moon's \"when you draw this card, Special Summon it\" is activated."},"loss":{"es":"Anula la invocación por robo, que es el motor del mazo. La carta queda en la mano para pagar el efecto de Cielo o descartarse.","en":"It negates the draw Summon, which is the deck's engine. The card stays in hand to pay for Cielo's effect or be discarded."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Contra \"Raise Moon\" the City that Never Sleeps o The Glitter of Raise Moon cuando mandan o devuelven cartas del Cementerio.","en":"Against \"Raise Moon\" the City that Never Sleeps or The Glitter of Raise Moon when they shuffle or return cards from the GY."},"loss":{"es":"City baraja los Raise Moon del Cementerio y el destierro al Deck en la End Phase; negar esa activación deja el Deck sin reciclarse.","en":"City shuffles Raise Moon cards from the GY and banishment into the Deck in the End Phase; negating that activation leaves the Deck unrecycled."}}],"side":{"first":{"in":[{"card":"Mistaken Arrest","qty":2,"why":{"es":"Nadie añade cartas del Deck a la mano por un turno; a Raise Moon no le cuesta nada porque no busca.","en":"Nobody adds cards from the Deck to the hand for a turn; it costs Raise Moon nothing because it never searches."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Deja pasar la primera búsqueda; Mistaken Arrest las corta todas.","en":"It lets the first search through; Mistaken Arrest stops them all."}},{"card":"Effect Veiler","qty":1,"why":{"es":"Una sola negación de monstruo, redundante con las demás reactivas.","en":"A single monster negation, redundant with the other reactive cards."}}]},"second":{"in":[{"card":"Ghost Belle & Haunted Mansion","qty":2,"why":{"es":"Contra mazos que reviven del Cementerio, niega la activación completa.","en":"Against decks that revive from the GY, it negates the whole activation."}}],"out":[{"card":"Ghost Ogre & Snow Rabbit","qty":2,"why":{"es":"Solo destruye; Belle corta efectos de Cementerio que Ogre no frena.","en":"It only destroys; Belle stops GY effects that Ogre cannot."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/chaos-ritual":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"La jugada clave es el primer Ritual del Caos: Black Luster Soldier o Magician of Dark Chaos, invocados con Light and Darkness Ritual.","en":"The key play is the first Chaos Ritual Summon: Black Luster Soldier or Magician of Dark Chaos, Ritual Summoned with Light and Darkness Ritual."},{"es":"Ambos son inmunes a efectos activados del rival que no los apunten, y al invocarse destierran una carta (BLS) o una boca abajo (Magician of Dark Chaos).","en":"Both are unaffected by the opponent's activated effects that do not target them, and banish a card (BLS) or one face-down (Magician of Dark Chaos) when Special Summoned."},{"es":"Black Chaos (nivel 8) destierra 2 cartas rivales cada Main Phase y es inmune a efectos activados mientras tengas un Ritual Spell en el Cementerio.","en":"Black Chaos (Level 8) banishes 2 opposing cards each Main Phase and is unaffected by activated effects while you have a Ritual Spell in the GY."},{"es":"Dark Time Wizard busca o, tirando la moneda, destruye todos los monstruos rivales; sirve como pivote cuando la mesa del rival estorba.","en":"Dark Time Wizard searches or, on a coin toss, destroys every opposing monster; it is the pivot when the opposing board is in the way."}]},"starters":[{"cards":["Griffoh","Mind Shuffle"],"route":{"es":"Griffoh descartado pone Mind Shuffle desde el Deck; este agrega Skull Archfiend of Chaos, que mandado al Cementerio busca el Ritual que pida un Ritual Spell.","en":"Discarded Griffoh Sets Mind Shuffle from the Deck; it adds Skull Archfiend of Chaos, which sent to the GY adds the Ritual Monster named on a Ritual Spell."}},{"cards":["Ragged Records of Rites","Light and Darkness Ritual"],"route":{"es":"Records revela Light and Darkness Ritual y agrega el monstruo que lo menciona; con eso se hace el Ritual en el mismo turno.","en":"Records reveals Light and Darkness Ritual and adds a monster that mentions it, giving a same-turn Ritual Summon."}},{"cards":["Celtic Mystic"],"route":{"es":"Si mostrás en la mano una carta que mencione Light and Darkness Ritual, robás 3 y descartás 2; también se tributa para invocar un Ritual desde la mano.","en":"If you reveal a card in hand that mentions Light and Darkness Ritual, you draw 3 and discard 2; it can also be Tributed to Special Summon a Ritual from hand."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Ragged Records of Rites, Pre-Preparation of Rites o la búsqueda de Skull Archfiend.","en":"Against Ragged Records of Rites, Pre-Preparation of Rites or Skull Archfiend's search."},"loss":{"es":"Corta la búsqueda del Ritual o del monstruo. Por eso Griffoh y Mind Shuffle son la ruta alternativa: no dependen de una sola carta.","en":"It cuts the Ritual or monster search. That is why Griffoh and Mind Shuffle are the alternative route: they do not hang on one card."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno (Records, Pre-Preparation o Celtic Mystic).","en":"On resolution of the first search of the turn (Records, Pre-Preparation or Celtic Mystic)."},"loss":{"es":"Lo que se buscó llega, pero no podés buscar más ese turno. Armá la mano pensando en que tras la primera búsqueda no hay segunda.","en":"What you searched arrives, but you cannot search again that turn. Plan the hand as if there is no second search after the first."}},{"card":"Maxx \"C\"","step":"main","stepText":{"es":"En la Main Phase, cada vez que invocás de Especial (Skull Archfiend, Black Chaos, el Ritual).","en":"In the Main Phase, each time you Special Summon (Skull Archfiend, Black Chaos, the Ritual)."},"loss":{"es":"El rival roba una carta por invocación; el mazo hace pocas invocaciones por turno, así que lo aguanta mejor que otros, pero regala recursos.","en":"The opponent draws a card per Summon; the deck makes few Summons per turn, so it handles it better than most, but it gives resources away."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de desterrar de Black Chaos o del Ritual (BLS y Magician of Dark Chaos).","en":"When the banish effect of Black Chaos or the Ritual (BLS or Magician of Dark Chaos) is activated."},"loss":{"es":"Niega la remoción y te deja un monstruo grande sin efecto. Si lo ves venir, activá primero el efecto que menos te importa.","en":"It negates the removal and leaves you a big monster without its effect. If you see it coming, activate the effect you care least about first."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o activación que invoca: protege contra el combo rival de segundo turno.","en":"Negates the Summon or activation that Special Summons: protects against the opponent's second-turn combo."}}],"out":[{"card":"Mulcharmy Purulia","qty":1,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero queda muerta.","en":"Only activates with no cards on your field; going first it is dead."}},{"card":"Mulcharmy Fuwalos","qty":1,"why":{"es":"Misma restricción: no se activa con mesa armada.","en":"Same restriction: it does not activate with a board."}}]},"second":{"in":[{"card":"Pot of Sloth","qty":2,"why":{"es":"Robás tantas cartas como cartas controle el rival y devolvés al fondo todas menos 1: sirve contra una mesa ya armada.","en":"Draw as many cards as the opponent controls and put all but 1 on the bottom: useful against an already built board."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo el rival ya jugó su turno.","en":"Reacts to opposing searches; going second the opponent has already taken their turn."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opponent's line than after."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/mitsurugi-chaos-ritual":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Mezcla dos motores Ritual: el de Mitsurugi (Rituales Reptil de nivel 8 que se tributan entre sí y buscan cartas) y el del Caos (Black Chaos, BLS, Magician of Dark Chaos con Light and Darkness Ritual).","en":"It mixes two Ritual engines: Mitsurugi (Level 8 Reptile Rituals that Tribute each other and search) and Chaos (Black Chaos, BLS, Magician of Dark Chaos with Light and Darkness Ritual)."},{"es":"Ame no Habakiri no Mitsurugi es el arranque: se revela desde la mano para invocar a otro Mitsurugi del Deck y tributar uno, y una vez tributado se invoca de vuelta.","en":"Ame no Habakiri no Mitsurugi starts it: revealed from hand it Special Summons another Mitsurugi from the Deck and Tributes one, and once Tributed it Special Summons itself back."},{"es":"El final suele incluir a Ame no Murakumo no Mitsurugi (destruye monstruos al invocarse y niega o hace descartar como efecto rápido) y una Mitsurugi Great Purification boca abajo.","en":"The end board usually includes Ame no Murakumo no Mitsurugi (destroys monsters when Special Summoned and negates or forces a discard as a Quick Effect) and a Set Mitsurugi Great Purification."},{"es":"Un artículo de YGOrganization marca el primer Ritual del Caos como el turno clave; a partir de ahí el motor Mitsurugi toma el control del turno.","en":"A YGOrganization article marks the first Chaos Ritual Summon as the key turn; after that the Mitsurugi engine takes over the turn."}]},"starters":[{"cards":["Ame no Habakiri no Mitsurugi"],"route":{"es":"Revelás la carta, invocás a Saji o a otro Mitsurugi del Deck y lo tributás; Saji busca Mitsurugi Ritual y la cadena de Rituales arranca sola. Solo una vez por Duelo.","en":"Reveal it, Special Summon Saji or another Mitsurugi from the Deck and Tribute it; Saji adds Mitsurugi Ritual and the Ritual chain starts. Once per Duel only."}},{"cards":["Griffoh","Mind Shuffle"],"route":{"es":"Griffoh descartado pone Mind Shuffle, que agrega Skull Archfiend of Chaos; este, mandado al Cementerio, busca el Ritual que pida un Ritual Spell.","en":"Discarded Griffoh Sets Mind Shuffle, which adds Skull Archfiend of Chaos; sent to the GY it adds the Ritual Monster named on a Ritual Spell."}},{"cards":["Mitsurugi no Mikoto, Saji","Mitsurugi Ritual"],"route":{"es":"Saji busca Mitsurugi Ritual; con ella invocás de Ritual un Reptil de nivel 8 del Deck tributando Reptiles.","en":"Saji adds Mitsurugi Ritual; with it you Ritual Summon a Level 8 Reptile from the Deck by Tributing Reptiles."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra la búsqueda de Saji, Aramasa, Pre-Preparation of Rites o Ragged Records of Rites.","en":"Against the search of Saji, Aramasa, Pre-Preparation of Rites or Ragged Records of Rites."},"loss":{"es":"Sin Mitsurugi Ritual en mano la cadena no arranca. Tener Ritual de respaldo (Mitsurugi Mirror o Light and Darkness Ritual) es lo que te salva.","en":"Without Mitsurugi Ritual in hand the chain does not start. Having a backup Ritual (Mitsurugi Mirror or Light and Darkness Ritual) is what saves you."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación de la jugada.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"Los Rituales se invocan y se tributan una y otra vez, así que se llega rápido a cinco invocaciones; Nibiru tributa toda la mesa.","en":"Rituals are Summoned and Tributed again and again, so five Summons arrive quickly; Nibiru Tributes the whole board."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno.","en":"On resolution of the first search of the turn."},"loss":{"es":"Después del primer Mitsurugi Ritual o Mikoto buscado ya no podés agregar más: las respuestas de Aramasa y Kusanagi se quedan sin efecto de búsqueda.","en":"After the first Mitsurugi Ritual or Mikoto is added you cannot add more: Aramasa's and Kusanagi's add effects do nothing."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Contra el efecto de Habakiri (u otro Mitsurugi) que se invoca de vuelta desde el Cementerio al ser tributado.","en":"Against the effect of Habakiri (or another Mitsurugi) that Special Summons itself back from the GY when Tributed."},"loss":{"es":"El bucle depende de revivir Rituales; negar esa activación corta la recursión y deja la mesa corta.","en":"The loop depends on reviving Rituals; negating that activation cuts the recursion and leaves a short board."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de destruir monstruos de Ame no Murakumo no Mitsurugi.","en":"When the destroy-monsters effect of Ame no Murakumo no Mitsurugi is activated."},"loss":{"es":"Se pierde la limpieza del campo rival. Murakumo sigue siendo un cuerpo de 3200 de ATK, pero sin el barrido.","en":"The clear of the opposing field is lost. Murakumo is still a 3200 ATK body, but without the sweep."}}],"side":{"first":{"in":[{"card":"Solemn Judgment","qty":1,"why":{"es":"Anula una invocación o activación pagando la mitad de los LP; protege el combo rival de segundo turno.","en":"Negates a Summon or activation by paying half your LP; protects against the opponent's second-turn combo."}},{"card":"Nibiru, the Primal Being","qty":1,"why":{"es":"Corta el combo del rival cuando junta cinco invocaciones.","en":"Ends the opponent's combo once they reach five Summons."}}],"out":[{"card":"Mulcharmy Purulia","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero con mesa queda muerta.","en":"Only activates with no cards on your field; going first with a board it is dead."}}]},"second":{"in":[{"card":"Hey, Space Trunade!","qty":1,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano: útil contra una mesa ya armada.","en":"Returns up to 2 cards from the field to the hand: useful against an already built board."}},{"card":"Ghost Ogre & Snow Rabbit","qty":1,"why":{"es":"Destruye un monstruo que activa su efecto en el campo, buena contra bosses rivales.","en":"Destroys a monster that activates its effect on the field, good against opposing bosses."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/sacred-beast":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Fallen Paradise of the Sacred Beasts manda 3 cartas del mismo tipo al Cementerio e invoca una Sacred Beast desde la mano, el Deck, el Cementerio o el destierro, inmune a Mágicas/Trampas activadas del rival.","en":"Fallen Paradise of the Sacred Beasts sends 3 cards of the same type to the GY and Special Summons a Sacred Beast from hand, Deck, GY or banishment, unaffected by the opponent's activated Spells/Traps."},{"es":"Raviel tributa 2 Sacred Beast para destruir todos los monstruos rivales y gana 1000 de ATK por cada uno; Hamon inflige 1000 de daño cuando un monstruo rival va al Cementerio.","en":"Raviel Tributes 2 Sacred Beasts to destroy all opposing monsters and gains 1000 ATK for each; Hamon deals 1000 damage when an opposing monster goes to the GY."},{"es":"Con una Bestia de nivel 10 en campo, Fallen Paradise te da un robo de 2 por turno, y Sacred Beasts Released agrega 3 Bestias distintas descartando 2.","en":"With a Level 10 Beast on the field, Fallen Paradise draws 2 per turn, and Sacred Beasts Released adds 3 different Beasts for 2 discards."},{"es":"Las guías de la comunidad señalan que el mazo casi no tiene protección fuera de Fallen Paradise y que rinde mejor yendo segundo.","en":"Community guides note the deck has almost no protection beyond Fallen Paradise and plays better going second."}]},"starters":[{"cards":["Martyr of the Sacred Beasts"],"route":{"es":"Al entrar pone un Field Spell o un Continuo Sacred Beast del Deck (Fallen Paradise); con otra Bestia en campo invoca 2 Martyr más.","en":"On Summon it places a Sacred Beast Field Spell or Continuous Spell/Trap from the Deck (Fallen Paradise); with another Beast on the field it Special Summons 2 more Martyrs."}},{"cards":["Sacred Beasts Released"],"route":{"es":"Agrega 3 Sacred Beast distintas del Deck y descarta 2 cartas; deja la mano lista para Fallen Paradise.","en":"Adds 3 different Sacred Beasts from the Deck and discards 2 cards; it sets the hand up for Fallen Paradise."}},{"cards":["Sacred Beasts Thunderclap","Fallen Paradise of the Sacred Beasts"],"route":{"es":"Thunderclap pone 2 copias más boca arriba y, mostrando una Bestia de nivel 10, coloca Fallen Paradise del Deck en la Zona de Campo.","en":"Thunderclap places 2 more copies face-up and, revealing a Level 10 Beast, places Fallen Paradise from the Deck in the Field Zone."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Sacred Beasts Released o contra la invocación desde el Deck de Fallen Paradise.","en":"Against Sacred Beasts Released or Fallen Paradise's Special Summon from the Deck."},"loss":{"es":"Sin la búsqueda o la invocación, la mano queda sin bosses. Guardá el segundo camino (Summoner of the Sacred Beasts o una Bestia revelada) para esos turnos.","en":"Without the search or the Summon, the hand has no bosses. Keep a second route (Summoner of the Sacred Beasts or a revealed Beast) for those turns."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de Raviel, después de pagar los 2 tributos.","en":"When Raviel's effect is activated, after the 2 Tributes are paid."},"loss":{"es":"Los tributos son un costo: se pierden 2 Bestias y no destruís nada. Es el peor momento para recibir una negación.","en":"The Tributes are a cost: you lose 2 Beasts and destroy nothing. It is the worst moment to be negated."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse Released o la primera búsqueda del turno.","en":"On resolution of Released or the first search of the turn."},"loss":{"es":"Después de la primera búsqueda no podés usar las de Hamon, Raviel y Uria (agregan desde el Deck revelándolas): la mano queda corta.","en":"After the first search you cannot use the adds of Hamon, Raviel or Uria (they add from the Deck by revealing): the hand is short."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, cuando las Martyr y las Bestias suman la quinta invocación.","en":"During the Main Phase, when Martyrs and Beasts reach the fifth Summon."},"loss":{"es":"Con 2 Martyr extra y las Bestias invocadas por Fallen Paradise se llega rápido a cinco; Nibiru tributa la mesa que armaste.","en":"With 2 extra Martyrs and Beasts Summoned by Fallen Paradise, five arrives quickly; Nibiru Tributes the board you built."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o activación que invoca: protege cuando el rival juega su combo en el segundo turno.","en":"Negates the Summon or an activation that Special Summons: protects against the opponent's second-turn combo."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero con mesa queda muerta.","en":"Only activates with no cards on your field; going first with a board it is dead."}}]},"second":{"in":[{"card":"Triple Tactics Talent","qty":2,"why":{"es":"Se activa tras un efecto de monstruo rival en tu Main Phase: roba 2, roba el monstruo o baraja una carta de su mano.","en":"Activates after an opposing monster effect in your Main Phase: draw 2, take the monster or shuffle a card from their hand."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/branded":{"win":{"plan":"grind","pace":"medium","bullets":[{"es":"Fallen of Albaz es el motor: al invocarse, descarta 1 carta y fusiona usando monstruos de cualquiera de los dos campos, así llega a Mirrorjade the Iceblade Dragon con casi cualquier monstruo del Extra Deck rival.","en":"Fallen of Albaz is the engine: when Summoned it discards 1 card and Fusion Summons using monsters on either field, reaching Mirrorjade the Iceblade Dragon with almost any monster in the opponent's Extra Deck."},{"es":"Mirrorjade destierra un monstruo como efecto rápido, y Albion the Branded Dragon encadena otra Fusión de nivel 8 o menos al ser invocado.","en":"Mirrorjade banishes a monster as a Quick Effect, and Albion the Branded Dragon chains another Level 8 or lower Fusion when Summoned."},{"es":"Recicla recursos: Incredible Ecclesia, Blazing Cartesia y Branded in High Spirits vuelven a la mano en la End Phase si una Fusión fue al Cementerio ese turno.","en":"It recycles resources: Incredible Ecclesia, Blazing Cartesia and Branded in High Spirits return to hand in the End Phase if a Fusion went to the GY that turn."},{"es":"Una guía de YGOPRODeck advierte que no tiene respuesta propia a la zona de Mágicas/Trampas, y que Nibiru y Droll & Lock Bird le duelen menos que a otros mazos.","en":"A YGOPRODeck guide warns it has no built-in answer to the Spell/Trap zone, and that Nibiru and Droll & Lock Bird hurt it less than other decks."}]},"starters":[{"cards":["Aluber the Jester of Despia","Branded Fusion"],"route":{"es":"Aluber agrega un Mágica/Trampa Branded (Branded Fusion) y esta fusiona con materiales del Deck para llegar a Albion, Lubellion o Mirrorjade.","en":"Aluber adds a Branded Spell/Trap (Branded Fusion) and it Fusion Summons with materials from the Deck to reach Albion, Lubellion or Mirrorjade."}},{"cards":["Fallen of Albaz"],"route":{"es":"Invocado de Normal o de Especial, descarta 1 y fusiona con monstruos de ambos campos: Mirrorjade con cualquier monstruo del Extra Deck rival.","en":"Normal or Special Summoned, it discards 1 and Fusion Summons with monsters on both fields: Mirrorjade with any monster in the opponent's Extra Deck."}},{"cards":["Nadir Servant"],"route":{"es":"Manda un monstruo del Extra Deck al Cementerio y agrega Fallen of Albaz o un Dogmatika con ATK igual o menor; después no podés invocar del Extra Deck ese turno.","en":"Sends an Extra Deck monster to the GY and adds Fallen of Albaz or a Dogmatika with ATK less than or equal; you cannot Special Summon from the Extra Deck afterwards that turn."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra la búsqueda de Aluber, Nadir Servant o Branded in High Spirits.","en":"Against the add of Aluber, Nadir Servant or Branded in High Spirits."},"loss":{"es":"Sin Branded Fusion o Fallen of Albaz en mano la cadena no arranca. Tener copias extra de Fallen of Albaz y el motor Ecclesia es el plan B.","en":"Without Branded Fusion or Fallen of Albaz in hand the line does not start. Extra Albaz copies and the Ecclesia engine are plan B."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto rápido de Mirrorjade para desterrar.","en":"When Mirrorjade's Quick Effect to banish is activated."},"loss":{"es":"Niega la remoción de tu jefe principal y te deja con un cuerpo de 3000 sin efecto. Guardá Albion y su segunda fusión como alternativa.","en":"It negates your main boss's removal and leaves a 3000 body with no effect. Keep Albion and its second Fusion as an alternative."}},{"card":"Mulcharmy Fuwalos","step":"main","stepText":{"es":"En la Main Phase, cada vez que invocás del Extra Deck o el Deck.","en":"In the Main Phase, each time you Summon from the Extra Deck or Deck."},"loss":{"es":"El mazo invoca mucho de Extra Deck: el rival roba por cada una y al final de turno te obliga a barajar si tenés demasiadas cartas.","en":"The deck Summons from the Extra Deck a lot: the opponent draws for each one and you are forced to shuffle back down in the End Phase if the hand is too big."}},{"card":"Ghost Belle & Haunted Mansion","step":"activation","stepText":{"es":"Contra los efectos que recuperan o reviven desde el Cementerio (Branded in Red, Guiding Quem, Aluber).","en":"Against effects that recover or revive from the GY (Branded in Red, Guiding Quem, Aluber)."},"loss":{"es":"El mazo vive de recuperar Albaz y Despia del Cementerio; negar esa activación corta la recursión.","en":"The deck lives on recovering Albaz and Despia from the GY; negating that activation cuts the recursion."}},{"card":"Anti-Spell Fragrance","step":"main","stepText":{"es":"Cuando está en el campo: los Mágicas deben ponerse y esperar al turno siguiente.","en":"While it is on the field: Spells must be Set and wait until the next turn."},"loss":{"es":"Branded Fusion, Branded in Red y The Fallen & The Virtuous quedan un turno atrás: el mazo se queda sin su mejor inicio. Guardá cartas de remoción de Mágicas/Trampas en el Side.","en":"Branded Fusion, Branded in Red and The Fallen & The Virtuous fall a turn behind: the deck loses its best opening. Keep Spell/Trap removal in the Side."}}],"side":{"first":{"in":[{"card":"Solemn Accusation","qty":2,"why":{"es":"Niega la activación de una Mágica/Trampa, y se puede activar el turno que se pone mostrando otra Trampa boca abajo.","en":"Negates a Spell/Trap activation, and can be activated the turn it is Set by revealing another face-down Trap."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero queda muerta.","en":"Only activates with no cards on your field; going first it is dead."}}]},"second":{"in":[{"card":"Hey, Space Trunade!","qty":2,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano: ayuda contra la zona de Mágicas/Trampas que el mazo no resuelve solo.","en":"Returns up to 2 cards from the field to the hand: helps against the Spell/Trap zone the deck cannot answer itself."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/sky-striker":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Raye es la carta principal: como efecto rápido se tributa para invocar un Sky Striker Ace del Extra Deck, y vuelve sola si un Link Sky Striker es destruido en batalla o se va por un efecto rival.","en":"Raye is the main card: as a Quick Effect she Tributes to Special Summon a Sky Striker Ace from the Extra Deck, and returns if a Sky Striker Link is destroyed by battle or leaves due to an opponent's effect."},{"es":"Los Mágicas Sky Striker se potencian con 3 Mágicas en el Cementerio: Engage roba 1, Widow Anchor puede robar el control del monstruo que niega y Kagari gana 100 de ATK por cada Mágica.","en":"Sky Striker Spells scale with 3 Spells in the GY: Engage draws 1, Widow Anchor can take control of the monster it negates and Kagari gains 100 ATK per Spell."},{"es":"El motor Radiant Typhoon llena el Cementerio de Mágicas y encuentra Mystical Space Typhoon (Eldam y Swen buscan; Chant y Vision se vuelven a poner si MST las destruye).","en":"The Radiant Typhoon engine fills the GY with Spells and finds Mystical Space Typhoon (Eldam and Swen search; Chant and Vision are Set again if MST destroys them)."},{"es":"El final típico es Shizuku con 4 o 5 cartas boca abajo, y la guía oficial muestra una línea de 8000 de daño yendo segundo con Linkage y Kagari.","en":"The typical end board is Shizuku with 4 or 5 Set cards, and the official guide shows an 8000-damage line going second with Linkage and Kagari."}]},"starters":[{"cards":["Sky Striker Mobilize - Engage!"],"route":{"es":"Con las Zonas de Monstruo Principales vacías, busca cualquier carta Sky Striker y roba 1 si ya hay 3 Mágicas en el Cementerio.","en":"With your Main Monster Zones empty, adds any Sky Striker card and draws 1 if there are already 3 Spells in the GY."}},{"cards":["Sky Striker Ace - Raye","Sky Striker Mobilize - Linkage!"],"route":{"es":"Raye entra y se tributa a velocidad rápida para invocar un Ace; Linkage invoca otro Ace al Extra Monster Zone, y Kagari recupera Linkage del Cementerio.","en":"Raye comes out and Tributes at Quick Effect speed for an Ace; Linkage Special Summons another Ace to the Extra Monster Zone, and Kagari recovers Linkage from the GY."}},{"cards":["Mystical Space Typhoon","Radiant Typhoon Vision"],"route":{"es":"MST destruye tu propia Radiant Typhoon Vision, que se vuelve a poner y roba 2 cartas: llena el Cementerio de Mágicas.","en":"MST destroys your own Radiant Typhoon Vision, which Sets itself again and draws 2 cards: it fills the GY with Spells."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Sky Striker Mobilize - Engage! o la búsqueda de Eldam y Swen.","en":"Against Sky Striker Mobilize - Engage! or Eldam's and Swen's searches."},"loss":{"es":"No tenés Multirole en esta lista para hacer imparable a Engage. El Mágica igual va al Cementerio y suma para los 3, pero no buscás ni robás.","en":"This list has no Multirole to make Engage unresponsive. The Spell still goes to the GY and counts toward the 3, but you do not add or draw."}},{"card":"Droll & Lock Bird","step":"resolution","stepText":{"es":"Al resolverse la primera búsqueda del turno (Engage o Eldam).","en":"On resolution of the first search of the turn (Engage or Eldam)."},"loss":{"es":"Corta la segunda búsqueda: sin el segundo Sky Striker o el MST no se arma el Cementerio y las Mágicas se quedan con efecto sin activar.","en":"It cuts the second search: without the second Sky Striker card or MST the GY never builds and Spells stay below their bonus."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de Kagari o Zero al ser invocados (el que busca o recupera un Mágica).","en":"When Kagari's or Zero's on-Summon effect (the one that adds or recovers a Spell) is activated."},"loss":{"es":"Perdés la recuperación del Mágica; el monstruo queda de cuerpo. Contá con Raye en el Cementerio para volver si lo sacan del campo.","en":"You lose the Spell recovery; the monster is just a body. Count on Raye in the GY to come back if it is removed."}},{"card":"Anti-Spell Fragrance","step":"main","stepText":{"es":"En la Main Phase, cuando está boca arriba: los Mágicas se ponen y esperan al turno siguiente.","en":"In the Main Phase, while face-up: Spells are Set and wait until the next turn."},"loss":{"es":"Engage, Linkage y Widow Anchor ya no se activan en el momento: el mazo pierde casi toda su velocidad. Mystical Space Typhoon es la salida.","en":"Engage, Linkage and Widow Anchor can no longer be played on the spot: the deck loses most of its speed. Mystical Space Typhoon is the way out."}}],"side":{"first":{"in":[{"card":"Solemn Accusation","qty":2,"why":{"es":"Niega una Mágica o Trampa y puede activarse el turno que se pone mostrando otra Trampa boca abajo.","en":"Negates a Spell or Trap and can be activated the turn it is Set by revealing another face-down Trap."}}],"out":[{"card":"Ultimate Sky","qty":2,"why":{"es":"Pide que el rival controle más monstruos que vos, algo raro yendo primero con mesa vacía.","en":"Needs the opponent to control more monsters than you, which is rare going first with an empty board."}}]},"second":{"in":[{"card":"Harpie's Feather Duster","qty":1,"why":{"es":"Destruye todas las Mágicas/Trampas del rival: lo que el mazo no resuelve con su motor.","en":"Destroys all of the opponent's Spells/Traps: what the deck cannot handle with its own engine."}},{"card":"Hey, Space Trunade!","qty":1,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano contra una mesa ya armada.","en":"Returns up to 2 cards from the field to the hand against an already built board."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/kewl-tune":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Todo el tema son Tuners: un Kewl Tune en el campo que se use de materia Sincro puede usar un Tuner de la mano como otro material, lo que acelera la cadena de Sincros.","en":"The whole theme is Tuners: a Kewl Tune on the field used as Synchro Material can use a Tuner in hand as another material, which speeds up the chain of Synchros."},{"es":"Cue invoca un Tuner de la mano, el Deck o el Cementerio al ser invocado de Normal; Mix y Reco buscan otro Kewl Tune; Rotary mira la mano rival y busca un Mágica Kewl Tune.","en":"Cue Special Summons a Tuner from hand, Deck or GY when Normal Summoned; Mix and Reco add another Kewl Tune; Rotary looks at the opponent's hand and adds a Kewl Tune Spell."},{"es":"Kewl Tune Clip se juega en la Main Phase rival desde la mano para sincronizar un Tuner Sincro; es la forma de pelear yendo segundo.","en":"Kewl Tune Clip is played from hand in the opponent's Main Phase to Synchro Summon a Tuner Synchro; it is how the deck fights going second."},{"es":"Kewl Tune B2B da doble ataque a los Tuners y recicla un Tuner cada vez que el rival activa un efecto de monstruo; con Fydraulis Harmonia sale una OTK según YGOrganization.","en":"Kewl Tune B2B gives Tuners a second attack and recycles a Tuner each time the opponent activates a monster effect; with Fydraulis Harmonia it makes an OTK according to YGOrganization."}]},"starters":[{"cards":["Kewl Tune Mix"],"route":{"es":"Invocado, agrega otro Kewl Tune de nivel distinto de 2 (por ejemplo Cue o Reco); mandado al Cementerio como material, destruye un monstruo rival.","en":"Summoned, it adds another Kewl Tune that is not Level 2 (for example Cue or Reco); sent to the GY as material, it destroys an opposing monster."}},{"cards":["Kewl Tune Synchro"],"route":{"es":"Agrega una carta Kewl Tune del Deck y sincroniza un Tuner Sincro de inmediato; después solo podés invocar Tuners ese turno.","en":"Adds a Kewl Tune card from the Deck and Synchro Summons a Tuner Synchro right away; afterwards you can only Special Summon Tuners that turn."}},{"cards":["Kewl Tune Clip"],"route":{"es":"En la Main Phase rival se invoca desde la mano y sincroniza un Tuner Sincro: sirve para interrumpir yendo segundo.","en":"In the opponent's Main Phase it Special Summons from hand and Synchro Summons a Tuner Synchro: it interrupts going second."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra las búsquedas de Mix, Reco, Kewl Tune Synchro o Duelist Genesis, y la invocación desde el Deck de Cue u Over Tuning.","en":"Against the adds of Mix, Reco, Kewl Tune Synchro or Duelist Genesis, and the Deck Summon of Cue or Over Tuning."},"loss":{"es":"Cada Tuner depende de que otro lo busque; negar esa activación deja un solo Tuner y rompe la cadena. Tené más de un inicio en la mano.","en":"Each Tuner depends on another one fetching it; negating that activation leaves a single Tuner and breaks the chain. Keep more than one opener in hand."}},{"card":"Maxx \"C\"","step":"main","stepText":{"es":"En la Main Phase, cada vez que el mazo invoca de Especial.","en":"In the Main Phase, each time the deck Special Summons."},"loss":{"es":"La cadena de Tuners son muchas invocaciones; una reseña de torneo (Road of the King, enero 2026) cuenta que Maxx \"C\" frenó esa jugada limitando los robos.","en":"The Tuner chain is many Summons; a tournament report (Road of the King, Jan 2026) reports Maxx \"C\" stopping that play by limiting draws."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación del turno.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"Los Sincros más los Tuners llegan a cinco invocaciones enseguida; Nibiru tributa toda la mesa.","en":"Synchros plus Tuners reach five Summons quickly; Nibiru Tributes the whole board."}},{"card":"Red Reboot","step":"activation","stepText":{"es":"Cuando activás una Trampa del mazo (Kewl Tune Playlist o Infinite Impermanence).","en":"When you activate a Trap from the deck (Kewl Tune Playlist or Infinite Impermanence)."},"loss":{"es":"Niega la activación y la pone boca abajo; además no podés activar más Trampas ese turno. Playlist y Impermanence no sirven en esa vuelta.","en":"It negates the activation and Sets the card; you also cannot activate more Traps that turn. Playlist and Impermanence do nothing that round."}}],"side":{"first":{"in":[{"card":"Nibiru, the Primal Being","qty":2,"why":{"es":"Una sola carta termina el combo rival cuando junta cinco invocaciones.","en":"One card ends the opponent's combo once they reach five Summons."}}],"out":[{"card":"Effect Veiler","qty":2,"why":{"es":"Niega un solo monstruo; Nibiru limpia toda la jugada.","en":"Negates one monster; Nibiru clears the whole line."}}]},"second":{"in":[{"card":"Ultimate Sky","qty":2,"why":{"es":"Con el rival con más monstruos que vos, niega varios efectos a la vez a 800 LP cada uno.","en":"With the opponent holding more monsters than you, it negates several effects at once for 800 LP each."}}],"out":[{"card":"Ghost Ogre & Snow Rabbit","qty":2,"why":{"es":"Destruye un solo monstruo; Ultimate Sky frena más de uno por turno.","en":"Destroys a single monster; Ultimate Sky stops more than one per turn."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/maliss":{"win":{"plan":"combo","pace":"fast","bullets":[{"es":"Los monstruos Maliss desterrados vuelven pagando 300 LP, y las Trampas Maliss se pueden activar el turno que se ponen desterrando un Maliss tuyo en el campo.","en":"Banished Maliss monsters return for 300 LP, and Maliss Traps can be activated the turn they are Set by banishing a face-up Maliss monster you control."},{"es":"Sube de Link con Cyberse: Maliss Hearts Crypter (barajá un Maliss desterrado para desterrar 1 carta del campo) y White Binder, y puede seguir hasta Firewall Dragon o Transcode Talker.","en":"It Link-climbs with Cyberse: Maliss Hearts Crypter (shuffle a banished Maliss to banish 1 card on the field) and White Binder, and can continue up to Firewall Dragon or Transcode Talker."},{"es":"Maliss in Underground da 3000 de ATK a los Links Maliss con 3 Trampas Maliss distintas desterradas y obliga a los monstruos rivales a atacar solo a Links Maliss.","en":"Maliss in Underground gives Maliss Links 3000 ATK with 3 different Maliss Traps banished and forces opposing monsters to attack only Maliss Links."},{"es":"YGOPRODeck señala que Underground es inconsistente de encontrar, por eso las listas suman extensores como Backup @Ignister y Wizard @Ignister.","en":"YGOPRODeck notes Underground is inconsistent to find, which is why lists add extenders like Backup @Ignister and Wizard @Ignister."}]},"starters":[{"cards":["Terraforming","Maliss in Underground"],"route":{"es":"Terraforming busca el Field Spell Maliss in Underground; al activarlo destierra una carta Maliss de la mano, el Deck o el Cementerio y arma la mesa.","en":"Terraforming adds the Field Spell Maliss in Underground; on activation it banishes a Maliss card from hand, Deck or GY and sets the board up."}},{"cards":["Backup @Ignister","Wizard @Ignister"],"route":{"es":"Backup agrega un Cyberse DARK y descarta 1; Wizard se invoca junto a un Cyberse DARK del Cementerio si controlás un Cyberse del Extra Deck.","en":"Backup adds a DARK Cyberse and discards 1; Wizard Special Summons itself with a DARK Cyberse from the GY if you control a Cyberse from the Extra Deck."}}],"chokepoints":[{"card":"Ash Blossom & Joyous Spring","step":"activation","stepText":{"es":"Contra Backup @Ignister, Terraforming u otra búsqueda del mazo.","en":"Against Backup @Ignister, Terraforming or another search in the deck."},"loss":{"es":"Cortan el extensor que traía el Cyberse DARK. White Rabbit y las Trampas no son búsquedas, así que la mano puede seguir sin esa carta.","en":"It cuts the extender that brought the DARK Cyberse. White Rabbit and the Traps are not searches, so the hand can keep going without that card."}},{"card":"Nibiru, the Primal Being","step":"main","stepText":{"es":"En la Main Phase, tras la quinta invocación del turno.","en":"During the Main Phase, after the fifth Summon of the turn."},"loss":{"es":"Los Links y los Maliss que vuelven del destierro suman invocaciones rápido; Nibiru tributa toda la mesa de Links.","en":"Links and Maliss monsters coming back from banishment add Summons quickly; Nibiru Tributes the whole Link board."}},{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Al activarse el efecto de desterrar de Maliss Hearts Crypter.","en":"When Maliss Hearts Crypter's banish effect is activated."},"loss":{"es":"Crypter es inmune a la negación solo si apunta a un monstruo; si no, Impermanence lo frena. Apuntá a un monstruo con el Link antes de usarlo.","en":"Crypter cannot be negated only while pointing to a monster; otherwise Impermanence stops it. Make it point to a monster before using it."}},{"card":"Mulcharmy Fuwalos","step":"main","stepText":{"es":"En la Main Phase, cada vez que invocás del Extra Deck.","en":"In the Main Phase, each time you Summon from the Extra Deck."},"loss":{"es":"La subida de Links son muchas invocaciones: el rival roba por cada una. Si te frenan, quedás con menos tablero y el rival con más cartas.","en":"Link climbing is many Summons: the opponent draws for each one. If you are stopped you have less board and they have more cards."}}],"side":{"first":{"in":[{"card":"Solemn Warning","qty":2,"why":{"es":"Anula la invocación o activación que invoca: protege contra el combo rival en el segundo turno.","en":"Negates the Summon or an activation that Special Summons: protects against the opponent's second-turn combo."}}],"out":[{"card":"Mulcharmy Fuwalos","qty":2,"why":{"es":"Solo se activa sin cartas en tu campo; yendo primero con mesa queda muerta.","en":"Only activates with no cards on your field; going first with a board it is dead."}}]},"second":{"in":[{"card":"Hey, Space Trunade!","qty":2,"why":{"es":"Devuelve hasta 2 cartas del campo a la mano: ayuda contra una mesa rival ya armada.","en":"Returns up to 2 cards from the field to the hand: helps against an already built opposing board."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26"},"ocg/trirealm-rift":{"win":{"plan":"control","pace":"medium","bullets":[{"es":"Cada monstruo Trirealm Rift destierra boca abajo las primeras cartas de tu Deck al entrar (Gehenna 1, Sheol 2, Tuonela 3, Naraka 4, Yomi 5, Helheim 6, Ploutonion 7, Darkness 8) y esa pila es un segundo Deck.","en":"Each Trirealm Rift monster banishes the top cards of your Deck face-down when it comes in (Gehenna 1, Sheol 2, Tuonela 3, Naraka 4, Yomi 5, Helheim 6, Ploutonion 7, Darkness 8) and that pile works as a second Deck."},{"es":"Gehenna recupera hasta 2 monstruos desterrados boca abajo y Sheol recupera Mágicas/Trampas; Valvols y Gospel banean 5 cartas del Cementerio o del Deck para sostener la pila.","en":"Gehenna recovers up to 2 face-down banished monsters and Sheol recovers Spells/Traps; Valvols and Gospel banish 5 cards from the GY or Deck to feed the pile."},{"es":"Interactúa desde la mano y el destierro: Yomi niega un efecto de monstruo rival, Helheim se invoca como efecto rápido y Ploutonion baraja al Deck un monstruo rival del mismo Atributo.","en":"It interacts from hand and banishment: Yomi negates an opposing monster effect, Helheim Special Summons as a Quick Effect and Ploutonion shuffles an opposing monster of the same Attribute into the Deck."},{"es":"Trirealm Rift Darkness gana efectos según las cartas desterradas boca abajo: con 20 o más destruye una carta como efecto rápido, con 40 o más salta las Draw Phase.","en":"Trirealm Rift Darkness gains effects by face-down banished cards: with 20 or more it destroys a card as a Quick Effect, with 40 or more it skips Draw Phases."}]},"starters":[{"cards":["Trirealm Rift of Emptiness Gehenna","Trirealm Rift of Sky Sheol"],"route":{"es":"Gehenna se invoca de la mano sin monstruos y recupera monstruos desterrados; Sheol, invocado con un Trirealm Rift en campo, recupera Mágicas/Trampas.","en":"Gehenna Special Summons from hand with no monsters and recovers banished monsters; Sheol, Special Summoned with a Trirealm Rift on the field, recovers Spells/Traps."}},{"cards":["Trirealm Rift Territory - Valvols","Trirealm Rift Gospel"],"route":{"es":"Ambos se activan desterrando 5 cartas boca abajo del Cementerio o del Deck; Valvols agrega una carta Trirealm Rift desterrada y Gospel da una Invocación Normal extra.","en":"Both activate by banishing 5 face-down cards from the GY or Deck; Valvols adds a banished Trirealm Rift card and Gospel gives an extra Normal Summon."}},{"cards":["Mad Tempest Trirealm Rift Ploutonion"],"route":{"es":"Desde la mano, junto a otra carta Trirealm Rift, se destierran ambas boca abajo para robar 2: carga la pila y repone la mano.","en":"From hand with another Trirealm Rift card, both are banished face-down to draw 2: it loads the pile and refills the hand."}}],"chokepoints":[{"card":"Infinite Impermanence","step":"activation","stepText":{"es":"Contra Burial Summit Trirealm Rift Helheim, antes de que proteja a los demás.","en":"Against Burial Summit Trirealm Rift Helheim, before it protects the rest."},"loss":{"es":"Helheim impide que apunten o destruyan por efecto a las otras cartas Trirealm Rift, pero a él sí: quien lo niega primero deja la mesa sin escudo.","en":"Helheim stops targeting or effect destruction of your other Trirealm Rift cards, but not of itself: negating it first leaves the board without its shield."}},{"card":"Dominus Impulse","step":"summon","stepText":{"es":"Contra la invocación especial por efecto de Helheim, Naraka o Gehenna.","en":"Against the Special Summon effect of Helheim, Naraka or Gehenna."},"loss":{"es":"Anula el efecto que invoca desde el destierro. Con la pila intacta se puede reintentar con otra carta, pero se pierde la jugada del turno.","en":"It negates the effect that Special Summons from banishment. With the pile intact you can retry with another card, but the turn's play is lost."}},{"card":"Effect Veiler","step":"main","stepText":{"es":"En la Main Phase, contra Burial Summit Trirealm Rift Helheim boca arriba.","en":"In the Main Phase, against a face-up Burial Summit Trirealm Rift Helheim."},"loss":{"es":"Niega sus efectos ese turno, así que las otras cartas Trirealm Rift pierden el escudo contra efectos que apuntan o destruyen. Jugá Helheim solo cuando tengas con qué reponerlo.","en":"It negates its effects that turn, so the other Trirealm Rift cards lose their shield against targeting and destroying effects. Play Helheim only when you can replace it."}}],"side":{"first":{"in":[{"card":"Mistaken Arrest","qty":2,"why":{"es":"Nadie añade cartas del Deck a la mano por un turno; el mazo recupera desde el destierro, no del Deck.","en":"Nobody adds cards from the Deck to the hand for a turn; the deck recovers from banishment, not the Deck."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Deja pasar la primera búsqueda; Mistaken Arrest las corta todas.","en":"It lets the first search through; Mistaken Arrest stops them all."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Con Mistaken Arrest en el Side hay una forma más fiable de frenar combos.","en":"With Mistaken Arrest in the Side there is a more reliable way to stop combos."}}]},"second":{"in":[{"card":"Ultimate Sky","qty":2,"why":{"es":"Con el rival con más monstruos, niega varios efectos pagando 800 LP por cada uno.","en":"With the opponent holding more monsters, it negates several effects paying 800 LP each."}}],"out":[{"card":"Droll & Lock Bird","qty":1,"why":{"es":"Reacciona a búsquedas rivales; yendo segundo ya jugaron su turno.","en":"Reacts to opposing searches; going second they have already played."}},{"card":"Maxx \"C\"","qty":1,"why":{"es":"Rinde más antes de la jugada rival que después.","en":"Worth more before the opposing line than after."}}]},"basis":"editorial"},"updated":"2026-10-26"}});